(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("ammianus-1-b", [{"sp": "HDR", "t": "Res Gestae (Libri XIV–XIX)"}, {"sp": "HDR", "t": "Liber XIV", "st": "14"}, {"sp": "N", "t": "Post emensos insuperabilis expeditionis eventus, languentibus partium animis, quas periculorum varietas fregerat et laborum, nondum tubarum cessante clangore, vel milite locato per statiores hibernas, fortunae saevientis procellae tempestates alias rebus infudere communibus, per multa illa et dira facinora Caesaris Galli, qui ex squalore imo miseriarum, in aetatis adultae primitiis, ad principale culmen insperato saltu provectus, ultra terminos potestatis delatae procurrens, asperitate nimia cuncta foedabat. Propinquitate enim regiae stirpis, gentilitateque etiam tum Constantii nominis, efferebatur in fastus, si plus valuisset, ausurus hostilia in auctorem suae felicitatis (ut videbatur).", "st": "14.1"}, {"sp": "N", "t": "Cuius acerbitati uxor grave accesserat incentivum, germanitate Augusti turgida supra modum, quam Hanniballiano regi fratris filio antehac Constantinus iunxerat pater, Megaera quaedam mortalis, inflammatrix saevientis assidua, humani cruoris avida nihil mitius quam maritus. Qui paulatim eruditiores facti processu temporis ad nocendum, per clandestinos versutosque rumigerulos, compertis leviter addere quaedam male suetos, falsa et placentia sibi discentes, affectati regni vel artium nefandarum calumnias insontibus affigebant.", "st": "14.1"}, {"sp": "N", "t": "Eminuit autem inter humilia, supergressa iam impotentia fines mediocrium delictorum, nefanda Clematii cuiusdam Alexandrini nobilis mors repentina; cuius socrus cum misceri sibi generum, flagrans eius amore, non impetraret, ut ferebatur, per palatii pseudothyrum introducta, oblato pretioso reginae monili, id assecuta est, ut ad Honoratum, tum comitem Orienvis, formula missa letali, homo scelere nullo contactus, idem Clematius, nec hiscere nec loqui permissus, occideretur.", "st": "14.1"}, {"sp": "N", "t": "Post hoc impie perpetratum, quod in aliis quoque iam timebatur, tamquam licentia crudelitati indulta, per suspicionum nebulas aestimati quidam noxii damnabantur. Quorum pars necati alii puniti bonorum multatione, actique laribus suis extorres, nullo sibi relicto praeter querellas et lacrimas, stipe collaticia victitabant; et civili iustoque imperio ad voluntatem converso cruentam, claudebantur opulentae domus et clarae.", "st": "14.1"}, {"sp": "N", "t": "Nec vox accusatoris ulla (licet subditicii) in his malorum quaerebatur acervis, ut saltem specie tenus crimina praescriptis legum committerentur, quod aliquotiens fecere principes saevi; sed quidquid Caesaris implacabilitati sedisset, id velut fas iusque perpensum, confestim urgebatur impleri.", "st": "14.1"}, {"sp": "N", "t": "Excogitatum est super his, ut homines quidam ignoti, vilitate ipsa parum cavendi, ad colligendos rumores per Antiochiae latera cuncta destinarentur, relaturi quae audirent. Hi peragranter et dissimulanter honoratorum circulis assistendo, pervadendoque divites domus egentium habitu, quicquid noscere poterant vel audire, latenter intromissi per posticas in regiam, nuntiabant, id observantes conspiratione concordi, ut fingerent quaedam, et cognita duplicarent in peius, laudes vero supprimerent Caesaris, quas invitis compluribus formido malorum impendentium exprimebat.", "st": "14.1"}, {"sp": "N", "t": "Et interdum acciderat, ut siquid in penetrali secreto, nullo citerioris vitae ministro praesente, paterfamilias uxori susurrasset in aurem, velut Amphiarao referente aut Marcio, quondam vatibus inclitis, postridie disceret imperator. Ideoque etiam parites arcanorum soli conscii timebantur.", "st": "14.1"}, {"sp": "N", "t": "adolescebat autem obstinatum propositum erga haec et similia multa scrutandi, stimulos admovente regina, quae abrupte mariti fortunas trudebat in exitium praeceps, cum eum potius lenitate feminea ad veritatis humanitatisque viam reducere utilia suadendo deberet, ut in Gordianorum actibus factitasse Maximini truculenti illius imperatoris retulimus coniugem.", "st": "14.1"}, {"sp": "N", "t": "Novo denique perniciosoque exemplo, idem Gallus ausus est inire flagitium grave, quod Romae cum ultimo dedecore temptasse aliquando dicitur Gallienus, et adhibitis paucis clam ferro succinctis, vesperi per tabernas palabatur et compita, quaeritando Graeco sermone, cuius erat impendio gnarus, quid de Caesare quisque sentiret. Et haec confidenter agebat in urbe, ubi pernoctantium luminum claritudo dierum solet imitari fulgorem. Postremo agnitus saepe, iamque (si prodisset) conspicuum se fore contemplans, non nisi luce palam egrediens ad agenda quae putabat seria cernebatur. Et haec quidem medullitus multis gementibus agebantur.", "st": "14.1"}, {"sp": "N", "t": "Thalassius vero ea tempestate praefectus praetorio praesens, ipse quoque arrogantis ingenii, considerans incitationem eius ad multorum augeri discrimina, non maturitate vel consiliis mitigabat, ut aliquotiens celsae potestates iras principum molliverunt, sed adversando iurgandoque cum parum congrueret, eum ad rabiem potius evibrabat, Augustum actus eius exaggerando creberrime docens, idque (incertum qua mente) ne lateret affectans. Quibus mox Caesar acrius efferatus, velut contumaciae quoddam vexillum altius erigens, sine respectu salutis alienae vel suae, ad vertenda opposita, instar rapidi fluminis, irrevocabili impetu ferebatur.", "st": "14.1"}, {"sp": "N", "t": "Nec sane haec sola pernicies orientem diversis cladibus affligebat. Namque et Isauri, quibus est usitatum saepe pacari, saepeque inopinis excursibus cuncta miscere, ex latrociniis occultis et raris, alente impunitate adulescentem in peius audaciam, ad bella gravia proruperunt, diu quidem perduelles spiritus irrequietis motibus erigentes, hac tamen indignitate perciti vehementer, ut iactitabant, quod eorum capti quidam consortes, apud Iconium Pisidiae oppidum in amphitheatrali spectaculo feris praedatricibus obiecti sunt praeter morem.", "st": "14.2"}, {"sp": "N", "t": "Atque (ut Tullius ait) ut etiam bestiae fame monitae plerumque ad cum locum ubi aliquando pastae sunt revertuntur, ita omnes instar turbinis degressi montibus impeditus et arduis, loca petivere mari confinia, per quae viis latebrosis sese convallibusque occultantes, mm appeterent noctes—luna etiam tum cornuta, ideoque nondum solido splendore fulgente—nauticos observabant. Quos cum in somnum sentirent effusos, per ancoralia quadrupedo gradu repentes, seseque suspensis passibus iniectantes in scaphas, eisdem nihil opinantibus assistebant, et incendente aviditate saevitiam, ne cedentium quidem ulli parcendo, obtruncatis omnibus merces opimas vel utiles nullis repugnantibus avertebant.", "st": "14.2"}, {"sp": "N", "t": "Haecque non diu sunt perpetrata. Cognitis enim pilatorum caesorumque funeribus, nemo deinde ad has stationes appulit navem, sed ut Scironis praerupta letalia declinantes, litoribus Cypriis contigui navigabant, quae Isauriae scopulis sunt controversa.", "st": "14.2"}, {"sp": "N", "t": "Procedente igitur mox tempore cum adventicium nihil inveniretur, relicta ora maritima, in Lycaoniam annexam Isauriae se contulerunt, ibique densis intersaepientes itinera praetenturis, provincialium et viatorum opibus pascebantur.", "st": "14.2"}, {"sp": "N", "t": "Excitavit hic ardor milites per municipia plurima, quae eisdem conterminant, dispositos et castella, et quisque serpentes latius pro viribus repellere moliens, nunc globis confertos, aliquotiens et dispersos, multitudine superabatur vigenti, quae nata et educata inter editos recurvosque ambitus montium, eos ut loca plana persultat et mollia, missilibus obvios eminus lacessens et ululatu truci perterrens.", "st": "14.2"}, {"sp": "N", "t": "Coactique aliquotiens nostri pedites ad eos persequendos scandere clivos sublimes, etiam si lapsantibus plantis fruticeta prensando vel dumos, ad vertices venerint summos, inter arta tamen et invia, nullas acies explicare permissi, r.ec firmare nisu valido gressus; hoste discursatore rupium abscisa volvente superne, periculose per prona discedunt, aut ex necessitate ultima fortiter dimicantes, ruinis ponderum immanium consternuntur.", "st": "14.2"}, {"sp": "N", "t": "Quam ob rem circumspecta cautela observatum est deinceps, et cum edita montium petere coeperint grassatores, loci iniquitati milites cedunt. Ubi autem in planitie potuerint reperiri, quod contingit assidue, nec exsertare lacertos nec crispare permissi tela quae vehunt bina vel terna, pecudum ritu inertium trucidantur.", "st": "14.2"}, {"sp": "N", "t": "Metuentes igitur idem latrones Lycaoniam magna parte campestrem, cum se impares nostris fore congressione stataria documentis frequentibus scirent, tramitibus deviis petivere Pamphyliam, diu quidem intactam, sed timore populationum et caedum, milite per omnia diffuso propinqua, magnis undique praesidiis communitam.", "st": "14.2"}, {"sp": "N", "t": "Raptim igitur properantes, ut motus sui rumores celeritate nimia praevenirent, vigore corporum ac levitate confisi, per flexuosas semitas ad summitates collium tardius evadebant. Et cum, superatis difficultatibus arduis, ad supercilia venissent fluvii Melanis, alti et verticosi, qui pro muro tuetur accolas circumfusus, augente nocte adulta terrorem, quievere paulisper, lucem opperientes. Arbitrabantur enim nullo impediente transgressi, inopino accursu apposita quaeque vastare, sed in cassum labores pertulere gravissimos.", "st": "14.2"}, {"sp": "N", "t": "Nam sole orto magnitudine angusti gurgitis sed profundi a transitu arcebantur, et dum piscatorios quaerunt lenunculos, vel innare temere contextis cratibus parant, effusae legiones quae hiemabant tunc apud Siden, eisdem impetu occurrere veloci. Et signis prope ripam locatis, ad manus comminus conserendas, denseta scutorum compage, semet scientissime praestruebant, ausos quoque aliquos fiducia nandi, vel cavatis arborum truncis, amnem permeare latenter, facillime trucidarunt.", "st": "14.2"}, {"sp": "N", "t": "Unde temptatis ad discrimen ultimum artibus militum, cum nihil impetraretur, pavore vique repellente extrusi, et quo tenderent ambigentes, venere prope oppidum Laranda.", "st": "14.2"}, {"sp": "N", "t": "Ibi victu recreati et quiete, postquam abierat timor, vicos opulentos adorti, equestrium adiumento cohortium, quae casu propinquabant, nec resistere planitie porrecta conati, digressi sunt, retroque cedentes, omne iuventutis robur relictum in sedibus acciverunt.", "st": "14.2"}, {"sp": "N", "t": "Et quoniam inedia gravi afflictabantur, locum petivere Paleas nomine, vergentem in mare, valido muro firmatum, ubi conduntur nunc usque commeatus, distribui militibus omne latus Isauriae defendentibus assueti. Circumstetere igitur hoc munimentum per triduum et trinoctium, et cum neque acclivitas ipsa sine discrimine posset adiri letali, nec cuniculis quicquam geri, nec procedebat ullam obsidionale commentum, maesti excedunt, postrema vi subigente maiora viribus aggressuri.", "st": "14.2"}, {"sp": "N", "t": "Proinde concepta rabie saeviore, quam desperatio incendebat et fames, amplificatis viribus, ardore incohibili in excidium urbium matris Seleuciae efferebantur, quam comes tuebatur Castricius, tresque legiones bellicis sudoribus induratae.", "st": "14.2"}, {"sp": "N", "t": "Horum adventum praedocti speculationibus fidis, rectores militum tessera data sollemni, armatos omnes celeri eduxere procursu, et agiliter praeterito Calycadni fluminis ponte, cuius undarum magnitudo murorum alluit turres, in speciem locavere pugnandi. Neque tamen exsiluit quisquam, nec permissus est congredi. Formidabatur enim flagrans vesania manus, et superior numero, et ruitura sine respectu salutis in ferrum.", "st": "14.2"}, {"sp": "N", "t": "Viso itaque exercitu procul, auditoque liticinum cantu, represso gradu parumper stetere praedones, exsertantesque minaces gladios postea lentius incedebant.", "st": "14.2"}, {"sp": "N", "t": "Quibus occurrere bene pertinax miles explicatis ordinibus parans, hastisque feriens scuta, qui habitus iram pugnantium concitat et dolorem, proximos iam gestu terrebat. Sed eum in certamen alacriter consurgentem, revocavere ductores, rati intempestivum anceps subire certamen, cum haut longe muri distarent, quorum tutela securitas poterat in solido locari cunctorum.", "st": "14.2"}, {"sp": "N", "t": "Hac ita persuasione reducti intra moenia bellatores, obseratis undique portarum aditibus, propugnaculis insistebant et pinnis, congesta undique saxa telaque habentes in promptu, ut si quis se proripuisset citerius, multitudine missilium sterneretur et lapidum.", "st": "14.2"}, {"sp": "N", "t": "Illud tamen clausos vehementer angebat, quod captis navigiis, quae frumenta vehebant per flumen, Isauri quidem alimentorum copiis affluebant, ipsi vero solitarum rerum cibo iam consumendo, inediae propinquantis aerumnas exitialis horrebant.", "st": "14.2"}, {"sp": "N", "t": "Haec ubi latius fama vulgasset, missaeque relationes assiduae Gallum Caesarem permovissent, quoniam magister equitum longius ea tempestate distinebatur, iussus comes Orientis Nebridius, contractis undique militaribus copiis, ad eximendam periculo civitatem amplam et opportunam, studio properabat ingenti. Quo cognito abscessere latrones, nulla re amplius memorabili gesta, dispersique (ut solent,) avia montium petiere celsorum.", "st": "14.2"}, {"sp": "N", "t": "Eo adducta re per Isauriam, rege Persarum bellis finitimis illigato, repellenteque a collimitiis suis ferocissimas gentes, quae mente quadam versabili hostiliter eum saepe incessunt, et in nos arma moventem aliquotiens iuvant, Nohodares quidam nomine e numero optimatum, incursare Mesopotamiam quotiens copia dederit ordinatus, explorabat nostra sollicite, si repperisset usquam locum, vi subita perrupturus.", "st": "14.3"}, {"sp": "N", "t": "Et quia Mesopotamiae tractus omnes crebro inquietari sueti, praetenturis et stationibus servabantur agrariis, laevorsum flexo itinere, Osdroenae subsederat extimas partes, novum parumque aliquando temptatum commentum aggressus; quod si impetrasset, fulminis modo cuncta vastarat. Erat autem quod cogitabat huius modi.", "st": "14.3"}, {"sp": "N", "t": "Batnae municipium in Anthemusia conditum Macedonum manu priscorum, ab Euphrate flumine brevi spatio disparatur, refertum mercatoribus opulentis, ubi annua sollemnitate prope Septembris initium mensis, ad nundinas magna promiscuae fortunae convenit multitudo, ad commercanda quae Indi mittunt et Seres, aliaque plurima vehi terra marique consueta.", "st": "14.3"}, {"sp": "N", "t": "Hanc regionem praestitutis celebritati diebus, invadere parans dux ante dictus, per solitudines Aboraeque amnis herbidas ripas, suorum indicio proditus, qui admissi flagitii metu exagitati, ad praesidia descivere Romana, absque ullo egressus effectu, deinde tabescebat immobilis.", "st": "14.3"}, {"sp": "N", "t": "Saraceni tamen nec amici nobis umquam nec hostes optandi, ultro citroque discursantes, quicquid inveniri poterat momento temporis parvi vastabant, milvorum rapacium similes, qui si praedam dispexerint celsius, volatu rapiunt celeri, ac si impetraverint, non immorantur.", "st": "14.4"}, {"sp": "N", "t": "Super quorum moribus licet in actibus principis Marci, et postea aliquotiens memini rettulisse, tamen nunc quoque pauca de eisdem expediam carptim.", "st": "14.4"}, {"sp": "N", "t": "Apud has gentes, quarum exordiens initium ab Assyriis, ad Nili cataractas porrigitur, et confinia Blemmyarum, omnes pari sorte sunt bellatores, seminudi coloratis sagulis pube tenus amicti, equorum adiumento pernicium graciliumque camelorum per diversa reptantes, in tranquillis vel turbidis rebus; nec eorum quisquam aliquando stivam apprehendit, vel arborem colit, aut arva subigendo quaeritat victum, sed errant semper per spatia longe lateque distenta, sine lare sine sedibus fixis aut legibus; nec idem perferunt diutius caelum, aut tractus unius sol illis umquam placet.", "st": "14.4"}, {"sp": "N", "t": "Vita est illis semper in fuga, uxoresque mercennariae conductae ad tempus ex pacto, atque (ut sit species matrimonii,) dotis nomine futura coniunx hastam et tabernaculum offert marito, post statum diem (si id elegerit,) discessura, et incredibile est quo ardore apud eos in venerem uterque solvitur sexus.", "st": "14.4"}, {"sp": "N", "t": "Ita autem quoad vixerint late palantur, ut alibi mulier nubat, in loco pariat alio, liberosque procul educat, nulla copia quiescendi permissa.", "st": "14.4"}, {"sp": "N", "t": "Victus universis caro fe ina est, lactisque abundans copia qua sustentantur, et herbae multiplices, et siquae alites capi per aucupium possint, et plerosque nos vidimus frumenti usum et vini penitus ignorantes.", "st": "14.4"}, {"sp": "N", "t": "Hactenus de natione perniciosa. Nunc ad textum propositum revertamur.", "st": "14.4"}, {"sp": "N", "t": "Dum haec in Oriente aguntur, Arelate hiemem agens Constantius, post theatralis ludos atque circenses ambitioso editos apparatu, diem sextum: idus Octobres, qui imperii eius annum tricensimum terminabat, insolentiae pondera gravius librans, siquid dubium deferebatur aut falsum, pro liquido accipiens et comperto, inter alia excarnificatum Gerontium, Magnentianae comitem partis, exsulari maerore multavit.", "st": "14.5"}, {"sp": "N", "t": "Utque aegrum corpus quassari etiam levibus solet offensis, ita animus eius angustus et tener, quicquid increpuisset, ad salutis suae dispendium existimans factum aut cogitatum, insontium caedibus fecit victoriam luctuosam.", "st": "14.5"}, {"sp": "N", "t": "Siquis enim militarium vel honoratorum aut nobilis inter suos, rumore tenus esset insimulatus fovisse partes hostiles, iniecto onere catenarum, in modum beluae trahebatur, et inimico urgente vel nullo, quasi sufficiente hoc solo, quod nominatus esset aut delatus aut postulatus, capite vel multatione bonorum, aut insulari solitudine damnabatur.", "st": "14.5"}, {"sp": "N", "t": "Accedebant enim eius asperitati, ubi inminuta esse amplitudo imperii dicebatur, et iracundiae suspicionumque vanitati, proximorum cruentae blanditiae, exaggerantium incidentia, et dolere impendio simulantium, si principis petitur vita, a cuius salute velut filo pendere statum orbis terrarum fictis vocibus exclamabant.", "st": "14.5"}, {"sp": "N", "t": "Ideoque fertur neminem aliquando ob haec vel similia poenae addictum, oblato de more elogio, revocari iussisse, quod inexorabiles quoque principes factitarunt. Et exitiale hoc vitium, quod in aliis non numquam intepescit, in illo aetatis progressu effervescebat, obstinatum eius propositum accendente adulatorum cohorte.", "st": "14.5"}, {"sp": "N", "t": "Inter quos Paulus eminebat notarius, ortus in Hispania coluber quidam sub vultu latens, odorandi vias periculorum occultas perquam sagax. Is in Britanniam missus, ut militares quosdam perduceret, ausos conspirasse Magnentio, cum reniti non possent, iussa licentius supergressus, fluminis modo fortunis complurium sese repentinus infudit, et ferebatur per strages multiplices ac ruinas, vinculis membra ingenuorum affligens, et quosdam obterens manicis, crimina scilicet multa consarcinando, a veritate longe discreta. Unde admissum est facinus impium, quod Constanti tempus nota inusserat sempiterna.", "st": "14.5"}, {"sp": "N", "t": "Martinus agens illas provincias pro praefectis, aerumnas innocentium graviter gemens, saepeque obsecrans, ut ab omni culpa immunibus parceretur, cum non impetraret, minabatur se discessurum; ut saltem id metuens, perquisitor malivolus tandem desineret quieti coalitos homines in aperta pericula proiectare.", "st": "14.5"}, {"sp": "N", "t": "Per hoc minui studium suum existimans Paulus, ut erat in complicandis negotiis artifex dirus, unde ei Catenae indutum est cognomentum, vicarium ipsum eos quibus praeerat adhuc defensantem, ad sortem periculorum communium traxit. Et instabat ut eum quoque cum tribunis et aliis pluribus, ad comitatum imperatoris vinctum perduceret; quo percitus ille, exitio urgente abrupto, ferro eundem adoritur Paulum. Et quia languente dextera letaliter ferire non potuit, iam destrictum mucronem in proprium latus impegit. hocque deformi genere mortis, excessit e vita iustissimus rector, ausus miserabiles casus levare multorum.", "st": "14.5"}, {"sp": "N", "t": "Quibus ita sceleste patratis, Paulus cruore perfusus, reversusque ad principis castra, multos coopertos paene catenis adduxit, in squalorem deiectos atque maestitiam, quorum adventu intendebantur eculei, uncosque parabat carnifex et tormenta. Et ex his proscripti sunt plures, actique in exsilium alii, non nullos gladii consumpsere poenales. Nec enim quisquam facile meminit sub Constantio, ubi susurro tenus haec movebantur, quemquam absolutum.", "st": "14.5"}, {"sp": "N", "t": "Inter haec Orfitus praefecti potestate regebat urbem aeternam, ultra modum delatae dignitatis sese efferens insolenter, vir quidem prudens, et forensium negotiorum oppido gnarus, sed splendore liberalium doctrinarum minus quam nobilem de, uerat institutus. Quo administrante seditiones sunt concitatae graves ob inopiam vini, cuius avidis usibus vulgus intentum, ad motus asperos excitatur et crebros.", "st": "14.6"}, {"sp": "N", "t": "Et quoniam mirari posse quosdam peregrinos existimo, haec lecturos forsitan (si contigerit), quam ob rem cum oratio ad ea monstranda deflexerit quae Romae geruntur, nihil praeter seditiones narrator et tabernas et vilitates harum similis alias, summatim causas perstringam, nusquam a veritate sponte propria digressurus.", "st": "14.6"}, {"sp": "N", "t": "Tempore quo primis auspiciis in mundanum fulgorem surgeret victura dum erunt homines Roma, ut augeretur sublimibus incrementis, foedere pacis aeternae Virtus convenit atque Fortuna, plerumque dissidentes, quarum si altera defuisset, ad perfectam non venerat summitatem.", "st": "14.6"}, {"sp": "N", "t": "Eius populus ab incunabulis primis ad usque pueritiae tempus extremum, quod annis circumcluditur fere trecentis, circummurana pertulit bella; deinde aetatem ingressus adultam, post multiplices bellorum aerumnas, Alpes transcendit et fretum; in iuvenem erectus et virum, ex omni plaga quam orbis ambit immensus, reportavit laureas et triumphos; iamque vergens in senium, et nomine solo aliquotiens vincens, ad tranquilliora vitae discessit.", "st": "14.6"}, {"sp": "N", "t": "Ideo urbs venerabilis, post superbas efferatarum gentium cervices oppressas, latasque leges, fundamenta libertatis et retinacula sempiterna, velut frugi parens et prudens et dives, Caesaribus tamquam liberis suis regenda patrimonii iura permisit.", "st": "14.6"}, {"sp": "N", "t": "Et olim licet otiosae sint tribus, pacataeque centuriae, et nulla suffragiorum certamina, sed Pompiliani redierit securitas temporis, per omnes tamen quot orae sunt partesque terrarum, ut domina suscipitur et regina, et ubique patrum reverenda cum auctoritate canities, populique Romani nomen circumspectum et verecundum.", "st": "14.6"}, {"sp": "N", "t": "Sed laeditur hic coetuum magnificus splendor, levitate paucorum incondita, ubi nati sunt non reputantium, sed tamquam indulta licentia vitiis, ad errores lapsorum atque lasciviam. Ut enim Simonides lyricus docet, beate perfecta ratione victuro, ante alia patriam esse convenit gloriosam.", "st": "14.6"}, {"sp": "N", "t": "Ex his quidam aeternitati se commendari posse per statuas aestimantes, eas ardenter affectant, quasi plus praemii de figmentis aereis sensu carentibus adepturi, quam ex conscientia honeste recteque factorum, easque auro curant inbracteari, quod Acilio Glabrioni delatum est primo, cum consiliis armisque regem superasset Antiochum. Quam autem sit pulchrum, exigua haec spernentem et minima, ad ascensus verae gloriae tendere longos et arduos, ut memorat vates Ascraeus, Censorius Cato monstravit. Qui interrogatus quam ob rem inter multos ipse statuam non haberet, “Malo” inquit “ambigere bonos, quam ob rem id non meruerim, quam (quod est gravius) cur impetraverim mussitare.”", "st": "14.6"}, {"sp": "N", "t": "Alii summum decus in carruchis solito altioribus, et ambitioso vestium cultu ponentes, sudant sub ponderibus lacernarum, quas in collis insertas iugulis ipsis annectunt, nimia subtegminum tenuitate perflabiles, exceptantes eas manu utraque et vexantes crebris agitationibus, maximeque sinistra, ut longiores fimbriae tunicaeque perspicue luceant, varietate liciorum effigiatae in species animalium multiformes.", "st": "14.6"}, {"sp": "N", "t": "Alii nullo quaerente, vultus severitate assimulata, patrimonia sua in immensum extollunt, cultorum (ut putant) feracium multiplicantes annuos fructus, quae a primo ad ultimum solem se abunde iactitant possidere, ignorantes profecto maiores suos per quos ita magnitudo Romana porrigitur, non divitiis eluxisse, sed per bella saevissima, nec opibus nec victu nec indumentorum vilitate gregariis militibus discrepantes, opposita cuncta superasse virtute.", "st": "14.6"}, {"sp": "N", "t": "Hac ex causa collaticia stipe Valerius humatur ille Publicola, et subsidiis amicorum mariti, inops cum liberis uxor alitur Reguli, et dotatur ex aerario filia Scipionis, cum nobilitas florem adultae virginis diuturnum absentia pauperis erubesceret patris.", "st": "14.6"}, {"sp": "N", "t": "At nunc si ad aliquem bene nummatum tumentemque ideo, honestus advena salutatum introieris primitus, tamquam exoptatus suscipieris, et interrogatus multa coactusque mentiri, miraberis numquam antea visus, summatem virum tenuem te sic enixius observantem, ut paeniteat ob haec bona tamquam praecipua non vidisse ante decennium Romam.", "st": "14.6"}, {"sp": "N", "t": "Hacque affabilitate confisus, cum eadem postridie feceris, ut incognitus haerebis et repentinus, hortatore illo hesterno suos enumerando, qui sis vel unde venias diutius ambigente. Agnitus vero tandem et asscitus in amicitiam, si te salutandi assiduitati dederis triennio indiscretus, et per totidem dierum defueris tempus, reverteris ad paria perferenda, nec ubi esses interrogatus, et ni inde miser discesseris, aetatem omnem frustra in stipite conteres summittendo.", "st": "14.6"}, {"sp": "N", "t": "Cum autem commodis intervallata temporibus, convivia longa et noxia coeperint apparari, vel distributio sollemnium sportularum, anxia deliberatione tractatur, an exceptis his quibus vicissitudo debetur, peregrinum invitari conveniet, et si digesto plene consilio, id placuerit fieri, is adhibetur qui pro domibus excubat aurigarum, aut artem tesserariam profitetur, aut secretiora quaedam se nosse confingit.", "st": "14.6"}, {"sp": "N", "t": "Homines enim eruditos et sobrios, ut infaustos et inutiles vitant, eo quoque accedente, quod et nomenclatores, assueti haec et talia venditare, mercede accepta, lucris quosdam et prandiis inserunt subditicios ignobiles et obscure.", "st": "14.6"}, {"sp": "N", "t": "Mensarum enim voragines et varias voluptatum illecebras, ne longius progrediar, praetermitto, illuc transiturus, quod quidam per ampla spatia urbis, subversasque silices, sine periculi metu properantes equos velut publicos, ignitis quod dicitur calcibus agitant, familiarium agmina tamquam praedatorios globos post terga trahentes, ne Sannione quidem (ut ait comicus) domi relicto. Quos imitatae matronae complures, opertis capitibus et basternis, per latera civitatis cuncta discurrunt.", "st": "14.6"}, {"sp": "N", "t": "Utque proeliorum periti rectores primo catervas densas opponunt et fortes, deinde leves armaturas, post iaculatores ultimasque subsidiales acies (si fors adegerit) iuvaturas, ita praepositis urbanae familiae suspense digerentibus atque sollicite, quos insignes faciunt virgae dexteris aptatae, velut tessera data castrensi, iuxta vehiculi frontem omne textrinum incedit: huic atratum coquinae iungitur ministerium, dein totum promisce servitium, cum otiosis plebeis de vicinitate coniunctis; postrema multitudo spadonum a senibus in pueros desinens, obluridi distortaque lineamentorum compage deformes, ut quaqua incesserit quisquam, cernens mutilorum hominum agmina, detestetur memoriam Samiramidis reginae illius veteris, quae teneros mares castravit omnium prima, velut vim iniectans naturae, eandemque ab instituto cursu retorquens, quae inter ipsa oriundi crepundia, per primigenios seminis fontes, tacita quodam modo lege vias propagandae posteritatis ostendit.", "st": "14.6"}, {"sp": "N", "t": "Quod cum ita sit, paucae domus studiorum seriis cultibus antea celebratae, nunc ludibriis ignaviae torpentis exundant, vocabili sonu, perflabili tinnitu fidium resultantes. Denique pro philosopho cantor, et in locum oratoris doctor artium ludicrarum accitur, et bibliothecis sepulcrorum ritu in perpetuum clausis, organa fabricantur hydraulica, et lyrae ad speciem carpentorum ingentes, tibiaeque et histrionici gestus instrumenta non levia.", "st": "14.6"}, {"sp": "N", "t": "Postremo ad id indignitatis est ventum, ut cum peregrini ob formidatam haud ita dudum alimentorum inopiam pellerentur ab urbe praecipites, sectatoribus disciplinarum liberalium, impendio paucis, sine respiratione ulla extrusis, tenerentur mimarum adseclae veri, quique id simularunt ad tempus, et tria milia saltatricum, ne interpellata quidem, cum choris totidemque remanerent magistris.", "st": "14.6"}, {"sp": "N", "t": "Et licet, quocumque oculos flexeris, feminas affatim multas spectare cirratas, quibus (si nupsissent) per aetatem ter iam nixus poterat suppetere liberorum, ad usque taedium pedibus pavimenta tergentis, iactari volucriter gyris, dum exprimunt innumera simulacra, quae finxere fabulae theatrales.", "st": "14.6"}, {"sp": "N", "t": "Illud autem non dubitatur, quod cum esset aliquando virtutum omnium domicilium Roma, ingenuos advenas plerique nobilium, ut Homerici bacarum suavitate Lotophagi, humanitatis multiformibus officiis retentabant.", "st": "14.6"}, {"sp": "N", "t": "Nunc vero inanes flatus quorundam, vile esse quicquid extra urbis pomerium nascitur aestimant praeter orbos et caelibes, nec credi potest qua obsequiorum diversitate coluntur homines sine liberis Romae.", "st": "14.6"}, {"sp": "N", "t": "Et quoniam apud eos, ut in capite mundi, morborum acerbitates celsius dominantur, ad quos vel sedandos omnis professio medendi torpescit, excogitatum est adminiculum sospitale, nequi amicum perferentem similia videat, additumque est cautioribus paucis remedium aliud satis validum, ut famulos percontatum missos quem ad modum valeant noti hac aegritudine colligati, non ante recipiant domum, quam lavacro purgaverint corpus. Ita etiam alienis oculis visa metuitur labes.", "st": "14.6"}, {"sp": "N", "t": "Sed tamen haec cum ita tutius observentur, quidam vigore artuum imminuto, rogati ad nuptias, ubi aurum dextris manibus cavatis offertur, impigre vel usque Spoletium pergunt. Haec nobilium sunt instituta.", "st": "14.6"}, {"sp": "N", "t": "Ex turba vero imae sortis et paupertinae, in tabernis aliqui pernoctant vinariis, non nulli sub velabris umbraculorum theatralium latent, quae, Campanam imitatus lasciviam, Catulus in aedilitate sua suspendit omnium primus; aut pugnaciter aleis certant, turpi sono fragosis naribus introrsum reducto spiritu concrepantes; aut quod est studiorum omnium maximum ab ortu lucis ad vesperam sole fatiscunt vel pluviis, per minutias aurigarum equorumque praecipua vel delicta scrutantes.", "st": "14.6"}, {"sp": "N", "t": "Et est admodum mirum videre plebem innumeram, mentibus ardore quodam infuso, e dimicationum curulium eventu pendentem. Haec similiaque memorabile nihil vel serium agi Romae permittunt. Ergo redeundum ad textum.", "st": "14.6"}, {"sp": "N", "t": "Latius iam disseminata licentia, onerosus bonis omnibus Caesar, nullum post haec adhibens modum, orientis latera cuncta vexabat, nec honoratis parcens nec urbium primatibus nec plebeis.", "st": "14.7"}, {"sp": "N", "t": "Denique Antiochensis ordinis vertices sub uno elogio iussit occidi, ideo efferatus, quod ei celerari vilitatem intempestivam urgenti, cum impenderet inopia, gravius rationabili responderunt; et perissent ad unum, ni comes orientis tunc Honoratus fixa constantia restitisset.", "st": "14.7"}, {"sp": "N", "t": "Erat autem diritatis eius hoc quoque indicium nec obscurum nec latens, quod ludicris cruentis delectabatur, et in circo sex vel septem aliquotiens deditus certaminibus, pugilum vicissim se concidentium, perfusorumque sanguine specie, ut lucratus ingentia, laetabatur.", "st": "14.7"}, {"sp": "N", "t": "Accenderat super his incitatum propositum ad nocendum aliqua mulier vilis, quae ad palatium (ut poposcerat) intromissa, insidias ei latenter obtendi prodiderat a militibus obscurissimis. Quam Constantina exultans, ut in tuto iam locata mariti salute, muneratam vehiculoque impositam per regiae ianuas emisit in publicum, ut his illecebris alios quoque ad indicanda proliceret paria vel maiora.", "st": "14.7"}, {"sp": "N", "t": "Post haec Gallus Hierapolim profecturus, ut expeditioni specie tenus adesset, Antiochensi plebi suppliciter obsecranti, ut inediae dispelleret metum, quae per multas difficilisque causas affore iam sperabatur, non ut mos est principibus, quorum diffusa potestas localibus subinde medetur aerumnis, disponi quicquam statuit, vel ex provinciis alimenta transferri conterminis, sed consularem Syriae Theophilum prope adstantem, ultima metuenti multitudini dedit, id assidue replicando, quod invito rectore, nullus egere poterit victu.", "st": "14.7"}, {"sp": "N", "t": "Auxerunt haec vulgi sordidioris audaciam; et cum ingravesceret penuria commeatuum, famis et furoris impulsu, Eubuli cuiusdam inter suos clari domum ambitiosam ignibus subditis inflammavit, rectoremque ut sibi iudicio imperiali addictum, calcibus incessens et pugnis, conculcans seminecem laniatu miserando discerpsit. Post cuius lacrimosum interitum, in unius exitio quisque imaginem periculi sui considerans, documento recenti similia formidabat.", "st": "14.7"}, {"sp": "N", "t": "Eodem tempore Serenianus ex duce, cuius ignavia populatam in Phoenice Celsen ante rettulimus, pulsatae maiestatis imperii reus iure postulatus ac lege, incertum qua potuit suffragatione absolui, aperte convictus, familiarem suum cum pileo quo caput operiebat, incantato vetitis artibus, ad templum misisse fatidicum, quaeritatum praesagia, an ei firmum portenderetur imperium (ut cupiebat) et tutum.", "st": "14.7"}, {"sp": "N", "t": "Duplexque eisdem diebus acciderat malum, quod et Theophilum insontem atrox interceperat casus, et Serenianus dignus execratione cunctorum, innoxius, modo non reclamante publico vigore, discessit.", "st": "14.7"}, {"sp": "N", "t": "Haec subinde Constantius audiens, et quaedam referente Thalassio doctus, quem obisse iam compererat lege communi, scribens ad Caesarem blandius, adiumenta paulatim illi subtraxit, sollicitari se simulans ne, uti est militare otium fere tumultuosum, in eius perniciem conspiraret, solisque scholis iussit esse contentum palatinis et protectorum, cum Scutariis et Gentilibus, et mandabat Domitiano, ex comite largitionum praefecto provecto, ut cum in Syriam venerit, Gallum quem crebro acciverat, ad Italiam properare blande hortaretur et verecunde.", "st": "14.7"}, {"sp": "N", "t": "Qui cum venisset ob haec festinatis itineribus Antiochiam, praestrictis palatii ianuis, contempto Caesare quem videri decuerat, ad praetorium cum pompa sollemni perrexit, morbosque diu causatus, nec regiam introiit, nec processit in publicum, sed abditus multa in eius moliebatur exitium, addens quaedam relationibus supervacua, quas subinde mittebat ad principem.", "st": "14.7"}, {"sp": "N", "t": "Rogatus ad ultimum, admissusque in consistorium, ambage nulla praegressa, inconsiderate et leviter,“Proficiscere” inquit (ut praeceptum est) “Caesar, sciens quod (si cessaveris) et tuas et palatii tui auferri iubebo prope diem annonas.” Hocque solo contumaciter dicto, subiratus abscessit, nec in conspectum eius postea venit, saepius arcessitus.", "st": "14.7"}, {"sp": "N", "t": "Hinc ille commotus, ut iniusta perferens et indigna, praefecti custodiam protectoribus mandaverat fidis. Quo conperto Montius tune quaestor, acer quidem sed ad lenitatem propensior, consulens in commune, advocatos palatinarum primos scholarum allocutus est mollius, docens nec decere haec fieri nec prodesse, addensque vocis obiurgatorio sonu, quod si id placuerit, post statuas Constantii deiectas, super adimenda vita praefecto conveniet securius cogitari.", "st": "14.7"}, {"sp": "N", "t": "His cognitis Gallus ut serpens appetitus telo vel saxo, iamque spes extremas opperiens, et succurrens saluti suae quavis ratione, colligiones iussit armatos, et cum starent attoniti, districta dentium acie stridens, “Adeste” inquit “viri fortes mihi periclitanti vobiscum.", "st": "14.7"}, {"sp": "N", "t": "“Montius nos tumore inusitato quodam et novo, ut rebelles et maiestati recalcitrantes Augustae, per haec quae strepit incusat, iratus nimirum, quod contumacem praefectum, quid rerum ordo postulat ignorare dissimulantem, formidine tenus iusserim custodiri.”", "st": "14.7"}, {"sp": "N", "t": "Nihil morati post haec militares avidi saepe turbarum, adorti sunt Montium primum, qui devertebat in proximo, levi corpore senem atque morbosum, et hirsutis resticulis cruribus eius innexis, divaricatum sine spiramento ullo ad usque praetorium traxere praefecti.", "st": "14.7"}, {"sp": "N", "t": "Et eodem impetu Domitianum praecipitem per scalas itidem funibus constrinxerunt, eosque coniunctos per ampla spatia civitatis acri raptavere discursu. Iamque artuum et membrorum divulsa compage, superscandentes corpora mortuorum, ad ultimam truncata deformitatem, velut exsaturati mox abiecerunt in flumen.", "st": "14.7"}, {"sp": "N", "t": "Incenderat autem audaces usque ad insaniam homines ad haec quae nefariis egere conatibus, Luscus quidam curator urbis subito visus, eosque ut heiulans baiolorum praecentor, ad expediendum quod orsi sunt, incitans vocibus crebris. Qui haut longe postea ideo vivus exustus est.", "st": "14.7"}, {"sp": "N", "t": "Et quia Montius inter dilancinantium manus spiritum efflaturus, Epigonum et Eusebium, nec professionem nec dignitatem ostendens, aliquotiens increpabat, aequisoni his magna quaerebantur industria, et nequid intepesceret, Epigonus e Cilicia philosophus ducitur, et Eusebius ab Emissa Pittacas cognomento, concitatus orator, cum quaestor non hos sed tribunos fabricarum insimulasset, promittentes armorum, si novae res agitari coepissent.", "st": "14.7"}, {"sp": "N", "t": "Eisdem diebus Apollinaris Domitiani gener paulo ante agens palatii Caesaris curam, ad Mesopotamiam missus a socero, per militares numeros immodice scrutabatur, an quaedam altiora meditantis iam Galli secreta susceperint scripta; qui compertis Antiochiae gestis, per minorem Armeniam lapsus, Constantinopolim petit, exindeque per protectores retractus, artissime tenebatur.", "st": "14.7"}, {"sp": "N", "t": "Quae dum ita struuntur, indicatum est apud Tyrum indumentum regale textum occulte, incertum quo locante vel cuius usibus apparatum. Ideoque rector provinciae tunc pater Apollinaris eiusdem nominis ut conscius ductus est, aliique congregati sunt ex diversis civitatibus multi, qui atrocium criminum ponderibus urgebantur.", "st": "14.7"}, {"sp": "N", "t": "Iamque lituis cladium concrepantibus internarum, non celate (ut antea) turbidum saeviebat ingenium, a veri consideratione detortum, et nullo impositorum vel compositorum fidem sollemniter inquirente, nec discernente a societate noxiorum insontes, velut exturbatum e iudiciis fas omne discessit et causarum legitima silente defensione, carnifex rapinarum sequester, et obductio capitum, et bonorum ubique multatio versabatur per orientales provincias; quas recensere puto nunc opportunum, absque Mesopotamia, iam digesta cum bella Parthica narrarentur, et Aegypto, quam necessario aliud reieciemus ad tempus.", "st": "14.7"}, {"sp": "N", "t": "Superatis Tauri montis verticibus, qui ad solis ortum sublimius attolluntur, Cilicia spatiis porrigitur late distentis, dives bonis omnibus terra, eiusque lateri dextro annexa Isauria, pari sorte uberi, palmite viret et frugibus multis, quam mediam navigabile flumen Calycadnus interscindit.", "st": "14.8"}, {"sp": "N", "t": "Et hanc quidem praeter oppida multa duae civitates exornant, Seleucia opus Seleuci regis, et Claudiopolis, quam deduxit coloniam Claudius Caesar. Isaura enim antehac nimium potens, olim subversa ut rebellatrix interneciva, aegre vestigia claritudinis pristinae monstrat admodum pauca.", "st": "14.8"}, {"sp": "N", "t": "Ciliciam vero, quae Cydno amni exultat, Tarsus nobilitat, urbs perspicabilis—hanc condidisse Perseus memoratur, Iovis filius et Danaes, vel certe ex Aethiopia profectus Sandan quidam nomine vir opulentus et nobilis —et Anazarbus auctoris vocabulum referens, et Mopsuestia, vatis illius domicilium Mopsi, quem a commilitio Argonautarum, cum aureo vellere direpto redirent, errore abstractum, delatumque ad Africae litus, mors repentina consumpsit, et ex eo caespite punico tecti, manes eius heroici, dolorum varietati medentur plerumque sospitales.", "st": "14.8"}, {"sp": "N", "t": "Hac duae provinciae, bello quondam piratico catervis mixtae praedonum, a Servilio pro consule missae sub iugum, factae sunt vectigales. Et hae quidem regiones velut in prominenti terrarum lingua positae, ab orbe eoo monte Amano disparantur.", "st": "14.8"}, {"sp": "N", "t": "Orientis vero limes in longum protentus et rectum, ab Euphratis fluminis ripis ad usque supercilia porrigitur Nili, laeva Saracenis conterminans gentibus, dextra pelagi fragoribus patens, quam plagam Nicator Seleucus occupatam auxit magnum in modum, cum post Alexandri Macedonis obitum successorio iure teneret regna Persidis, efficaciae impetrabilis rex (ut indicat cognomentum).", "st": "14.8"}, {"sp": "N", "t": "Abusus enim multitudine hominum, quam tranquillis in rebus diutius rexit, ex agrestibus habitaculis urbes construxit, multis opibus firmas et viribus, quarum ad praesens pleraeque, licet Graecis nominibus appellentur, quae eisdem ad arbitrium imposita sunt conditoris, primigenia tamen nomina non amittunt, quae eis Assyria lingua institutores veteres indiderunt.", "st": "14.8"}, {"sp": "N", "t": "Et prima post Osdroenam quam (ut dictum est) ab hac descriptione discrevimus, Commagena (nunc Euphratensis) clementer assurgit, Hierapoli (vetere Nino) et Samosata civitatibus amplis illustris.", "st": "14.8"}, {"sp": "N", "t": "Dein Syria per speciosam interpatet diffusa planitiem. Hanc nobilitat Antiochia, mundo cognita civitas, cui non certaverit alia advecticiis ita affluere copiis et internis, et Laodicia et Apamia, itidemque Seleucia iam inde a primis auspiciis florentissimae.", "st": "14.8"}, {"sp": "N", "t": "Post hanc acclinis Libano monti Phoenice, regio plena gratiarum et venustatis, urbibus decorata magnis et pulchris; in quibus amoenitate celebritateque nominum Tyros excellit, Sidon et Berytus eisdemque pares Emissa et Damascus saeculis condita priscis.", "st": "14.8"}, {"sp": "N", "t": "Has autem provincias, quas Orontes ambiens amnis, imosque pedes Cassii montis illius celsi praetermeans, funditur in Parthenium mare, Gnaeus Pompeius superato Tigrane, regnis Armeniorum abstractas, dicioni Romanae coniunxit.", "st": "14.8"}, {"sp": "N", "t": "Ultima Syriarum est Palaestina, per intervalla magna protenta, cultis abundans terris et nitidis, et civitates habens quasdam egregias, nullam nulli cedentem, sed sibi vicissim velut ad perpendiculum aemulas: Caesaream, quam ad honorem Octaviani principis exaedificavit Herodes, et Eleutheropolim et Neapolim, itidemque Ascalonem Gazam, aevo superiore exstructas.", "st": "14.8"}, {"sp": "N", "t": "In his tractibus navigerum nusquam visitur flumen, et in locis plurimis aquae suapte natura calentes emergunt, ad usus aptae multiplicium medellarum. Verum has quoque regiones pari sorte Pompeius Iudaeis domitis et Hierosolymis captis, in provinciae speciem delata iuris dictione formavit.", "st": "14.8"}, {"sp": "N", "t": "Huic Arabia est conserta, ex alio latere Nabataeis contigua, opima varietate commerciorum castrisque oppleta validis et castellis, quae ad repellendos gentium vicinarum excursus, sollicitudo pervigil veterum per opportunos saltus erexit et cautos. Haec quoque civitates habet inter oppida quaedam ingentes, Bostram et Gerasam atque Philadelphiam, murorum firmitate cautissimas. Hanc provinciae imposito nomine, rectoreque adtributo, obtemperare legibus nostris Traianus compulit imperator, incolarum tumore saepe contunso, cum glorioso Marte Mediam urgeret et Parthos.", "st": "14.8"}, {"sp": "N", "t": "Cyprum itidem insulam procul a continenti discretam et portuosam, inter municipia crebra urbes duae faciunt claram, Salamis et Paphus, altera Iovis delubris, altera Veneris temple insignis. Tanta autem tamque multiplici fertilitate abundat rerum omnium eadem Cyprus, ut nullius externi indigens adminiculi, indigenis viribus, a fundamento ipso carinae ad supremos usque carbasos, aedificet onerariam navem, omnibusque armamentis instructam, mari committat.", "st": "14.8"}, {"sp": "N", "t": "Nec piget dicere avide magis hanc insulam populum Romanum invasisse quam iuste. Ptolomaeo enim rege foederato nobis et socio, ob aerarii nostri angustias iusso sine ulla culpa proscribi, ideoque hausto veneno, voluntaria morte deleto, et tributaria facta est, et velut hostiles eius exuviae classi impositae, in urbem advectae sunt per Catonem. Nunc repetetur ordo gestorum.", "st": "14.8"}, {"sp": "N", "t": "Inter has ruinarum varietates, a Nisibi quam tuebatur accitus Ursicinus, cui nos obsecuturos iunxerat imperiale praeceptum, dispicere litis exitialis crimina cogebatur, abnuens et reclamans, adllatorum oblatrantibus turmis, bellicosus sane milesque semper et militum ductor, sed forensibus iurgiis longe discretus, qui metu sui discriminis. anxius, cum accusatores quaesitoresque subditivos sibi consociatos, ex eisdem foveis cerneret emergentes, quae clam palamve agitabantur occultis Constantium litteris edocebat, implorans subsidia, quorum metu tumor notissimus Caesaris exhalaret.", "st": "14.9"}, {"sp": "N", "t": "Sed cautela nimia in peiores haeserat plagas, ut narrabimus postea, aemulis consarcinantibus insidias graves apud Constantium, cetera medium principem, sed siquid auribus eius huius modi quivis infudisset ignotus, acerbum et implacabilem, et in hoc causarum titulo dissimilem sui.", "st": "14.9"}, {"sp": "N", "t": "Proinde die funestis interrogationibus praestituto, imaginarius iudex equitum resedit magister, adhibitis allis, iam quae essent agenda praedoctis, et assistebant hinc inde notarii, quid quaesitum esset quidve responsum, cursim ad Caesarem perferentes; cuius imperio truci, stimulis reginae exsertantis ora subinde per aulaeum, nec diluere obiecta permissi nec defensi periere complures.", "st": "14.9"}, {"sp": "N", "t": "Primi igitur omnium statuuntur Epigonus et Eusebius, ob nominum gentilitatem oppressi. Praediximus enim Montium sub ipso vivendi termino his vocabulis appellatos, fabricarum culpasse tribunos, ut adminicula futurae molitioni pollicitos.", "st": "14.9"}, {"sp": "N", "t": "Et Epigonus quidem amictu tenus philosophus, ut apparuit, prece frustra temptata, sulcatis lateribus, mortisque metu admoto, turpi confessione cogitatorum socium (quae nulla erant) fuisse firmavit, cum nec vidisset quicquam nec audisset, penitus expers forensium rerum; Eusebius vero obiecta fidentius negans, suspensus in eodem gradu constantiae stetit, latrocinium illud esse, non iudicium clamans.", "st": "14.9"}, {"sp": "N", "t": "Cumque pertinacius (ut legum gnarus) accusatorem flagitaret atque sollemnia, doctus id Caesar, libertatemque superbiam ratus, tamquam obtrectatorem audacem excarnificari praecepit, qui ita evisceratus ut cruciatibus membra deessent, implorans caelo iustitiam, torvum renidens, fundato pectore mansit immobilis, nec se incusare nec quemquam alium passus, et tandem nec confessus nec confutatus, cum abiecto consorte poenali est morte multatus. Et ducebatur intrepidus, temporum iniquitati insultans, imitatus Zenonem illum veterem Stoicum, qui ut mentiretur quaedam laceratus diutius, avulsam sedibus linguam suam cum cruento sputamine, in oculos interrogantis Cyprii regis impegit.", "st": "14.9"}, {"sp": "N", "t": "Post haec indumentum regale quaerebatur, et ministris fucandae purpurae tortis, confessisque pectoralem tuniculam sine manicis textam, Maras nomine quidam inductus est (ut appellant Christiani) diaconus; cuius prolatae litterae scriptae Graeco sermone, ad Tyrii textrini praepositum, celerari speciem perurgebant, quam autem non indicabant; denique etiam idem ad usque discrimen vitae vexatus, nihil fateri compulsus est.", "st": "14.9"}, {"sp": "N", "t": "Quaestione igitur per multiplices dilatata fortunas, cum ambigerentur quaedam, non nulla levius actitata constaret, post multorum clades Apollinares ambo pater et filius, in exilium acti, cum ad locum Crateras nomine pervenissent, villam scilicet suam, quae ab Antiochia vicensimo et quarto disiungitur lapide, ut mandatum est, fractis cruribus occiduntur.", "st": "14.9"}, {"sp": "N", "t": "Post quorum necem nihilo lenius ferociens Gallus, ut leo cadaveribus pastus, multa huius modi scrutabatur. Quae singula narrare non refert, ne professionis modum (quod sane vitandum est) excedamus.", "st": "14.9"}, {"sp": "N", "t": "Haec dum oriens diu perferret, caeli reserato tepore, Constantius consulatu suo septies et Caesaris iterum, egressus Arelate Valentiam petit, in Gundomadum et Vadomarium fratres Alamannorum reges arma moturus, quorum crebris excursibus vastabantur confines limitibus terrae Gallorum.", "st": "14.10"}, {"sp": "N", "t": "Dumque ibi diu moratur, commeatus opperiens, quorum translationem ex Aquitania verni imbres solito crebriores prohibebant auctique torrentes, Herculanus advenit protector domesticus, Hermogenis ex magistro equitum filius, apud Constantinopolim (ut supra retulimus) popularium quondam turbela discerpti. Quo verissime referente quae Gallus egerat coniuxque, super praeteritis maerens, et futurorum timore suspensus, angorem animi quam diu potuit emendabat.", "st": "14.10"}, {"sp": "N", "t": "Miles tamen interea omnis apud Cabillona collectus, morarum impatiens saeviebat, hoc irritatior, quod nec subsidia vivendi suppeterent, alimentis nondum ex usu translatis.", "st": "14.10"}, {"sp": "N", "t": "Unde Rufinus ea tempestate praefectus praetorio, ad discrimen trusus est ultimum. Ire enim ipse compellebatur ad militem, quem exagitabat inopia simul et feritas, et alioqui coalito more in ordinarias dignitates asperum semper et saevum, ut satisfaceret, atque monstraret, quam ob causam annonae convectio sit impedita.", "st": "14.10"}, {"sp": "N", "t": "Quod opera consulta cogitabatur astute, ut hoc insidiarum genere Galli periret avunculus, ne eum ut praepotens acueret in fiduciam, exitiosa coeptantem. Verum navata est opera diligens, hocque dilato, Eusebius praepositus cubiculi missus est Cabyllona, aurum secum perferens, quo per turbulentos seditionum concitores occultius distributo, et tumor consenuit militum, et salus est in tuto locata praefecti. Deinde cibo abunde perlato, castra die praedicto sunt mota.", "st": "14.10"}, {"sp": "N", "t": "Emensis itaque difficultatibus multis, et nive obrutis callibus plurimis, ubi prope Rauracum ventum est ad supercilia fluminis Rheni, resistente multitudine Alamanna, pontem suspendere navium compage Romani vi nimia vetabantur, ritu grandinis undique convolantibus telis; et cum id impossibile videretur, imperator cogitationibus magnis attonitus, quid capesseret ambigebat.", "st": "14.10"}, {"sp": "N", "t": "Ecce autem ex inproviso index quidam regionum gnarus advenit, et mercede accepta, vadosum locum nocte monstravit, unde superari potuit flumen. Et potuisset aliorsum intentis hostibus exercitus inde transgressus, nullo id opinante, cuncta vastare, ni pauci ex eadem gente, quibus erat honoratioris militis cura commissa, populares suos haec per nuntios docuissent occultos, ut quidam existimabant.", "st": "14.10"}, {"sp": "N", "t": "Infamabat autem haec suspicio Latinum domesticorum comitem et Agilonem tribunum stabuli atque Scudilonem scutariorum rectorem, qui tunc, ut dextris suis gestantes rem publicam, colebantur.", "st": "14.10"}, {"sp": "N", "t": "At barbari suscepto pro instantium rerum ratione consilio, dirimentibus forte auspicibus, vel congredi prohibente auctoritate sacrorum, mollito rigore, quo fidentius resistebant, optimates misere, delictorum veniam petituros et pacem.", "st": "14.10"}, {"sp": "N", "t": "Tentis igitur regis utriusque legatis, et negotio tectius diu pensato, cum pacem oportere tribui quae iustis condicionibus petebatur, eamque ex re fore sententiarum via concinens approbasset, advocato in contionem exercitu, imperator pro tempore pauca dicturus, tribunali adsistens, circumdatus potestatum coetu celsarum, ad hunc disseruit modum:", "st": "14.10"}, {"sp": "N", "t": "“Nemo (quaeso) miretur, si post exsudatos labores itinerum longos, congestosque adfatim commeatus, fiducia vestri ductante, barbaricos pagos adventans, velut mutato repente consilio, ad placidiora deverti.", "st": "14.10"}, {"sp": "N", "t": "“Pro suo enim loco et animo, quisque vestrum reputans id inveniet verum, quod miles ubique, licet membris vigentibus firmus, se solum vitamque propriam circumspicit et defendit, imperator vero officiorum, dum aequis omnibus consulit, plenus, alienae custos salutis, nihil non ad sui spectare tutelam rationes populorum cognoscit, et remedia cuncta quae status negotiorum admittit, arripere debet alacriter, secunda numinis voluntate delata.", "st": "14.10"}, {"sp": "N", "t": "“Ut in breve igitur conferam et ostendam qua ex causa omnes vos simul adesse volui, commilitones mei fidissimi, accipite aequis auribus quae succinctius explicabo. Veritatis enim absolutio semper est simplex.", "st": "14.10"}, {"sp": "N", "t": "“Arduos vestrae gloriae gradus, quos fama per plagarum quoque accolas extimarum diffundit, excellenter accrescens, Alamannorum reges et populi formidantes, per oratores quos videtis, summissis cervicibus, concessionem praeteritorum poscunt et pacem. Quam ut cunctator et cautus, utiliumque monitor, (si vestra voluntas adest) tribui debere censeo multa contemplans. Primo ut Martis ambigua declinentur, dein ut auxiliatores pro adversariis adsciscamus, quod pollicentur, tum autem ut incruenti mitigemus ferociae flatus, perniciosos saepe provinciis, postremo id reputantes, quod non ille hostis vincitur solus, qui cadit in acie, pondere armorum oppressus et virium, sed multo tutius etiam tuba tacente, sub iugum mittitur voluntarius, qui sentit expertus, nec fortitudinem in rebelles nec lenitatem in supplices animos abesse Romanis.", "st": "14.10"}, {"sp": "N", "t": "“In summa tanquam arbitros vos quid suadetis opperior, ut princeps tranquillus, temperanter adhibere modum adlapsa felicitate decernens. Non enim inertiae sed modestiae humanitatique (mihi credite) hoc quod recte consultum est adsignabitur.”", "st": "14.10"}, {"sp": "N", "t": "Mox dicta finierat, multitudo omnis ad quae imperator voluit promptior, laudato consilio, consensit in pacem, ea ratione maxime percita, quod norat expeditionibus crebris fortunam eius in malis tantum civilibus vigilasse; cum autem bella moverentur externa, accidisse plerumque luctuosa. Icto post haec foedere gentium ritu, perfectaque sollemnitate, imperator Mediolanum ad hiberna discessit.", "st": "14.10"}, {"sp": "N", "t": "Ubi curarum abiectis ponderibus aliis, tamquam nodum et codicem difficillimum, Caesarem convellere nisu valido cogitabat; eique deliberanti cum proximis, clandestinis colloquiis et nocturnis, qua vi quibusve commentis id fieret, antequam effundendis rebus pertinacius incumberet confidentia, acciri mollioribus scriptis, per simulationem tractatus publici nimis urgentis, eundem placuerat Gallum, ut auxilio destitutus, sine ullo interiret obstaculo.", "st": "14.11"}, {"sp": "N", "t": "Huic sententiae versabilium adulatorum refragantibus globis, inter quos erat Arbetio, ad insidiandum acer et flagrans, et Eusebius tunc praepositus cubiculi effusior ad nocendum, id occurrebat, Caesare discedente, Ursicinum in oriente perniciose relinquendum, si nullus esset qui prohiberet altiora meditaturum.", "st": "14.11"}, {"sp": "N", "t": "Eisdemque residui regii accessere spadones, quorum ea tempestate plus habendi cupiditas ultra mortalem modum adolescebat, inter ministeria vitae secretioris per arcanos susurros nutrimenta fictis criminibus subserentes; qui ponderibus invidiae gravioris virum fortissimum opprimebant, subolescere imperio adultos eius filios mussitantes, decore corporum favorabiles et aetate, per multiplicem armaturae scientiam, agilitatenque membrorum, inter cotidiana proludia exercitus, consulto consilio cognitos: Gallum suopte ingenio trucem, per suppositos quosdam ad saeva facinora ideo animatum, ut eo digna omnium ordinum detestatione exoso, ad magistri equitum liberos principatus insignia transferantur.", "st": "14.11"}, {"sp": "N", "t": "Cum haec taliaque sollicitas eius aures everberarent, expositas semper eius modi rumoribus et patentes, vario animi motu miscente consilia, tandem id ut optimum factu elegit: et Ursicinum primum ad se venire summo cum honore mandavit, ea specie ut pro rerum tune urgentium captu, disponeretur concordi consilio, quibus virium incrementis, Parthicarum gentium arma minantium impetus frangerentur.", "st": "14.11"}, {"sp": "N", "t": "Et nequid suspicaretur adversi venturus, vicarius eius (dum redit) Prosper missus est comes; acceptisque litteris, et copia rei vehiculariae data, Mediolanum itineribus properavimus magnis.", "st": "14.11"}, {"sp": "N", "t": "Restabat ut Caesar post haec properaret accitus, et abstergendae causa suspicionis, sororem suam (eius uxorem) Constantius ad se tandem desideratam venire, multis fictisque blanditiis hortabatur. Quae licet ambigeret, metuens saepe cruentum, spe tamen quod eum lenire poterit ut germanum, profecta, cum Bithyniam introisset, in statione quae Caenos Gallicanos appellatur, absumpta est vi febrium repentina. Cuius post obitum maritus contemplans cecidisse fiduciam qua se fultum existimabat, anxia cogitatione quid moliretur haerebat.", "st": "14.11"}, {"sp": "N", "t": "Inter res enim impeditas et turbidas, ad hoc unum mentem sollicitam dirigebat, quod Constantius cuncta ad suam sententiam conferens, nec satisfactionem suscipiet aliquam, nec erratis ignoscet, sed ut erat in propinquitatis perniciem inclinatior, laqueos ei latenter obtendens, si cepisset incautum, morte multaret.", "st": "14.11"}, {"sp": "N", "t": "Eo necessitatis adductus, ultimaque ni vigilasset opperiens, principem locum, si copia patuisset, clam affectabat, sed perfidiam proximorum ratione bifaria verebatur, qui eum ut truculentum horrebant et levem, quique altiorem Constantii fortunam in discordiis civilibus formidabant.", "st": "14.11"}, {"sp": "N", "t": "Inter has curarum moles immensas, imperatoris scripta suscipiebat assidua, monentis orantisque ut ad se veniret, et mente monstrantis obliqua, rem publicam nec posse dividi nec debere, sed pro viribus quemque ei ferre suppetias fluctuanti, nimirum Galliarum indicans vastitatem.", "st": "14.11"}, {"sp": "N", "t": "Quibus subserebat non adeo vetus exemplum, quod Diocletiano et eius collegae, ut apparitores Caesares non resides sed ultro citroque discurrentes, obtemperabant, et in Syria Augusti vehiculum irascentis, per spatium mille passuum fere pedes antegressus est Galerius purpuratus.", "st": "14.11"}, {"sp": "N", "t": "Advenit post multos Scudilo scutariorum tribunus, velamento subagrestis ingenii, persuasionis opifex callidus. Qui eum adulabili sermone periuriis admixto, solus omnium proficisci pellexit, vultu assimulato saepius replicando, quod flagrantibus votis eum videre frater cuperet patruelis, siquid per imprudentiam gestum est, remissurus, ut mitis et clemens, participemque eum suae maiestatis assciscet, futurum laborum quoque socium, quos Arctoae provinciae diu fessae poscebant.", "st": "14.11"}, {"sp": "N", "t": "Utque solent manum iniectantibus fatis, hebetari sensus hominum et obtundi, his illecebris ad meliorum expectationem erectus, egressusque Antiochia numine laevo ductante, prorsus ire tendebat de fumo, ut proverbium loquitur vetus, ad flammam; et ingressus Constantinopolim, tamquam in rebus prosperis et securis, editis equestribus ludis, capiti Thoracis aurigae coronam imposuit, ut victoris.", "st": "14.11"}, {"sp": "N", "t": "Quo cognito Constantius ultra mortalem modum exarsit; ac nequo casu idem Gallus de futuris incertus, agitare quaedam conducentia saluti suae per itinera conaretur, remoti sunt omnes de industria milites agentes in civitatibus perviis.", "st": "14.11"}, {"sp": "N", "t": "Eoque tempore Taurus quaestor ad Armeniam missus, confidenter nec appellate eo nec viso transivit. Venere tamen aliqui iussu imperatoris, administrationum specie diversarum, eundem ne commovere se posset, neve temptaret aliquid occulte custodituri; inter quos Leontius erat, postea urbi praefectus, ut quaestor, et Lucillianus quasi domesticorum comes et scutariorum tribunus nomine Bainobaudes.", "st": "14.11"}, {"sp": "N", "t": "Emensis itaque longis intervallis et planis, cum Hadrianopolim introisset, urbem Haemimontanam, Uscudamam antehac appellatam, fessasque labore diebus duodecim recreans vires, comperit Thebaeas legiones in vicinis oppidis hiemantes, consortes suos misisse quosdam, eum ut remaneret promissis fidis hortaturos et firmis, cum animarentur roboris sui fiducia, abunde per stationes locatae confines, sed observante cura pervigili proximorum, nullam videndi vel audiendi quae ferebant, furari potuit facultatem.", "st": "14.11"}, {"sp": "N", "t": "Inde aliis super alias urgentibus litteris exire et decem vehiculis publicis, ut praeceptum est, usus, relicto palatio omni, praeter paucos tori ministros et mensae, quos avexerat secum, squalore concretus, celerare gradum compellebatur, adigentibus multis, temeritati suae subinde flebiliter imprecatus, quae eum iam despectum et vilem arbitrio subdiderat infimorum.", "st": "14.11"}, {"sp": "N", "t": "Inter haec tamen per indutias naturae conquiescentis, sauciabantur eius sensus circumstridentium terrore larvarum, interfectorumque catervae, Domitiano et Montio praeviis, correptum eum (ut existimabat in somnis), uncis furialibus obiectabant.", "st": "14.11"}, {"sp": "N", "t": "Solutus enim corporeis nexibus, animus semper vigens motibus indefessis, ex cogitationibus subiectis et curis, quae mortalium sollicitant mentes, colligit visa nocturna, quas φαντασίας nos appellamus.", "st": "14.11"}, {"sp": "N", "t": "Pandente itaque viam fatorum sorte tristissima, qua praestitutum erat eum vita et imperio spoliari, itineribus rectis permutatione iumentorum emensis, venit Petobionem oppidum Noricorum, ubi reseratae sunt insidiarum latebrae omnes, et Barbatio repente apparuit Comes, qui sub eo domesticis praefuit, cum Apodemio agente in rebus, milites ducens, quos beneficiis suis oppigneratos elegerat imperator, certus nec praemiis nec miseratione ulla posse deflecti.", "st": "14.11"}, {"sp": "N", "t": "Iamque non umbratis fallaciis res agebatur, sed qua palatium est extra muros, armatis Barbatio omne circumdedit. Ingressusque obscuro iam die, ablatis regiis indumentis, Caesarem tunica texit et paludamento communi, eum post haec nihil passurum, velut mandato principis iurandi crebritate confirmans, et “Statim” inquit “exsurge,” et inopinum carpento privato impositum, ad Histriam duxit, prope oppidum Polam, ubi quondam peremptum Constantini filium accipimus Crispum.", "st": "14.11"}, {"sp": "N", "t": "Et cum ibi servaretur artissime, terrore propinquantis exitii iam praesepultus, accurrit Eusebius, cubiculi tune praepositus, Pentadiusque notarius, et Mallobaudes armaturarum tribunus, iussu imperatoris compulsuri eum singillatim docere, quam ob causam quemque apud Antiochiam necatorum iusserat trucidari.", "st": "14.11"}, {"sp": "N", "t": "Ad quae Adrasteo pallore perfusus, hactenus valuit loqui, quod plerosque incitante coniuge iugulaverit Constantina, ignorans profecto Alexandrum Magnum urgenti matri ut occideret quendam insontem, et dictitanti spe impetrandi postea quae vellet, eum se per novem menses utero portasse praegnantem, ita respondisse prudenter: “Aliam, parens optima, posce mercedem; hominis enim salus beneficio nullo pensatur.”", "st": "14.11"}, {"sp": "N", "t": "Quo comperto irrevocabili ira princeps percitus et dolore, fiduciam omnem fundandae securitatis in eodem posuit abolendo. Et misso Sereniano, quem in crimen maiestatis vocatum praestigiis quibusdam absolutum esse supra monstravimus, Pentadio quin etiam notario, et Apodemio agente in rebus, eum capitali supplicio destinavit, et ita colligatis manibus in modum noxii cuiusdam latronis, cervice abscisa, ereptaque vultus et capitis dignitate, cadaver est relictum informe, paulo ante urbibus et provinciis formidatum.", "st": "14.11"}, {"sp": "N", "t": "Sed vigilavit utrubique superni numinis aequitas. Nam et Gallum actus oppressere crudeles, et non diu postea ambo cruciabili morte absumpti sunt, qui eum licet nocentem, blandius palpantes periuriis, ad usque plagas perduxere letales. Quorum Scudilo destillatione iecoris pulmones vomitans interiit; Barbatio, qui in eum iam diu falsa composuerat crimina, cum ex magisterio peditum altius niti quorundam susurris incusaretur, damnatus extincti per fallacias Caesaris manibus inlacrimoso obitu parentavit.", "st": "14.11"}, {"sp": "N", "t": "Haec et huius modi quaedam innumerabilia ultrix facinorum impiorum, bonorumque praemiatrix, aliquotiens operatur Adrastia, (atque utinam semper!): quam vocabulo duplici etiam Nemesim appellamus: ius quoddam sublime numinis efficacis, humanarum mentium opinione lunari circulo superpositum, vel ut definiunt alii, substantialis tutela generali potentia partilibus praesidens fatis, quam theologi veteres fingentes Iustitiae filiam, ex abdita quadam aeternitate tradunt omnia despectare terrena.", "st": "14.11"}, {"sp": "N", "t": "Haec ut regina causarum, et arbitra rerum ac disceptatrix, urnam sortium temperat, accidentium vices alternans, voluntatumque nostrarum exorsa interdum alio quam quo contendebant exitu terminans, multiplices actus permutando convolvit. Eademque necessitatis insolubili retinaculo mortalitatis vinciens fastus, tumentes in cassum, et incrementorum detrimentorumque momenta versabilis librans (ut novit), nunc erectas eminentium cervices opprimit et enervat, nunc bonos ab imo suscitans ad bene vivendum extollit. Pinnas autem ideo illi fabulosa vetustas aptavit, ut adesse velocitate volucri cunctis existimetur, et praetendere gubernaculum dedit, eique subdidit rotam, ut universitatem regere per elementa discurrens omnia non ignoretur.", "st": "14.11"}, {"sp": "N", "t": "Hoc immaturo interitu, ipse quoque sui pertaesus, excessit e vita, aetatis nono anno atque vicensimo, cum quadriennio imperasset. Natus apud Tuscos in Massa Veternensi patre Constantio, Constantini fratre imperatoris, matreque Galla, sorore Rufini et Cerealis, quos trabeae consulares nobilitarunt, et praefecturae.", "st": "14.11"}, {"sp": "N", "t": "Fuit autem forma conspicuus bona, decente filo corporis membrorumque recta compage, flavo capillo et molli, barba licet recens emergente lanugine tenera, ita tamen ut maturius auctoritas emineret; tantum a temperatis moribus Iuliani differens fratris, quantum inter Vespasiani filios fuit Domitianum et Titum.", "st": "14.11"}, {"sp": "N", "t": "Assumptus autem in amplissimum fortunae fastigium, versabilis eius motus expertus est, qui ludunt mortalitatem, nunc evehentes quosdam in sidera, nunc ad Cocyti profunda mergentes. Cuius rei cum innumera sint exempla, pauca tactu summo transcurram.", "st": "14.11"}, {"sp": "N", "t": "Haec fortuna mutabilis et inconstans fecit Agathoclem Siculum ex figulo regem, et Dionysium, gentium quondam terrorem, Corinthi litterario ludo praefecit.", "st": "14.11"}, {"sp": "N", "t": "Haec Adramytenum Andriscum, in fullonio natum, ad Pseudophilippi nomen evexit, et Persei legitimum filium artem ferrariam ob quaerendum docuit victum.", "st": "14.11"}, {"sp": "N", "t": "Eadem Mancinum post imperium dedidit Numantinis, Samnitum atrocitati Veturium, et Claudium Corsis, substravitque feritati Carthaginis Regulum; istius iniquitate Pompeius, post quaesitum Magni ex rerum gestarum amplitudine cognomentum, ad spadonum libidinem in Aegypto trucidatur.", "st": "14.11"}, {"sp": "N", "t": "Et Eunus quidam ergastularius servus ductavit in Sicilia fugitivos. Quam multi splendido loco nati Romani, eadem rerum domina conivente, Viriathi genua sunt amplexi vel Spartaci? Quot capita quae horruere gentes funesti carnifices absciderunt? Alter in vincula ducitur, alter insperatae praeficitur potestati, alius a summo culmine dignitatis excutitur.", "st": "14.11"}, {"sp": "N", "t": "Quae omnia si scire quisquam velit quam varia sint et assidua, harenarum numerum idem iam desipiens et montium pondera scrutari putabit.", "st": "14.11"}, {"sp": "HDR", "t": "Liber XV", "st": "15"}, {"sp": "N", "t": "Utcumque potui veritatem scrutari, ea quae videre licuit per aetatem, vel perplexe interrogando versatos in medio scire, narravimus ordine casuum exposito diversorum; residua quae secuturus aperiet textus, pro virium captu limatius absolvemus, nihil obtrectatores longi (ut putant) operis formidantes. Tunc enim laudanda est brevitas, cum moras rumpens intempestivas, nihil subtrahit cognitioni gestorum.", "st": "15.1"}, {"sp": "N", "t": "Nondum apud Noricum exuto penitus Gallo, Apodemius quoad vixerat igneus turbarum incentor, raptos eius calceos vehens, equorum permutatione veloci, ut nimietate cogendi quosdam exstingueret, praecursorius index Mediolanum advenit ingressusque regiam, ante pedes proiecit Constantii, velut spolia regis occisi Parthorum; et perlato nuntio repentino, docente rem insperatam et arduam ad sententiam totam facilitate completam, hi qui summam aulam tenebant, omni placendi studio in adulationem ex more collato, virtutem felicitatemque imperatoris extollebant in caelum, cuius nutu in modum gregariorum militum (licet diversis temporibus) duo exauctorati sunt principes, Veteranio nimirum et Gallus.", "st": "15.1"}, {"sp": "N", "t": "Quo ille studio blanditiarum exquisite sublatus, immunemque se deinde fore ab omni mortalitatis incommodo fidenter existimans, confestim a iustitia declinavit ita intemperanter, ut “Aeternitatem meam” aliquotiens subsereret ipse dictando, scribendoque propria manu orbis totius se dominum appellaret; quod dicentibus aliis, indignanter admodum ferre deberet is qui ad aemulationem civilium principum formare vitam moresque suos, ut praedicabat, diligentia laborabat enixa.", "st": "15.1"}, {"sp": "N", "t": "Namque etiam si mundorum infinitates Democriti regeret, quos Anaxarcho incitante Magnus somniabat Alexander, id reputasset legens vel audiens, quod (ut docent mathematici concinentes), ambitus terrae totius, quae nobis videtur immensa, ad magnitudinem universitatis instar brevis optinet puncti.", "st": "15.1"}, {"sp": "N", "t": "Iamque post miserandam deleti Caesaris cladem, sonante periculorum iudicialium tuba, in crimen laesae maiestatis arcessebatur Ursicinus, adulescente magis magisque contra eius salutem livore, omnibus bonis infesto.", "st": "15.2"}, {"sp": "N", "t": "Hac enim superabatur difficultate, quod ad suscipiendas defensiones aequas et probabiles, imperatoris aures occlusae, patebant susurris insidiantium clandestinis, qui Constantii nomine per orientis tractus omnes abolito, ante dictum ducem domi forisque desiderari, ut formidolosum Persicae genti, fingebant.", "st": "15.2"}, {"sp": "N", "t": "Sed contra accidentia vir magnanimus stabat immobilis, ne se proiceret abiectius cavens, parum tuto loco innocentiam stare medullitus gemens, hocque uno tristior quod amici ante haec frequentes ad potiores desciverant, ut ad successores officiorum, more poscente, solent transire lictores.", "st": "15.2"}, {"sp": "N", "t": "Impugnabat autem eum per fictae benignitatis illecebras, collegam et virum fortem propalam saepe appellans Arbetio, ad innectendas letales insidias vitae simplici perquam callens, et ea tempestate nimium potens. Ut enim subterraneus serpens, foramen subsidens occultum, adsultu subito singulos transitores observans incessit, ita ille odio alienae sortis etiam post adeptum summum militiae munus, nec laesus aliquando nec lacessitus, inexplebili quodam laedendi proposito, conscientiam polluebat.", "st": "15.2"}, {"sp": "N", "t": "Igitur paucis arcanorum praesentibus consciis, latenter cum imperatore sententia diu digesta, id sederat, ut nocte ventura, procul a conspectu militarium raptus, Ursicinus indemnatus occideretur, ut quondam Domitius Corbulo dicitur caesus, in colluvione illa Neroniani saeculi provinciarum fidus defensor et cautus.", "st": "15.2"}, {"sp": "N", "t": "Quibus ita compositis, cum ad hoc destinati praedictum tempus operirentur, consilio in lenitudinem flexo, facinus impium ad deliberationem secundam differri praeceptum est.", "st": "15.2"}, {"sp": "N", "t": "Indeque ad Iulianum, recens perductum, calumniarum vertitur machina, memorabilem postea principem, gemino crimine, ut iniquitas aestimabat, implicitum: quod a Macelli fundo, in Cappadocia posito, ad Asiam demigrarat, liberalium desiderio doctrinarum, et per Constantinopolim transeuntem viderat fratrem.", "st": "15.2"}, {"sp": "N", "t": "Qui cum obiecta dilueret, ostenderetque neutrum sine iussu fecisse, nefando assentatorum coetu perisset urgente, ni adspiratione superni numinis Eusebia suffragante regina, ductus ad Comum oppidum Mediolano vicinum, ibique paulisper moratus, procudendi ingenii causa (ut cupidine flagravit) ad Graeciam ire permissus est.", "st": "15.2"}, {"sp": "N", "t": "Nec defuere deinceps ex his emergentia casibus, quae diceres secundis avibus contigisse, dum punirentur ex iure, vel tamquam irrita diffluebant et vana. Sed accidebat non numquam, ut opulenti pulsantes praesidia potiorum, eisdemque tamquam ederae celsis arboribus adhaerentes, absolutionem pretiis mercarentur immensis; tenues vero, quibus exiguae vires erant ad redimendam salutem aut nullae, damnabantur abrupte. Ideoque et veritas mendaciis velabatur, et valuere pro veris aliquotiens falsa.", "st": "15.2"}, {"sp": "N", "t": "Perductus est eisdem diebus et Gorgonius, cui erat thalami Caesariani cura commissa, cumque eum ausorum fuisse participem, concitoremque interdum, ex confesso pateret, conspiratione spadonum iustitia concinnatis mendaciis obumbrata, periculo evolutus abscessit.", "st": "15.2"}, {"sp": "N", "t": "Haec dum Mediolani aguntur, militarium catervae ab oriente perductae sunt Aquileiam, cum aulicis pluribus, membris inter catenas fluentibus, spiritum trahentes exiguum vivendique moras per aerumnas detestati multiplices. Arcessebantur enim ministri fuisse Galli ferocientis, perque eos Domitianus discerptus credebatur et Montius, et alii post eos acti in exitium praeceps.", "st": "15.3"}, {"sp": "N", "t": "Ad quos audiendos Arboreus missus est et Eusebius, cubiculi tunc praepositus, ambo inconsideratae iactantiae, iniusti pariter et cruenti. Qui nullo perspicaciter inquisito, sine innocentium sontiumque differentia, alios verberibus vel tormentis afflictos exsulari poena damnarunt, quosdam ad infimam trusere militiam, residuos capitalibus addixere suppliciis. Impletisque funerum bustis, reversi velut ovantes, gesta rettulerunt ad principem, erga haec et similia palam obstinatum et gravem.", "st": "15.3"}, {"sp": "N", "t": "Vehementius hinc et deinde Constantius, quasi praescriptum fatorum ordinem convulsurus, recluso pectore patebat insidiantibus multis. Unde rumorum aucupes subito exstitere complures, honorum vertices ipsos ferinis morsibus appetentes, posteaque pauperes et divites indiscrete; non ut Cibyratae illi Verrini, tribunal unius legati lambentes, sed rei publicae membra totius per incidentia mala vexantes.", "st": "15.3"}, {"sp": "N", "t": "Inter quos facile Paulus et Mercurius eminebant: hic origine Persa, ille natus in Dacia: notarius ille, hie a ministro triclinii rationalis. Et Paulo quidem, ut relatum est supra, Catenae inditum est cognomentum, eo quod in complicandis calumniarum nexibus erat indissolubilis, mira inventorum sese varietate dispendens, ut in colluctationibus callere nimis quidam solent artifices palaestritae.", "st": "15.3"}, {"sp": "N", "t": "Mercurius vero somniorum appellatus est comes, quod ut clam mordax canis interna saevitia summissius agitans caudam, epulis coetibusque se crebris inserens, si per quietem quisquam, ubi fusius natura vagatur, vidisse aliquid amico narrasset, id venenatis artibus coloratum in peius, patulis imperatoris auribus infundebat, et ob hoc homo tamquam inexpiabili obnoxius culpae, gravi mole criminis pulsabatur.", "st": "15.3"}, {"sp": "N", "t": "Haec augente vulgatius fama, tantum aberat, ut proderet quisquam visa nocturna, ut contra aegre homines dormisse sese praesentibus faterentur externis, maerebantque docti quidam, quod apud Atlanteos nati non essent, ubi memorantur somnia non videri; quod unde eveniat, rerum scientissimis relinquamus.", "st": "15.3"}, {"sp": "N", "t": "Inter has quaestionum suppliciorumque species diras, in Illyrico exoritur alia clades, ad multorum pericula ex verborum inanitate progressa. In convivio Africani, Pannoniae secundae rectoris, apud Sirmium poculis amplioribus madefacti quidam, arbitrum adesse nullum existimantes, licenter imperium praesens ut molestissimum incusabant; quibus alii optatam permutationem temporum adventare, veluti e praesagiis affirmabant, non nulli maiorum augurio sibi portendi, incogitabili dementia promittebant.", "st": "15.3"}, {"sp": "N", "t": "E quorum numero Gaudentius agens in rebus, mente praecipiti stolidus, rem ut seriam detulerat ad Rufinum, apparitionis praefecturae praetorianae tune principem, ultimorum semper avidum hominem, et coalita pravitate famosum.", "st": "15.3"}, {"sp": "N", "t": "Qui confestim quasi pinnis elatus, ad comitatum principis advolavit, eumque ad suspiciones huius modi mollem et penetrabilem, ita acriter inflammavit, ut sine deliberatione ulla Africanus, et omnes letalis mensae participes, iuberentur rapi sublimes. Quo facto delator funestus, vetita ex more humano validius cupiens, biennio id quod agebat (ut postularat) continuare praeceptus est.", "st": "15.3"}, {"sp": "N", "t": "Missus igitur ad eos corripiendos Teutomeres protector domesticus cum collega onustos omnes catenis (ut mandatum est) perducebat. Sed ubi ventum est Aquileiam, Marinus tribunus ex campidoctore eo tempore vacans, auctor perniciosi sermonis, et alioqui naturae ferventis, in taberna relictus, dum parantur itineri necessaria, lateri cultrum longiorem casu repertum impegit, statimque extractis vitalibus, interiit.", "st": "15.3"}, {"sp": "N", "t": "Residui ducti Mediolanum, excruciatique tormentis, et confessi inter epulas petulanter se quaedam locutos, iussi sunt attineri poenalibus claustris, sub absolutionis aliqua spe (licet incerta). Protectores vero pronuntiati vertere solum exilio, ut Marino eisdem consciis mori permisso, veniam Arbetione meruere precante.", "st": "15.3"}, {"sp": "N", "t": "Re hoc modo finita, … et Lentiensibus, Alamannicis pagis, indictum est bellum, collimitia saepe Romana latius irrumpentibus. Ad quem procinctum imperator egressus, in Raetias camposque venit Caninos, et digestis diu consiliis, id visum est honestum et utile, ut eo cum militis parte ibidem opperiente, Arbetio magister equitum cum validiore exercitus manu, relegens margines lacus Brigantiae pergeret, protinus barbaris congressurus. Cuius loci figuram breviter quantum ratio patitur, designabo.", "st": "15.4"}, {"sp": "N", "t": "Inter montium celsorum amfractus, immani pulsu Rhenus exoriens, per scopulos extenditur altos, nullos advenas amnes adoptans, ut per cataractas inclinatione praecipiti funditur Nilus. Et navigari ab ortu poterat primigenio copiis exuberans propriis, ni ruenti curreret similis potius quam fluenti lenius amni.", "st": "15.4"}, {"sp": "N", "t": "Iamque ad plana volutus, altaque divortia riparum adradens, lacum invadit rotundum et vastum, quem Brigantiam accola Raetus appellat, perque quadringenta et sexaginta stadia longum, parique paene spatio late diffusum, horrore silvarum squalentium inaccessum, nisi qua vetus illa Romana virtus et sobria iter composuit latum, barbaris et natura locorum et caeli inclementia refragante.", "st": "15.4"}, {"sp": "N", "t": "Hanc ergo paludem spumosis strependo verticibus amnis irrumpens, et undarum quietem permeans pigram, mediam velut finali intersecat libramento, et tamquam elementum perenni discordia separatum, nec aucto nec imminuto agmine quod intulit, vocabulo et viribus absolvitur integris, nec contagia deinde ulla perpetiens, oceani gurgitibus intimatur.", "st": "15.4"}, {"sp": "N", "t": "Quodque est impendio mirum, nec stagnum aquarum rapido transcursu movetur, nec limosa subluvie tardatur properans flumen, et confusum misceri non potest corpus; quod, ni ita agi ipse doceret aspectus, nulla vi credebatur posse discerni.", "st": "15.4"}, {"sp": "N", "t": "Sic Alpheus oriens in Arcadia, cupidine fontis Arethusae captus, scindens Ionium mare, ut fabulae ferunt, ad usque amatae confinia proruit nymphae.", "st": "15.4"}, {"sp": "N", "t": "Arbetio qui adventus barbarorum nuntiarent non exspectans dum adessent, licet sciret aspera orta bellorum, in occultas delatus insidias, stetit immobilis, malo repentino perculsus.", "st": "15.4"}, {"sp": "N", "t": "Namque improvisi e latebris hostes exsiliunt, et sine parsimonia quicquid offendi poterat telorum genere multiplici configebant; nec enim resistere nostrorum quisquam potuit, nec aliud vitae subsidium, nisi discessu sperare veloci. Quocirca vulneribus declinandis intenti, incomposito agmine milites huc et illuc dispalantes, terga ferienda dederunt. Plerique tamen per angustas semitas sparsi, periculoque praesidio tenebrosae noctis extracti, revoluta iam luce, redintegratis viribus agmini quisque proprio sese consociavit. In quo casu ita tristi et inopino, abundans numerus armatorum, et tribuni desiderati sunt decem.", "st": "15.4"}, {"sp": "N", "t": "Ob quae Alamanni sublatis animis ferocius incedentes secuto die prope munimenta Romana, adimente matutina nebula lucem, strictis mucronibus discurrebant, frendendo minas tumidas intentantes. Egressique repente scutarii, cum obiectu turmarum hostilium repercussi stetissent, omnes suos conspiratis mentibus ciebant ad pugnam.", "st": "15.4"}, {"sp": "N", "t": "Verum cum plerosque recentis aerumnae documenta terrerent, et intuta fore residua credens haereret Arbetio, tres simul exsiluere tribuni, Arintheus agens vicem armaturarum rectoris, et Seniachus qui equestrem turmam comitum tuebatur, et Bappo ducens promotos.", "st": "15.4"}, {"sp": "N", "t": "Qui cum commissis sibi militibus, pro causa communi se velut propria Deciorum veterum exemplo voventes, more fluminis hostibus superfusi, non iusto proelio sed discursionibus rapidis, universos in fugam coegere foedissimam. Qui dispersi laxatis ordinibus, dumque elabi properant impediti, corpora nudantes intecta, gladiorum hastarumque densis ictibus truncabantur.", "st": "15.4"}, {"sp": "N", "t": "Multique cum equis interfecti iacentes, etiam tum eorum dorsis videbantur innexi; quo viso omnes e castris effusi, qui prodire in proelium cum sociis ambigebant, cavendi immemores, proterebant barbaram plebem, nisi quos fuga exemerat morte, calcantes cadaverum strues, et perfusi sanie peremptorum.", "st": "15.4"}, {"sp": "N", "t": "Hocque exitu proelio terminate, imperator Mediolanum ad hiberna ovans revertit et laetus.", "st": "15.4"}, {"sp": "N", "t": "Exoritur iam hinc rebus afflictis, haut dispari provinciarum malo calamitatum turbo novarum, exstincturus omnia simul, ni Fortuna moderatrix humanorum casuum motum eventu celeri consummavit, impendio formidatum.", "st": "15.5"}, {"sp": "N", "t": "Cum diuturna incuria Galliae caedes acerbas rapinasque et incendia, barbaris licenter grassantibus, nullo iuvante perferrent, Silvanus pedestris militiae rector, ut efficax ad haec corrigenda, principis iussu perrexit, Arbetione id maturari modis quibus poterat adigente, ut absenti aemulo quem superesse adhuc gravabatur periculosae molis onus impingeret.", "st": "15.5"}, {"sp": "N", "t": "Dynamius quidam actuarius sarcinalium principis iumentorum, commendaticias ab eo petierat litteras ad amicos, ut quasi familiaris eiusdem esset notissimus. Hoc impetrato, cum ille nihil suspicans simpliciter praestitisset, servabat epistulas, ut perniciosum aliquid in tempore moliretur.", "st": "15.5"}, {"sp": "N", "t": "Memorato itaque duce Gallias ex re publica discursante, barbarosque propellente, iam sibi diffidentes et trepidantes, idem Dynamius inquietius agens, ut versutus et in fallendo exercitatus, fraudem comminiscitur impiam, subornatore et conscio, ut iactavere rumores incerti, Lampadio praefecto praetorio, et Eusebio ex comite rei privatae, cui cognomentum erat inditum Mattyocopae, atque Aedesio ex magistro memoriae, quos ad consulatum ut amicos iunctissimos idem curarat rogari praefectus; et peniculo serie litterarum abstersa, solaque incolumi relicta subscriptione, alter multum a vero illo dissonans superscribitur textus: velut Silvano rogante verbis obliquis, hortanteque amicos agentes intra palatium, vel privatos, inter quos et Tuscus erat Albinus, aliique plures, ut se altiora coeptantem, et prope diem loci principalis aditum petiturum iuvarent.", "st": "15.5"}, {"sp": "N", "t": "Hunc fascem ad arbitrium figmenti compositum, vitam pulsaturum insontis, a Dynamio susceptum praefectus imperatori, avide scrutari haec et similia consueto, secrete obtulit soli, ingressus intimum conclave in tempore, deinde sperans accepturum se a principe praemium, ut pervigilem salutis eius custodem et cautum, lectaque consistorio astu callido consarcinata materia, tribuni iussi sunt custodiri, et de provinciis duci privati, quorum epistulae nomina designabant.", "st": "15.5"}, {"sp": "N", "t": "Confestimque iniquitate rei percitus Malarichus, gentilium rector, collegis adhibitis strepebat immaniter, circumveniri homines dicatos imperio per factiones et dolos minime debere proclamans, petebatque ut ipse relictis obsidum loco necessitudinibus suis, Mallobaude armaturarum tribuno spondente quod remeabit, velocius iuberetur ire ducturus Silvanum, aggredi nihil tale conatum, quale insidiatores acerrimi concitarunt; vel contra se paria promittente, Mallobaudem orabat properare permitti, haec quae ipse pollicitus est impleturum.", "st": "15.5"}, {"sp": "N", "t": "Testabatur enim id se procul dubio scire, quod siqui mitteretur externus, suopte ingenio Silvanus etiam nulla re perterrente timidior, composita forte turbabit.", "st": "15.5"}, {"sp": "N", "t": "Et quamquam utilia moneret et necessaria, ventis tamen loquebatur incassum. Namque Arbetione auctore, Apodemius ad eum vocandum cum litteris mittitur, inimicus bonorum omnium diuturnus et gravis. Qui incidentia parvi ducens cum venisset in Gallias, dissidens a mandatis, quae proficiscenti sunt data, nec viso Silvano nec oblatis scriptis ut veniret admonito, remansit adscitoque rationali, quasi proscripti iamque necandi magistri peditum clientes et servos hostili tumore vexabat.", "st": "15.5"}, {"sp": "N", "t": "Inter haec tamen dum praesentia Silvani speratur, et Apodemius quieta perturbat, Dynamius ut argumento validiore impie structorum adsereret fidem, compositas litteras his concinentes quas obtulerat principi per praefectum, ad tribunum miserat fabricae Cremonensis, nomine Silvani et Malarichi, a quibus ut arcanorum conscius monebatur parare propere cuncta.", "st": "15.5"}, {"sp": "N", "t": "Qui cum haec legisset, haerens et ambigens diu quidnam id esset—nec enim meminerat secum aliquando super negotio ullo interiore hos quorum litteras acceperat collocutos—epistulas ipsas per baiulum qui portarat, iuncto milite ad Malarichum remisit, obsecrans ut doceret aperte quae vellet, non ita perplexe; nec enim intellexisse firmabat, ut subagrestem et simplicem, quid significatum esset obscurius.", "st": "15.5"}, {"sp": "N", "t": "Haec Malarichus subito nanctus, etiam tunc squalens et maestus, suamque et popularis Silvani vicem graviter ingemiscens, adhibitis Francis, quorum ea tempestate in palatio multitudo florebat, erectius iam loquebatur; tumultuando patefactis insidiis reserataque iam fallacia, per quam ex confesso salus eorum appetebatur.", "st": "15.5"}, {"sp": "N", "t": "Hisque cognitis statuit imperator, dispicientibus consistorianis et militaribus universis, in negotium perspicaciter inquiri. Cumque iudices resedissent, Florentius Nigriniani filius agens tune pro magistro officiorum, contemplans diligentius scripta, apicumque pristinorum quasi quandam umbram repperiens animadvertit (ut factum est) priore textu interpolato longe alia quam dictarat Silvanus, ex libidine consarcinatae falsitatis adscripta.", "st": "15.5"}, {"sp": "N", "t": "Proinde fallaciarum nube discussa, imperator doctus gesta relatione fideli, abrogata potestate praefectum statui sub quaestione praecepit, sed absolutus est enixa conspiratione multorum. Suspensus autem Eusebius ex comite privatarum, se conscio haec dixerat concitata.", "st": "15.5"}, {"sp": "N", "t": "Aedesius omnino nescisse quid actum sit pertinaci infitiatione contendens, abiit innoxius, et ita finito negotio, omnes sunt absoluti quos exhiberi delatio compulit criminosa. Dynamius vero ut praeclaris artibus illustratus, cum correctoris dignitate regere iussus est Tuscos et Umbros.", "st": "15.5"}, {"sp": "N", "t": "Agens inter haec apud Agrippinam Silvanus, assiduisque suorum comperiens nuntiis, quae Apodemius in labem suarum ageret fortunarum, et sciens animum tenerum versabilis principis, timensque ne trucidaretur absens et inauditus, in difficultate positus maxima, barbaricae se fidei committere cogitabat.", "st": "15.5"}, {"sp": "N", "t": "Sed Laniogaiso vetante (tunc tribuno) quem dum militaret candidatus solum adfuisse morituro Constanti supra rettulimus, docenteque Francos, unde oriebatur, interfecturos eum aut accepto praemio prodituros, nihil tutum ex praesentibus ratus, in consilia agitabatur extrema et sensim cum principiorum verticibus erectius collocutus, eisdemque magnitudine promissae mercedis accensis, cultu purpureo a draconum et vexillorum insignibus ad tempus abstracto, ad culmen imperiale surrexit.", "st": "15.5"}, {"sp": "N", "t": "Dumque haec aguntur in Galliis, ad occasum inclinato iam die, perfertur Mediolanum insperabilis nuntius, aperte Silvanum demonstrans, dum ex magisterio peditum altius nititur, sollicitato exercitu ad augustum culmen evectum.", "st": "15.5"}, {"sp": "N", "t": "Hac mole casus inopini Constantio icto, quasi fulmine Fati, primates, consilio secunda vigilia convocato, properarunt omnes in regiam. Cumque nulli ad eligendum quid agi deberet, mens suppetere posset aut lingua, submissis verbis perstringebatur Ursicini mentio, ut consiliis rei bellicae praestantissimi, frustraque gravi iniuria lacessiti, et per admissionum magistrum—qui mos est honoratior—accito eodem, ingresso consistorium offertur purpura multo quam antea placidius. Diocletianus enim Augustus omnium primus, externo et regio more instituit adorari, cum semper antea ad similitudinem iudicum salutatos principes legerimus.", "st": "15.5"}, {"sp": "N", "t": "Et qui paulo antea cum insectatione malivola, orientis vorago, invadendaeque summae rei per filios affectator compellabatur, tune dux prudentissimus, et Constantini magnus erat commilito, solusque ad extinguendum, probis quidem sed insidiosis rationibus petebatur. Diligens enim opera navabatur, exstingui Silvanum, ut fortissimum perduellem, aut (si secus accidisset) Ursicinum exulceratum iam penitus aboleri, ne superesset scopulus impendio formidandus.", "st": "15.5"}, {"sp": "N", "t": "Igitur cum de profectione celeranda disponeretur, propulsationem obiectorum criminum eundem ducem parantem praegressus, oratione leni prohibet imperator, non id esse memorans tempus, ut controversa defensio causae susciperetur, cum vicissim restitui in pristinam concordiam partes necessitas subigeret urgentium rerum, antequam cresceret mollienda.", "st": "15.5"}, {"sp": "N", "t": "Habita igitur deliberatione multiplici, id potissimum tractabatur, quo commento Silvanus gesta etiam tum imperatorem ignorare existimaret. Et probabili argumento ad firmandam fidem reperto monetur honorificis scriptis, ut accepto Ursicino successore cum potestate rediret intacta.", "st": "15.5"}, {"sp": "N", "t": "Post haec ita digesta protinus iubetur exire, tribunis et protectoribus domesticis decem, ut postularat, ad iuvandas necessitates publicas ei coniunctis, inter quos ego quoque eram cum Veriniano collega, residui omnes propinqui et familiares.", "st": "15.5"}, {"sp": "N", "t": "Iamque eum egressum solum de se metuens quisque per longa spatia deducebat. Et quamquam ut bestiarii obiceremur intractabilibus feris, perpendentes tamen hoc bonum habere tristia accidentia, quod in locum suum secunda substituunt, mirabamur illam sententiam Tullianam, ex internis veritatis ipsius promulgatam, quae est talis: “Et quamquam optatissimum est perpetuo fortunam quam florentissimam permanere, illa tamen aequalitas vitae non tantum habet sensum, quantum cum ex miseris et perditis rebus ad meliorem statum fortuna revocatur.”", "st": "15.5"}, {"sp": "N", "t": "Festinamus itaque itineribus magnis, ut ambitiosus magister armorum, ante allapsum per Italicos de tyrannide ullum Rumorem, in suspectis finibus appareret, verum cursim nos properantes aeria quadam via antevolans prodiderat Fama, et Agrippinam ingressi, invenimus cuncta nostris conatibus altiora.", "st": "15.5"}, {"sp": "N", "t": "Namque convena undique multitudine trepide coepta fundante, coactisque copiis multis, pro statu rei praesentis id aptius videbatur, ut ad imperatoris novelli, per ludibriosa auspicia virium accessu firmandi sensum ac voluntatem dux flexibilis verteretur; quo variis assentandi figmentis in mollius vergente securitate, nihil metuens hostile deciperetur.", "st": "15.5"}, {"sp": "N", "t": "Cuius rei finis arduus videbatur; erat enim cautius observandum, ut appetitus opportunitati obtemperarent, nec praecurrentes eam nec deserentes. Qui si eluxissent intempestive, constabat nos omnes sub elogio uno morte multandos.", "st": "15.5"}, {"sp": "N", "t": "Susceptus tamen idem dux leniter adactusque, inclinante negotio ipso cervices, adorare sollemniter anhelantem celsius purpuratum, ut spectabilis colebatur et intimus: facilitate aditus honoreque mensae regalis adeo antepositus aliis, ut iam secretius de rerum summa consultaretur.", "st": "15.5"}, {"sp": "N", "t": "Aegre ferebat Silvanus ad consulatum potestatesque sublimes elatis indignis, se et Ursicinum solos post exsudatos magnos pro re publica labores et crebros, ita fuisse despectos, ut ipse quidem per quaestiones familiarium sub disceptatione ignobili crudeliter agitatus, commisisse in maiestatem arcesseretur, alter vero ab oriente raptus odiis inimicorum addiceretur; et haec assidue clam querebatur et palam.", "st": "15.5"}, {"sp": "N", "t": "Terrebant nos tamen, cum dicerentur haec et similia, circumfrementia undique murmura causantis inopiam militis, et rapida celeritate ardentis angustias Alpium perrumpere Cottiarum.", "st": "15.5"}, {"sp": "N", "t": "In hoc aestu mentis ancipiti, ad effectum tendens consilium occulta scrutabamur indagine, sederatque tandem mutatis prae timore saepe sententiis, ut quaesitis magna industria cautis rei ministris, obstricto religionum consecratione colloquio, Bracchiati sollicitarentur atque Cornuti, fluxioris fidei et ubertate mercedis ad momentum omne versabiles.", "st": "15.5"}, {"sp": "N", "t": "Firmato itaque negotio per sequestres quosdam gregarios, obscuritate ipsa ad id patrandum idoneos, praemiorum exspectatione accensus solis ortu iam rutilo, subitus armatorum globus erupit, atque ut solet in dubiis rebus, audentior caesis custodibus, regia penetrata, Silvanum extractum aedicula, quo exanimatus confugerat, ad conventiculum ritus Christiani tendentem, densis gladiorum ictibus trucidarunt.", "st": "15.5"}, {"sp": "N", "t": "Ita dux haut exsilium meritorum hoc genere oppetit mortis, metu calumniarum, quibus factione iniquorum irretitus est absens, ut tueri possit salutem, ad praesidia progressus extrema.", "st": "15.5"}, {"sp": "N", "t": "Licet enim ob tempestivam illam cum armaturis proditionem ante Mursense proelium obligatum gratia retineret Constantium, ut dubium tamen et mutabilem verebatur, licet patris quoque Boniti praetenderet fortia facta, Franci quidem sed pro Constantini partibus in bello civili acriter contra Licinianos saepe versati.", "st": "15.5"}, {"sp": "N", "t": "Evenerat autem ut, antequam huius modi aliquid agitaretur in Galliis, Romae in Circo maximo populus, incertum relatione quadam percitus an praesagio, “Silvanus devictus est” magnis vocibus exclamaret.", "st": "15.5"}, {"sp": "N", "t": "Igitur Silvano Agrippinae (ut relatum est) interfecto, inaestimabili gaudio re cognita princeps, insolentia coalitus et tumore, hoc quoque felicitatis suae prosperis cursibus assignabat, eo more quo semper oderat fortiter facientes, ut quondam Domitianus, superare tamen quacumque arte contraria cupiebat.", "st": "15.5"}, {"sp": "N", "t": "Tantumque afuit laudare industrie gesta, ut etiam quaedam scriberet de Gallicanis intercepta thesauris, quos nemo attigerat. Idque scrutari iusserat artius interrogate Remigio, etiam tum rationario apparitionis armorum magistri, cui multo postea Valentiniani temporibus laques vitam in causa Tripolitanae legationis, eripuit.", "st": "15.5"}, {"sp": "N", "t": "Post quae ita completa, Constantius ut iam caelo contiguus, casibusque imperaturus humanis, magniloquentia sufflabatur adulatorum, quos augebat ipse spernendo proiciendoque id genus parum callentes, ut Croesum legimus ideo regno suo Solonem expulisse praecipitem, quia blandiri nesciebat; et Dionysium intentasse poetae Philoxeno mortem, cum eum recitantem proprios versus absurdos et inconcinnos, laudantibus cunctis, solus audiret immobilis.", "st": "15.5"}, {"sp": "N", "t": "Quae res perniciosa vitiorum est altrix. Ea demum enim laus grata esse potestati debet excelsae, cum interdum et vituperationi secus gestorum pateat locus.", "st": "15.5"}, {"sp": "N", "t": "Iamque post securitatem quaestiones agitabantur ex more, et vinculis catenisque plures ut noxii plectebantur. Exsurgebat enim effervens laetitia Paulus, tartareus ille delator, ad venenatas artes suas licentius exercendas, et inquirentibus in negotium consistorianis atque militaribus (ut praeceptum est) Proculus admovetur eculeo, Silvani domesticus, homo gracilis et morbosus, metuentibus cunctis, ne vi nimia tormentorum, levi corpore fatigato, reos atrocium criminum promiscue citari faceret multos. Verum contra quam speratum est contigit.", "st": "15.6"}, {"sp": "N", "t": "Memor enim somnii quo vetitus erat per quietem (ut ipse firmavit) pulsare quendam insontem, usque ad confinia mortis vexatus, nec nominavit nec prodidit aliquem, sed asserebat factum Silvani constanter, id eum cogitasse quod iniit, non cupiditate sed necessitate compulsum, argumento evidenti demonstrans.", "st": "15.6"}, {"sp": "N", "t": "Causam enim probabilem ponebat in medio, multorum testimoniis claram, quod die quinto antequam infulas susciperet principatus, donatum stipendio militem Constanti nomine allocutus est, fortis esset et fidus. Unde apparebat quod si praesumere fortunae superioris insignia conaretur, auri tam grave pondus largiretur ut suum.", "st": "15.6"}, {"sp": "N", "t": "Post hunc damnatorum sorte Poemenius raptus ad supplicium interiit, qui (ut supra rettulimus) cum Treveri civitatem Caesari clausissent Decentio, ad defendendam plebem electus est. Tum Asclepiodotus et Lutto et Maudio comites interempti sunt, aliique plures, haec et similia perplexe temporis obstinatione scrutante.", "st": "15.6"}, {"sp": "N", "t": "Dum has exitiorum communium clades suscitat turbo feralis, urbem aeternam Leontius regens, multa spectati iudicis documenta praebebat, in audiendo celerior, in disceptando iustissimus, natura benevolus, licet auctoritatis causa servandae acer quibusdam videbatur, et inclinatior ad damnandum.", "st": "15.7"}, {"sp": "N", "t": "Prima igitur causa seditionis in eum concitandae vilissima fuit et levis. Philoromum enim aurigam rapi praeceptum, secuta plebs omnis, velut defensura proprium pignus, terribili impetu praefectum incessebat ut timidum, sed ille stabilis et erectus, immissis apparitoribus, correptos aliquos vexatosque tormentis, nec strepente ullo nec obsistente, insulari poena multavit.", "st": "15.7"}, {"sp": "N", "t": "Diebusque paucis secutis cum itidem plebs excita calore quo consuevit, vini causando inopiam, ad Septemzodium convenisset, celebrem locum, ubi operis ambitiosi Nymphaeum Marcus condidit imperator, illuc de industria pergens praefectus, ab omni toga apparitioneque rogabatur enixius, ne in multitudinem se arrogantem immitteret et minacem, ex commotione pristina saevientem; difficilis ad pavorem, recta tetendit, adeo ut eum obsequentium pars desereret, licet in periculum festinantem abruptum.", "st": "15.7"}, {"sp": "N", "t": "Insidens itaque vehiculo, cum speciosa fiducia contuebatur acribus oculis tumultuantium undique cuneorum, veluti serpentium vultus, perpessusque multa dici probrosa, agnitum quendam inter alios eminentem vasti corporis rutilique capilli, interrogavit, an ipse esset Petrus Valuomeres (ut audierat) cognomento; eumque cum esse sonu respondisset obiurgatorio, ut seditiosorum antesignanum olim sibi compertum, reclamantibus multis, post terga manibus vinctis, suspendi praecepit.", "st": "15.7"}, {"sp": "N", "t": "Quo viso sublimi, tribuliumque adiumentum nequicquam implorante, vulgus omne paulo ante confertum, per varia urbis membra diffusum, ita evanuit ut turbarum acerrimus concitor, tamquam in iudiciali secreto exaratis lateribus, ad Picenum eiceretur, ubi postea ausus eripere virginis non obscurae pudorem, Patruini consularis sententia supplicio est capitali addictus.", "st": "15.7"}, {"sp": "N", "t": "Hoc administrante Leontio, Liberius Christianae legis antistes, a Constantio ad comitatum mitti praeceptus est, tamquam imperatoriis iussis et plurimorum sui consortium decretis obsistens, in re quam brevi textu percurram.", "st": "15.7"}, {"sp": "N", "t": "Athanasium episcopum eo tempore apud Alexandriam, ultra professionem altius se efferentem, scitarique conatum externa, ut prodidere rumores assidui, coetus in unum quaesitus eiusdem legis cultorum (synodus ut appellant) removit a sacramento quod optinebat.", "st": "15.7"}, {"sp": "N", "t": "Dicebatur enim fatidicarum sortium fidem, quaeve augurales portenderent alites, scientissime callens, aliquotiens praedixisse futura; super his intendebantur ei alia quoque, a proposito legis abhorrentia cui praesidebat.", "st": "15.7"}, {"sp": "N", "t": "Hunc per subscriptionem abicere sede sacerdotali, paria sentiens ceteris, iubente principe Liberius monitus, perseveranter renitebatur, nec visum hominem nec auditum damnare nefas ultimum saepe exclamans, aperte scilicet recalcitrans imperatoris arbitrio.", "st": "15.7"}, {"sp": "N", "t": "Id enim ille Athanasio semper infestus, licet sciret impletum, tamen auctoritate quoque potiore aeternae urbis episcopi firmari desiderio nitebatur ardenti; quo non impetrato, Liberius aegre populi metu, qui eius amore flagrabat, cum magna difficultate noctis medio potuit asportari.", "st": "15.7"}, {"sp": "N", "t": "Et haec quidem Romae (ut ostendit textus superior) agebantur. Constantium vero exagitabant assidui nuntii, deploratas iam Gallias indicantes, nullo renitente ad internecionem barbaris vastantibus universa; aestuansque diu qua vi propulsaret aerumnas, ipse in Italia residens, ut cupiebat periculosum enim existimabat se in partem contrudere longe dimotam—repperit tandem consilium rectum, et Iulianum patruelem fratrem haut ita dudum ab Achaico tractu accitum, etiam tum palliatum, in societatem imperii adsciscere cogitabat.", "st": "15.8"}, {"sp": "N", "t": "Id ubi, urgente malorum impendentium mole, confessus est proximis, succumbere tot necessitatibus tamque crebris unum se (quod numquam fecerat) aperte demonstrans, illi in assentationem nimiam eruditi, infatuabant hominem, nihil esse ita asperum dictitantes, quod praepotens eius virtus, fortunaque tam vicina sideribus, non superaret ex more. Addebantque noxarum conscientia stimulante complures, deinceps caveri debere Caesaris nomen, replicantes gesta sub Gallo.", "st": "15.8"}, {"sp": "N", "t": "Quis annitentibus obstinate opponebat se sola regina, incertum migrationem ad longinqua pertimescens, an pro nativa prudentia consulens in commune, omnibusque memorans anteponi debere propinquum. Post multa itaque per deliberationes ambiguas actitata, stetit fixa sententia, abiectisque disputationibus irritis, ad imperium placuit Iulianum assumere.", "st": "15.8"}, {"sp": "N", "t": "Et cum venisset accitus, praedicto die advocato omni quod aderat commilitio, tribunali ad altiorem suggestum erecto, quod aquilae circumdederunt et signa, Augustus insistens eumque manu retinens dextera, haec sermone placido peroravit:", "st": "15.8"}, {"sp": "N", "t": "“Adsistimus apud vos—optimi rei publicae defensores—causae communi uno paene omnium spiritu vindicandae, quam acturus tamquam apud aequos iudices succinctius edocebo.", "st": "15.8"}, {"sp": "N", "t": "“Post interitum rebellium tyrannorum, quos ad haec temptanda quae moverunt, rabies egit et furor, velut impiis eorum manibus Romano sanguine parentantes, persultant barbari Gallias, rupta limitum pace; hac animati fiducia, quod nos per disiunctissimas terras arduae necessitates adstringunt.", "st": "15.8"}, {"sp": "N", "t": "“Huic igitur malo ultra apposita iam proserpenti, si dum patitur tempus, occurrerit nostri vestrique consulti suffragium, et colla superbarum gentium detumescent, et imperii fines erunt intacti. Restat ut venturorum spem quam gero secundo roboretis effectu.", "st": "15.8"}, {"sp": "N", "t": "“Iulianum hunc fratrem meum patruelem (ut nostis,) verecundia qua nobis ita ut necessitudine carus est, recte spectatum, iamque elucentis industriae iuvenem, in Caesaris adhibere potestatem exopto, coeptis (si videntur utilia) etiam vestra consensione firmandis.”", "st": "15.8"}, {"sp": "N", "t": "Dicere super his plura conantem, interpellans contio lenius prohibebat, arbitrium summi numinis id esse non mentis humanae velut praescia venturi proclamans.", "st": "15.8"}, {"sp": "N", "t": "Stansque imperator immobilis dum silerent, residua fidentius explicavit: “Quia igitur vestrum quoque favorem adesse fremitus indicat laetus, adulescens vigoris tranquilli, cuius temperati mores imitandi sunt potius quam praedicandi, ad honorem prosperante deo delatum exsurgat; cuius praeclaram indolem bonis artibus institutam, hoc ipso plene videor exposuisse quod elegi. Ergo eum, praesente nutu dei caelestis, amictu principali velabo.”", "st": "15.8"}, {"sp": "N", "t": "Dixit moxque indutum avita purpura Iulianum, et Caesarem cum exercitus gaudio declaratum, his alloquitur contractiore vultu submaestum:", "st": "15.8"}, {"sp": "N", "t": "“Recepisti primaevus originis tuae splendidum florem, amantissime mihi omnium frater; aucta gloria mea, confiteor, qui iustius in deferenda suppari potestate nobilitati mihi propinquae, quam ipsa potestate videor esse sublimis.", "st": "15.8"}, {"sp": "N", "t": "“Adesto igitur laborum periculorumque particeps, et tutelam ministerii suscipe Galliarum, omni beneficentia partes levaturus afflictas: et si hostilibus congredi sit necesse, fixo gradu consiste inter signiferos ipsos, audendi in tempore consideratus hortator, pugnantes accendens praeeundo cautissime, turbatosque subsidiis fulciens, modesteque increpans desides, verissimus testis adfuturus industriis et ignavis.", "st": "15.8"}, {"sp": "N", "t": "“Proinde urgente rei magnitudine, perge vir fortis, ducturus viros itidem fortes. Aderimus nobis vicissim amoris robusta constantia, militabimus simul, una orbem pacatum, deus modo velit quod oramus, pari moderatione pietateque recturi. Mecum ubique videberis praesens, et ego tibi quodcumque acturo non deero. Ad summam i, propera sociis omnium votis, velut assignatam tibi ab ipsa re publica, stationem cura pervigili defensurus.”", "st": "15.8"}, {"sp": "N", "t": "Nemo post haec finita reticuit, sed militares omnes horrendo fragore scuta genibus illidentes (quod est prosperitatis indicium plenum; nam contra cum hastis clipei feriuntur, irae documentum est et doloris) immane quo quantoque gaudio praeter paucos Augusti probavere iudicium, Caesaremque admiratione digna suscipiebant, imperatorii muricis fulgore flagrantem.", "st": "15.8"}, {"sp": "N", "t": "Cuius oculos cum venustate terribilis, vultumque excitatius gratum, diu multumque contuentes, qui futurus sit colligebant velut scrutatis veteribus libris, quorum lectio per corporum signa pandit animorum interna. Eumque ut potiori reverentia servaretur, nec supra modum laudabant, nec infra quam decebat, atque ideo censorum voces sunt aestimatae, non militum.", "st": "15.8"}, {"sp": "N", "t": "Susceptus denique ad consessum vehiculi, receptusque in regiam, hunc versum ex Homerico carmine susurrabat:<br>ἔλλαβε πορφύρεος θάνατος καὶ μοῖρα κραταιή.", "st": "15.8"}, {"sp": "N", "t": "Haec diem octavum iduum Novembrium gesta sunt, cum Arbetionem consulem annus haberet et Lollianum.", "st": "15.8"}, {"sp": "N", "t": "Deinde diebus paucis Helena virgine, Constanti sorore, eidem Caesari iugali foedere copulata, paratisque universis quae maturitas proficiscendi poscebat, comitatu parvo suscepto, kalendis Decembribus egressus est deductusque ab Augusto ad usque locum duabus columnis insignem, qui Laumellum interiacet et Ticinum, itineribus rectis Taurinos pervenit, ubi nuntio percellitur gravi, qui nuper in comitatum Augusti perlatus, de industria silebatur, ne parata diffluerent.", "st": "15.8"}, {"sp": "N", "t": "Indicabat autem Coloniam Agrippinam, ampli nominis urbem in secunda Germania, pertinaci barbarorum obsidione reseratam magnis viribus et deletam.", "st": "15.8"}, {"sp": "N", "t": "Quo maerore perculsus, velut primo adventantium malorum auspicio, murmurans querulis vocibus saepe audiebatur: nihil se plus assecutum, quam ut occupatior interiret.", "st": "15.8"}, {"sp": "N", "t": "Cumque Viennam venisset, ingredientem optatum quidem et impetrabilem honorifice susceptura omnis aetas concurrebat et dignitas, proculque visum plebs universa, cum vicinitate finitima, imperatorem clementem appellans et faustum, praevia consonis laudibus celebrabat, avidius pompam regiam in principe legitimo cernens: communiumque remedium aerumnarum in eius locabat adventu, salutarem quendam genium affulsisse conclamatis negotiis arbitrata.", "st": "15.8"}, {"sp": "N", "t": "tunc anus quaedam orba luminibus, cum percontando quinam esset ingressus, Iulianum Caesarem comperisset, exclamavit hunc deorum templa reparaturum.", "st": "15.8"}, {"sp": "N", "t": "Proinde quoniam—ut Mantuanus vates praedixit excelsus—“maius opus moveo” maiorque mihi rerum nascitur ordo, Galliarum tractus et situm ostendere puto nunc tempestivum, ne inter procinctus ardentes, proeliorumque varios casus, ignota quibusdam expediens imitari videar desides nauticos, attrita lintea cum rudentibus, quae licuit parari securius, inter fluctus resarcire coactos et tempestates.", "st": "15.9"}, {"sp": "N", "t": "Ambigentes super origine prima Gallorum, scriptores veteres notitiam reliquere negotii semiplenam, sed postea Timagenes, et diligentia Graecus et lingua, haec quae diu sunt ignorata collegit ex multiplicibus libris. Cuius fidem secuti, obscuritate dimota, eadem distincte docebimus et aperte.", "st": "15.9"}, {"sp": "N", "t": "Aborigines primos in his regionibus quidam visos esse firmarunt, Celtas nomine regis amabilis et matris eius vocabulo Galatas dictos—ita enim Gallos sermo Graecus appellat—alii Dorienses antiquiorem secutos Herculem oceani locos inhabitasse confines.", "st": "15.9"}, {"sp": "N", "t": "Drysidae memorant re vera fuisse populi partem indigenam, sed alios quoque ab insulis extimis confluxisse et tractibus transrhenanis, crebritate bellorum et alluvione fervidi maris sedibus suis expulsos.", "st": "15.9"}, {"sp": "N", "t": "Aiunt quidam paucos post excidium Troiae fugitantes Graecos ubique dispersos loca haec occupasse tunc vacua.", "st": "15.9"}, {"sp": "N", "t": "Regionum autem incolae id magis omnibus asseverant, quod etiam nos legimus in monumentis eorum incisum, Amphitryonis filium Herculem ad Geryonis et Taurisci saevum tyrannorum perniciem festinasse, quorum alter Hispanias, alter Gallias infestabat; superatisque ambobus, coisse cum generosis feminis suscepisseque liberos plures, et eos partes quibus imperitabant suis nominibus appellasse.", "st": "15.9"}, {"sp": "N", "t": "A Phocaea vero Asiaticus populus, Harpali inclementiam vitans, Cyri regis praefecti, Italiam navigio petit. Cuius pars in Lucania Veliam, alia condidit in Viennensi Massiliam: dein secutis aetatibus oppida, aucta virium copia, instituere non pauca. Sed declinanda varietas saepe satietati coniuncta.", "st": "15.9"}, {"sp": "N", "t": "Per haec loca hominibus paulatim excultis, viguere studia laudabilium doctrinarum, inchoata per bardos et euhagis et drasidas. Et Bardi quidem fortia virorum illustrium facta, heroicis composita versibus, cum dulcibus lyrae modulis cantitarunt, Euhages vero scrutantes sublimia, leges naturae pandere conabantur internas. Drysidae ingeniis celsiores, ut auctoritas Pythagorae decrevit, sodaliciis astricti consortiis, quaestionibus occultarum rerum altarumque erecti sunt, et despectantes humana, pronuntiarunt animas immortales.", "st": "15.9"}, {"sp": "N", "t": "Hanc Galliarum plagam ob suggestus montium arduos, et horrore nivali semper obductos, orbis residui incolis antehac paene ignotam, nisi qua litoribus est vicina, munimina claudunt undique natura velut arte circumdata.", "st": "15.10"}, {"sp": "N", "t": "Et a latere quidem australi, Tyrrheno alluitur et Gallico mari; qua caeleste suspicit plaustrum, a feris gentibus fluentis distinguitur Rheni; ubi occidentali subiecta est sideri, oceano et altitudine Pyrenaea arcetur; unde ad solis ortus attollitur, aggeribus cedit Alpium Cottiarum; quas rex Cottius perdomitis Galliis, solus in angustiis latens, inviaque locorum asperitate confisus, lenito tandem tumore, in amicitiam principis Octaviani receptus molibus magnis exstruxit, ad vicem memorabilis muneris, compendiarias et viantibus opportunas, medias inter alias Alpes vetustas, super quibus comperta paulo postea referemus.", "st": "15.10"}, {"sp": "N", "t": "In his Alpibus Cottiis, quarum initium a Segusione est oppido, praecelsum erigitur iugum, nulli fere sine discrimine penetrabile.", "st": "15.10"}, {"sp": "N", "t": "Est enim e Galliis venientibus prona humilitate devexum, pendentium saxorum altrinsecus visu terribile praesertim verno tempore, cum liquente gelu nivibusque solutis flatu calidiore ventorum, per diruptas utrimque angustias et lacunas, pruinarum congerie latebrosas, descendentes cunctantibus plantis homines et iumenta procidunt et carpenta; idque remedium ad arcendum exitium repertum est solum, quod pleraque vehicula vastis funibus illigata pone cohibente virorum vel boum nisu valido vix gressu reptante, paulo tutius devolvuntur. Et haec (ut diximus) anni verno contingunt.", "st": "15.10"}, {"sp": "N", "t": "Hieme vero humus crustata frigoribus et tamquam levigata ideoque labilis incessum praecipitantem impellit; et patulae valles per spatia plana glacie perfidae vorant non numquam transeuntes. Ob quae locorum callidi eminentes ligneos stilos per cautiora loca defigunt, ut eorum series viatorem ducat innoxium; qui si nivibus operti latuerint, aut montanis defluentibus rivis eversi, calles agrestibus praeviis difficile pervadunt.", "st": "15.10"}, {"sp": "N", "t": "A summitate autem huius Italici clivi, planities ad usque stationem nomine Martis per septem extenditur milia, et hinc alia celsitudo erectior, aegreque superabilis, ad Matronae porrigitur verticem, cuius vocabulum casus feminae nobilis dedit. Unde declive quidem iter sed expeditius ad usque castellum Brigantiam patet.", "st": "15.10"}, {"sp": "N", "t": "Huius sepulcrum reguli, quem itinera struxisse rettulimus, Segusione est moenibus proximum, manesque eius ratione gemina religiose coluntur, quod iusto moderamine rexerat suos, et asscitus in societatem rei Romanae, quietem genti praestitit sempiternam.", "st": "15.10"}, {"sp": "N", "t": "Et licet haec quam diximus viam media sit et compendiaria, magisque celebris, tamen etiam aliae multo antea temporibus sunt constructae diversis.", "st": "15.10"}, {"sp": "N", "t": "Et primam Thebaeus Hercules, ad Geryonem exstinguendum (ut relatum est) et Tauriscum lenius gradiens, prope maritimas composuit Alpes, hisque Graiarum indidit nomen; Monoeci similiter arcem et portum ad perennem sui memoriam consecravit. Deinde emensis postea saeculis multis, hac ex causa sunt Alpes excogitatae Poeninae.", "st": "15.10"}, {"sp": "N", "t": "Superioris Africani pater Publius Cornelius Scipio, Saguntinis memorabilibus aerumnis et fide, pertinaci destinatione Afrorum obsessis, iturus auxilio, in Hispaniam traduxit onustam manu valida classem, sed civitate potiore Marte deleta, Hannibalem sequi nequiens, triduo ante transito Rhodano, ad partes Italiae contendentem, navigatione veloci intercurso spatio maris haut longo, degressurum montibus apud Genuam observabat, Liguriae oppidum, ut cum eo (si copiam fors dedisset) viarum asperitate fatigato decerneret in planitie.", "st": "15.10"}, {"sp": "N", "t": "Consulens tamen rei communi, Cn. Scipionem fratrem ire monuit in Hispanias, ut Hasdrubalem exinde similiter erupturum arceret. Quae Hannibal doctus a perfugis, ut erat expeditae mentis et callidae, Taurinis ducentibus accolis, per Tricasinos et oram Vocontiorum extremam, ad saltus Tricorios venit. Indeque exorsus, aliud iter antehac insuperabile fecit; excisaque rupe in immensum elata, quam cremando vi magna flammarum acetoque infuso dissolvit, per Druentiam flumen, gurgitibus vagis intutum, regiones occupavit Etruscas. Hactenus super Alpibus. Nunc ad restantia veniamus.", "st": "15.10"}, {"sp": "N", "t": "Temporibus priscis, cum laterent hae partes ut barbarae, tripertitae fuisse creduntur in Celtas eosdemque Gallos divisae, et Aquitanos et Belgas, lingua institutis legibusque discrepantes.", "st": "15.11"}, {"sp": "N", "t": "Et Gallos quidem (qui Celtae sunt) ab Aquitanis Garumna disterminat flumen, a Pyrenaeis oriens collibus, postque oppida multa transcursa, in oceano delitescens.", "st": "15.11"}, {"sp": "N", "t": "Belgis vero eandem gentem Matrona discindit et Sequana, amnes magnitudinis geminae; qui fluentes per Lugdunensem, post circumclausum ambitu insulari Parisiorum castellum, Lutetiam nomine, consociati, meantesque protinus prope astra Constantia funduntur in mare.", "st": "15.11"}, {"sp": "N", "t": "Horum omnium apud veteres Belgae dicebantur esse fortissimi, ea propter quod ab humaniore cultu longe discreti, nec adventiciis effeminati deliciis, diu cum transrhenanis certavere Germanis.", "st": "15.11"}, {"sp": "N", "t": "Aquitani enim, ad quorum litora ut proxima placidaque, merces adventiciae convehuntur, moribus ad mollitiem lapsis, facile in dicionem venere Romanam.", "st": "15.11"}, {"sp": "N", "t": "Regebantur autem Galliae omnes, iam inde uti crebritate bellorum urgenti cessere Iulio dictatori, potestate in partes divisa quattuor, quarum Narbonensis una Viennensem intra se continebat et Lugdunensem; altera Aquitanis praeerat universis; superiorem et inferiorem Germaniam Belgasque duae iurisdictiones eisdem rexere temporibus.", "st": "15.11"}, {"sp": "N", "t": "At nunc numerantur provinciae per omnem ambitum Galliarum: secunda Germania, prima ab occidentali exordiens cardine, Agrippina et Tungris munita, civitatibus amplis et copiosis.", "st": "15.11"}, {"sp": "N", "t": "Dein prima Germania, ubi praeter alia municipia Mogontiacus est et Vangiones, et Nemetae et Argentoratus, barbaricis cladibus nota.", "st": "15.11"}, {"sp": "N", "t": "Post has Belgica prima Mediomatricos praetendit et Treveros, domicilium principum clarum.", "st": "15.11"}, {"sp": "N", "t": "Huic annexa secunda est Belgica, qua Ambiani sunt, urbs inter alias eminens, et Catelauni et Remi.", "st": "15.11"}, {"sp": "N", "t": "Apud Sequanos Bisontios videmus et Rauracos, aliis potiores oppidis multis. Lugdunensem primam Lugdunum ornat et Cabillona et Senones et Biturigae et moenium Augustuduni magnitudo vetusta.", "st": "15.11"}, {"sp": "N", "t": "Secundam enim Lugdunensem Rotomagi et Turini, Mediolanum ostendunt et Tricasini; Alpes Graiae et Poeninae exceptis obscurioribus habent et Aventicum, desertam quidem civitatem sed non ignobilem quondam, ut aedificia semiruta nunc quoque demonstrant. Haec provinciae urbesque sunt splendidae Galliarum.", "st": "15.11"}, {"sp": "N", "t": "In Aquitania quae Pyrenaeos montes et eam partem spectat oceani quae pertinet ad Hispanos, prima provincia est Aquitanica, amplitudine civitatum admodum culta omissis aliis multis, Burdigala et Arverni excellunt, et Santones et Pictavi.", "st": "15.11"}, {"sp": "N", "t": "Novem populos Ausci commendant et Vasatae. In Narbonensi Elusa et Narbona et Tolosa principatum urbium tenent. Viennensis civitatum exsultat decore multarum, e quibus potiores sunt Vienna ipsa et Arelate et Valentia; quibus Massilia iungitur, cuius societate et viribus in discriminibus arduis fultam aliquotiens legimus Romam.", "st": "15.11"}, {"sp": "N", "t": "His prope Salluvii sunt et Nicaea et Antipolis, insulaeque Stoechades.", "st": "15.11"}, {"sp": "N", "t": "Et quoniam ad has partes opere contexto pervenimus, silere super Rhodano, maximi nominis flumine, incongruum est et absurdum. A Poeninis Alpibus effusiore copia fontium Rhodanus fluens, et proclivi impetu ad planiora degrediens, proprio agmine ripas occultat, et paludi sese ingurgitat, nomine Lemanno, eamque intermeans, nusquam aquis miscetur externis, sed altrinsecus summitates undae praeterlabens segnioris, quaeritans exitus, viam sibi impetu veloci molitur.", "st": "15.11"}, {"sp": "N", "t": "Unde sine iactura rerum per Sapaudiam fertur et Sequanos, longeque progressus, Viennensem latere sinistro perstringit, dextro Lugdunensem, et emensus spatia flexuosa, Ararim quem Sauconnam appellant, inter Germaniam primam fluentem et Sequanos, suum in nomen assciscit, qui locus exordium est Galliarum. Exindeque non millenis passibus sed leugis itinera metiuntur.", "st": "15.11"}, {"sp": "N", "t": "Dein Isarae Rhodanus aquis advenis locupletior, vehit grandissimas naves, ventorum difflatu iactari saepius assuetas, finitisque intervallis quae ei natura praescripsit, spumeus Gallico mari concorporatur, per patulum sinum quem vocant Ad gradus, ab Arelate octavo decimo ferme lapide disparatum. Sit satis de situ locorum. Nunc figuras et mores hominum designabo.", "st": "15.11"}, {"sp": "N", "t": "Celsioris staturae et candidi paene Galli sunt omnes et rutili, luminumque torvitate terribiles, avidi iurgiorum, et sublatius insolentes. Nec enim eorum quemquam adhibita uxore rixantem, multo se fortiore et glauca, peregrinorum ferre poterit globus, tum maxime cum illa inflata cervice suffrendens, ponderansque niveas ulnas et vastas, admixtis calcibus emittere coeperit pugnos, ut catapultas tortilibus nervis excussas.", "st": "15.12"}, {"sp": "N", "t": "Metuendae voces complurium et minaces, placatorum iuxta et irascentium, tersi tamen pari diligentia cuncti et mundi, nec in tractibus illis, maximeque apud Aquitanos, vir poterit aliquis videri vel femina, licet perquam pauper, ut alibi frustis squalere pannorum.", "st": "15.12"}, {"sp": "N", "t": "Ad militandum omnis aetas aptissima, et pari pectoris robore senex ad procinctum ducitur et adultus, gelu duratis artubus et labore assiduo, multa contempturus et formidanda. Nec eorum aliquando quisquam (ut in Italia) munus Martium pertimescens, pollicem sibi praecidit, quos localiter murcos appellant.", "st": "15.12"}, {"sp": "N", "t": "Vini avidum genus, affectans ad vini similitudinem multiplices potus, et inter eos humiles quidam, obtunsis ebrietate continua sensibus, quam furoris voluntariam speciem esse Catoniana sententia definivit, raptantur discursibus vagis, ut verum illud videatur quod ait defendens Fonteium Tullius: “Gallos post haec dilutius esse poturos quod illi venenum esse arbitrabantur.”", "st": "15.12"}, {"sp": "N", "t": "Hae regiones, praecipueque confines Italicis, paulatim levi sudore sub imperium venere Romanum, primo temptatae per Fulvium, deinde proeliis parvis quassatae per Sextium, ad ultimum per Fabium Maximum domitae. Cui negotii plenus effectus, asperiore Allobrogum gente devicta, hoc indidit cognomentum.", "st": "15.12"}, {"sp": "N", "t": "Nam omnes Gallias (nisi qua paludibus inviae fuere, ut Sallustio docetur auctore) post decennalis belli mutuas clades subegit Caesar dictator, societatique nostrae foederibus iunxit aeternis. Evectus sum longius; sed remeabo tandem ad coepta.", "st": "15.12"}, {"sp": "N", "t": "Domitiano crudeli morte consumpto, Musonianus eius successor orientem praetoriani regebat potestate praefecti, facundia sermonis utriusque clarus. Unde sublimius quam sperabatur eluxit.", "st": "15.13"}, {"sp": "N", "t": "Constantinus enim cum limatius superstitionum quaereret sectas, Manichaeorum et similium, nec interpres inveniretur idoneus, hunc sibi commendatum ut sufficientem elegit; quem, officio functum perite, Musonianum voluit appellari, ante Strategium dictitatum, et ex eo percursis honorum gradibus multis, ascendit ad praefecturam, prudens alia tolerabilisque provinciis, et mitis et blandus, sed ex qualibet occasione, maximeque ex controversis litibus (quod nefandum est) et in totum lucrandi aviditate sordescens, ut inter alia multa, evidenter apparuit in quaestionibus agitatis super morte Theophili Syriae consularis, proditione Caesaris Galli, impetu plebis promiscuae discerpti, ubi damnatis pauperibus, quos cum haec agerentur, peregre fuisse constabat, auctores diri facinoris exutis patrimoniis absoluti sunt divites.", "st": "15.13"}, {"sp": "N", "t": "Hunc Prosper adaequabat, pro magistro equitum agente etiam tum in Galliis, militem regens, abiecte ignavus et (ut ait comicus) arte despecta furtorum rapiens propalam.", "st": "15.13"}, {"sp": "N", "t": "Quis concordantibus, mutuaque commercia vicissim sibi conciliando locupletatis, Persici duces vicini fluminibus, rege in ultimis terrarum suarum terminis occupato, per praedatorios globos nostra vexabant, nunc Armeniam aliquotiens Mesopotamiam confidentius incursantes, Romanis ductoribus ad colligendas oboedientium exuvias occupatis.", "st": "15.13"}, {"sp": "HDR", "t": "Liber XVI", "st": "16"}, {"sp": "N", "t": "Haec per orbem Romanum fatorum ordine contexto versante, Caesar apud Viennam in collegium fastorum a consule octiens Augusto adscitus, urgente genuino vigore, pugnarum fragores caedesque barbaricas somniabat, colligere provinciae fragmenta iam parans, si adfuisset fortuna flatu tandem secundo.", "st": "16.1"}, {"sp": "N", "t": "Quia igitur res magnae quas per Gallias virtute felicitateque correxit, multis veterum factis fortibus praestant, singula serie progrediente monstrabo, instrumenta omnia mediocris ingenii (si suffecerint) commoturus.", "st": "16.1"}, {"sp": "N", "t": "Quicquid autem narrabitur, quod non falsitas arguta concinnat, sed fides integra rerum absolvit, documentis evidentibus fulta, ad laudativam paene materiam pertinebit.", "st": "16.1"}, {"sp": "N", "t": "Videtur enim lex quaedam vitae melioris hunc invenem a nobilibus cunis ad usque spiritum comitata supremum. Namque incrementis velocibus ita domi forisque colluxit, ut prudentia Vespasiani filius Titus alter aestimaretur, bellorum gloriosis cursibus Traiani simillimus, clemens ut Antoninus, rectae perfectaeque rationis indigine congruens Marco, ad cuius aemulationem actus suos effingebat et mores.", "st": "16.1"}, {"sp": "N", "t": "Et quoniam (ut Tulliana docet auctoritas) “omnium magnarum artium sicut arborum altitudo nos delectat, radices stirpesque non item,” sic praeclarae huius indolis rudimenta, tune multis obnubilantibus tegebantur, quae anteferri gestis eius postea multis et miris, hac ratione deberent, quod adulescens primaevus, ut Erechtheus in secessu Minervae nutritus, ex Academiae quietis umbraculis, non e militari tabernaculo, in pulverem Martium tractus, strata Germania, pacatisque rigentis Rheni meatibus, cruenta spirantium regum hic sanguinem fudit, alibi manus catenis afflixit.", "st": "16.1"}, {"sp": "N", "t": "Agens itaque negotiosam hiemem apud oppidum ante dictum, inter rumores, qui volitabant assidui, comperit Augustuduni civitatis antiquae muros spatiosi quidem ambitus sed carie vetustatis invalidos, barbarorum impetu repentino insessos, torpente praesentium militum manu, veteranos concursatione pervigili defendisse, ut solet abrupta saepe discrimina salutis ultima desperatio propulsare.", "st": "16.2"}, {"sp": "N", "t": "Nihil itaque remittentibus curis, ancillari adulatione posthabita, qua eum proximi ad amoenitatem flectebant et luxum, satis omnibus comparatis, octavum kalendas Iulias Augustudunum pervenit, velut dux diuturnus viribus eminens et consiliis, per diversa palantes barbaros ubi dedisset fors copiam aggressurus.", "st": "16.2"}, {"sp": "N", "t": "Habita itaque deliberatione assistentibus locorum peritis, quodnam iter eligeretur ut tutum, multa ultro citroque dicebantur aliis per Arbor … quibusdam per Sedelaucum et Coram iri debere firmantibus.", "st": "16.2"}, {"sp": "N", "t": "Sed cum subsererent quidam, Silvanum paulo ante magistrum peditum per compendiosas vias, verum suspectas, quia ramorum tenebris multis umbrantur, cum octo auxiliarium milibus aegre transisse, fidentius Caesar audaciam viri fortis imitari magnopere nitebatur.", "st": "16.2"}, {"sp": "N", "t": "Et nequa interveniat mora, adhibitis cataphractariis solis et ballistariis, parum ad tuendum rectorem idoneis, percurso eodem itinere, Autosudorum pervenit.", "st": "16.2"}, {"sp": "N", "t": "Ubi brevi (sicut solebat) otio cum milite recreatus, ad Tricasinos tendebat, et barbaros in se catervatim ruentes partim, cum timeret ut ampliores, confertis lateribus observabat, alios occupatis habilibus locis, decursu facili proterens, non nullos pavore traditos cepit, residuos in curam celeritatis omne quod poterant conferentes, quia sequi non valebat, gravitate praepeditus armorum, innocuos abire perpessus est.", "st": "16.2"}, {"sp": "N", "t": "Proinde certiore iam spe ad resistendum ingruentibus confirmatus, per multa discrimina venit Tricasas, adeo insperatus, ut eo portas paene pulsante, diffusae multitudinis barbarae metu, aditus urbis non sine anxia panderetur ambage.", "st": "16.2"}, {"sp": "N", "t": "Et paulisper moratus, dum fatigato consulit militi, civitatem Remos, nihil prolatandum existimans, petit, ubi in unum congregatum exercitum vehentem unius mensis cibaria iusserat operiri praesentiam suam; cui praesidebat Ursicini successor Marcellus, et ipse Ursicinus, ad usque expeditionis finem agere praeceptus eisdem in locis.", "st": "16.2"}, {"sp": "N", "t": "Post variatas itaque sententias plures, cum placuisset per Decem pagos Alamannam aggredi plebem densatis agminibus, tendebat illuc solito alacrior miles.", "st": "16.2"}, {"sp": "N", "t": "Et quia dies umectus et decolor, vel contiguum eripiebat aspectum, iuvante locorum gnaritate hostes tramite obliquo discurso, post Caesaris terga legiones duas arma cogentes adorti, paene delessent, ni subito concitus clamor sociorum auxilia coegisset.", "st": "16.2"}, {"sp": "N", "t": "Hinc et deinde nec itinera nec flumina transire posse sine insidiis putans, erat providus et cunctator, quod praecipuum bonum in magnis ductoribus, opem ferre solet exercitibus et salutem.", "st": "16.2"}, {"sp": "N", "t": "Audiens itaque Argentoratum, Brotomagum, Tabernas, Salisonem, Nemetas et Vangionas et Mogontiacum civitates barbaros possidentes, territoria earum habitare (nam ipsa oppida ut circumdata retiis busta declinant) primam omnium Brotomagum occupavit, eique iam adventanti Germanorum manus pugnam intentans occurrit.", "st": "16.2"}, {"sp": "N", "t": "Cumque in bicornem figuram acie divisa, collato pede res agi coepisset, exitioque hostes urgerentur ancipiti, captis non nullis, aliis in ipso proelii fervore truncatis, residui discessere, celeritatis praesidio tecti.", "st": "16.2"}, {"sp": "N", "t": "Nullo itaque post haec repugnante, ad recuperandam ire placuit Agrippinam, ante Caesaris in Gallias adventum excisam, per quos tractus nec civitas ulla visitur nec castellum, nisi quod apud Confluentes, locum ita cognominatum, ubi amnis Mosella confunditur Rheno, Rigomagum oppidum est et una prope ipsam Coloniam turris.", "st": "16.3"}, {"sp": "N", "t": "Igitur Agrippinam ingressus, non ante motus est exinde, quam Francorum regibus furore mitescente perterritis, pacem firmaret rei publicae interim profuturam, et urbem reciperet munitissimam.", "st": "16.3"}, {"sp": "N", "t": "Quibus vincendi primitiis laetus, per Treveros hiematurus, apud Senonas oppidum tune opportunum abscessit. Ubi bellorum inundantium molem umeris suis (quod dicitur) vehens, scindebatur in multiplices curas, ut milites qui a solitis descivere praesidiis reducerentur ad loca suspecta, et conspiratas gentes in noxam Romani nominis disiectaret, ac provideret ne alimenta deessent exercitui per varia discursuro.", "st": "16.3"}, {"sp": "N", "t": "Haec sollicite perpensantem, hostilis aggreditur multitudo, oppidi capiundi spe in maius accensa, ideo confidenter quod ei nec scutarios adesse prodentibus perfugis didicerant nec gentiles, per municipia distributos, ut commodius vescerentur quam antea.", "st": "16.4"}, {"sp": "N", "t": "Clausa ergo urbe murorumque intuta parte firmata, ipse cum armatis die noctuque inter propugnacula visebatur et pinnas, ira exundante substridens, cum erumpere saepe conatus, paucitate praesentis manus impediretur. Post tricesimum denique diem, abiere barbari tristes, inaniter stulteque cogitasse civitatis obsidium mussitantes.", "st": "16.4"}, {"sp": "N", "t": "Et (quod indignitati rerum est assignandum) periclitanti Caesari distulit suppetias ferre Marcellus, magister equitum agens in stationibus proximis, cum etiam si civitas absque principe vexaretur, opposita multitudine malis obsidionalibus expediri deberet.", "st": "16.4"}, {"sp": "N", "t": "Hoc metu solutus, efficacissimus Caesar providebat constanti sollicitudine, ut militum diuturno labori quies succederet aliqua licet brevis, ad recreandas tamen sufficiens vires, quamquam ultima squalentes inopia terrae, saepe vastitatae exigua quaedam victui congrua suggerebant.", "st": "16.4"}, {"sp": "N", "t": "Verum hoc quoque diligentia curate pervigili, affusa laetiore spe prosperorum, sublate animo ad exsequanda plurima consurgebat.", "st": "16.4"}, {"sp": "N", "t": "Primum igitur factuque difficile, temperantiam ipse sibi indixit atque retinuit, tamquam adstrictus sumptuariis legibus viveret, quas ex rhetris Lycurgi (id est axibus) Romam translatas, diuque observatas et senescentes, paulatim reparavit Sulla dictator, reputans ex praedictis Democriti, quod ambitiosam mensam fortuna, parcam virtus apponit.", "st": "16.5"}, {"sp": "N", "t": "Id enim etiam Tusculanus Cato prudenter definiens, cui Censorii cognomentum, castior vitae indidit cultus: “Magna” inquit “cura cibi, magna virtutis incuria.”", "st": "16.5"}, {"sp": "N", "t": "Denique cum legeret libellum assidue, quem Constantius, ut privignum ad studia mittens, manu sua conscripserat, praelicenter disponens quid in convivio Caesaris impendi deberet, phasianum et vulvam et sumen exigi vetuit et inferri, munificis militis vili et fortuito cibo contentus.", "st": "16.5"}, {"sp": "N", "t": "Hinc contingebat ut noctes ad officia divideret tripertita, quietis et publicae rei et musarum, quod factitasse Alexandrum legimus Magnum; sed multo hic fortius. Ille namque aenea concha supposita, brachio extra cubile protento pilam tenebat argenteam, ut cum nervorum vigorem sopor laxasset infusus, gestaminis lapsi tinnitus abrumperet somnum.", "st": "16.5"}, {"sp": "N", "t": "Iulianus vero absque instrumento, quotiens voluit evigilavit, et nocte dimidiata semper exsurgens, non e plumis vel stragulis sericis ambiguo fulgore nitentibus, sed ex tapete et sisyra, quam vulgaris simplicitas susurnam appellat, occulte Mercurio supplicabat, quem mundi velociorem sensum esse motum mentium suscitantem, theologicae prodidere doctrinae; atque in tanto rerum defectu, explorate rei publicae munera cuncta curabat.", "st": "16.5"}, {"sp": "N", "t": "Post quae ut ardua et seria terminata, ad procudendum ingenium vertebatur, et incredibile quo quantoque ardore, principalium rerum notitiam celsam indagans, et quasi pabula quaedam animo ad sublimiora scandenti conquirens, per omnia philosophiae membra prudenter disputando currebat.", "st": "16.5"}, {"sp": "N", "t": "Sed tamen cum haec effecte pleneque colligeret, nec humiliora despexit, poeticam mediocriter et rhetoricam tractans (ut ostendit orationum epistularumque eius cum gravitate comitas incorrupta) et nostrarum externarumque rerum historiam multiformem. Super his aderat Latine quoque disserendi sufficiens sermo.", "st": "16.5"}, {"sp": "N", "t": "Si itaque verum est, quod scriptores varii memorant, Cyrum regem et Simonidem lyricum, et Hippian Eleum sophistarum acerrimum, ideo valuisse memoria, quod epotis quibusdam remediis id impetrarunt, credendum est hunc etiam tum adultum totum memoriae dolium (si usquam repperiri potuit) exhausisse. Et haec quidem pudicitiae virtutumque sunt signa nocturna.", "st": "16.5"}, {"sp": "N", "t": "Diebus vero quae ornate dixerit et facete, quaeve in apparatu vel in ipsis egerit congressibus proeliorum, aut in re civili magnanimitate correxit et libertate, suo quaeque loco singulatim demonstrabuntur.", "st": "16.5"}, {"sp": "N", "t": "Cum exercere proludia disciplinae castrensis philosophus cogeretur ut princeps, artemque modulatius incedendi per pyrricham concinentibus disceret fistulis, vetus illud proverbium “clitellae bovi sunt impositae; plane non est nostrum onus” Platonem crebro nominans exclamabat.", "st": "16.5"}, {"sp": "N", "t": "Cum inducti essent iussu eius quadam sollemnitate agentes in rebus in consistorium, ut aurum acciperent inter alios, quidam ex eorum consortio, non (ut moris est) pansa chlamyde, sed utraque manu cavata suscepit. Et imperator “rapere” inquit “non accipere sciunt agentes in rebus.”", "st": "16.5"}, {"sp": "N", "t": "Aditus a parentibus virginis raptae, eum qui violarat convictum relegari decrevit. Hisque indigna pati querentibus, quod non sit morte multatus, responderat hactenus: “Incusent iura clementiam, sed imperatorem mitissimi animi legibus praestare ceteris decet.”", "st": "16.5"}, {"sp": "N", "t": "Egressurum eum ad expeditionem plures interpellabant ut laesi, quos audiendos provinciarum rectoribus commendabat; et reversus, quid egerint singuli quaerens, delictorum vindictas genuina lenitudine mitigabat.", "st": "16.5"}, {"sp": "N", "t": "Ad ultimum exceptis victoriis, per quas cadentes saepe incolumi contumacia barbaros fudit, quod profuerit anhelantibus extrema penuria Gallis, hinc maxime claret, quod primitus partes eas ingressus, pro capitulis singulis tributi nomine vicenos quinos aureos repperit flagitari, discedens vero septenos tantum munera universa complentes: ob quae tamquam solem sibi serenum post squalentes tenebras affulsisse, cum alacritate et tripudiis laetabantur.", "st": "16.5"}, {"sp": "N", "t": "Denique id eum ad usque imperii finem et vitae scimus utiliter observasse, ne per indulgentias (quas appellant) tributariae rei concederet reliqua. Norat enim hoc facto se aliquid locupletibus additurum, cum constet ubique, pauperes inter ipsa indictorum exordia solvere universa sine laxamento compelli.", "st": "16.5"}, {"sp": "N", "t": "Inter has tamen regendi moderandique vias, bonis principibus aemulandas, barbarica rabies exarserat rursus in maius.", "st": "16.5"}, {"sp": "N", "t": "Utque bestiae custodum neglegentia raptu vivere solitae, ne his quidem remotis, appositisque fortioribus abscesserunt, sed tumescentes inedia, sine respectu salutis, armenta vel greges incursant, ita etiam illi, cunctis quae diripuere consumptis, fame urgente, agebant aliquotiens praedas, interdum antequam contingerent aliquid, oppetebant.", "st": "16.5"}, {"sp": "N", "t": "Haec per eum annum spe dubia eventu tamen secundo per Gallias agebantur. In comitatu vero Augusti, circumlatrabat Arbetionem invidia, velut summa mox adepturum, decora cultus imperatorii praestruxisse, instabatque ei strepens immania, comes Verissimus nomine, arguens coram, quod a gregario ad magnum militiae culmen evectus, hoc quoque non contentus (ut parvo) locum appeteret principalem.", "st": "16.6"}, {"sp": "N", "t": "Sed specialiter eum insectabatur Dorus quidam ex medico scutariorum, quem nitentium rerum centurionem sub Magnentio Romae provectum, retulimus accusasse Adelphium, urbi praefectum, ut altiora coeptantem.", "st": "16.6"}, {"sp": "N", "t": "Cumque res in inquisitionem veniret, necessariisque negotio tentis, obiectorum probatio speraretur, tamquam per saturam subito cubiculariis suffragantibus, ut loquebatur pertinax rumor, et vinculis sunt exutae personae quae stringebantur ut consciae, et Dorus evanuit, et Verissimus ilico tacuit, velut aulaeo deposito scenae.", "st": "16.6"}, {"sp": "N", "t": "Eisdem diebus, allapso rumore Constantius doctus, obsesso apud Senonas Caesari auxilium non tulisse Marcellum, eum sacramento solutum abire iussit in larem. Qui tamquam iniuria gravi perculsus, quaedam in Iulianum moliebatur, auribus Augusti confisus, in omne patentibus crimen.", "st": "16.7"}, {"sp": "N", "t": "Ideoque cum discederet, Eutherius praepositus cubiculi mittitur statim post eum, siquid finxerit convicturus. Verum ille hoc nesciens, mox venit Mediolanum, strepens et tumultuans, (ut erat vanidicus et amenti propior); admissus in consistorium, lulianum ut procacem insimulat, iamque ad evagandum altius validiores sibi pinnas aptare; ita enim cum motu quodam corporis loquebatur ingenti.", "st": "16.7"}, {"sp": "N", "t": "Haec eo fingente licentius, Eutherius (ut postulavit) inductus, iussusque loqui quod vellet, verecunde et modice docet, velari veritatem mendaciis. Magistro enim armorum, ut credebatur, cessante consulto, industria vigili Caesarem obsessum apud Senonas diu barbaros reppulisse, apparitoremque fidum auctori suo quoad vixerit fore, obligata cervice sua spondebat.", "st": "16.7"}, {"sp": "N", "t": "Res monuit super hoc eodem Eutherio pauca subserere, forsitan non credenda, ea re quod si Numa Pompilius vel Socrates bona quaedam dicerent de spadone, dictisque religionum adderent fidem, a veritate descivisse arguebantur. Sed inter vepres rosae nascuntur, et inter feras non nullae mitescunt, itaque carptim eius praecipua, quae sunt comperta, monstrabo.", "st": "16.7"}, {"sp": "N", "t": "Natus in Armenia sanguine libero, captusque a finitimis hostibus, etiam tum parvulus abstractis geminis Romanis mercatoribus venundatus, ad palatium Constantini deducitur; ubi paulatim adulescens rationem recte vivendi, sollertiamque ostendebat, litteris quantum tali fortunae satis esse poterat eruditus, cogitandi inveniendique dubia et scrupulosa, acumine nimio praestans, immensum quantum memoria vigens, benefaciendi avidus plenusque iusti consilii, quem si Constans imperator olim ex adulto iamque maturum audiret, honesta suadentem et recta, nulla vel venia certe digna peccasset.", "st": "16.7"}, {"sp": "N", "t": "Is praepositus cubiculi etiam Iulianum aliquotiens corrigebat, Asiaticis coalitum moribus, ideoque levem. Denique digressus ad otium, asscitusque postea in palatium, semper sobrius et in primis consistens, ita fidem continentiamque virtutes coluit amplas, ut nec prodidisse aliquando arcanum, nisi tuendae causa alienae salutis, nec exarsisse cupidine plus habendi arcesseretur, ut ceteri.", "st": "16.7"}, {"sp": "N", "t": "Unde factum est ut subinde Romam secedens, ibique fixo domicilio consenescens, comitem circumferens conscientiam bonam, colatur a cunctis ordinibus et ametur, cum soleant id genus homines post partas ex iniquitate divitias latebras captare secretas, ut lucifugae vitantes multitudinis laesae conspectus.", "st": "16.7"}, {"sp": "N", "t": "Cui spadonum veterum hunc comparare debeam, antiquitates replicando complures invenire non potui. Fuerunt enim apud veteres (licet oppido pauci) fideles et frugi, sed ob quaedam vitia maculosi. Inter praecipua enim, quae eorum quisque studio possederat vel ingenio, aut rapax aut feritate contemptior fuit, aut propensior ad laedendum, vel regentibus nimium blandus, aut potentiae fastu superbior; ex omni latere autem ita paratum, neque legisse me neque audisse confiteor, aetatis nostrae testimonio locupleti confisus.", "st": "16.7"}, {"sp": "N", "t": "Verum si forte scrupulosus quidam lector antiquitatum, Menophilum Mithridatis Pontici regis eunuchum, nobis opponat, hoc monitu recordetur, nihil super eo relatum praeter id solum, quod in supremo discrimine gloriose monstravit.", "st": "16.7"}, {"sp": "N", "t": "Ingenti proelio superatus a Romanis et Pompeio rex praedictus, fugiensque ad regna Colchorum, adultam filiam nomine Drypetinam, vexatam asperitate morborum, in castello Sinhorio huic Menophilo commissam reliquit. Qui virginem omni remediorum solacio plene curatam, patri tutissime servans, cum a Mallio Prisco, imperatoris legato, munimentum quo claudebatur obsideri coepisset, defensoresque eius deditionem meditari sentiret, veritus ne parentis opprobrio puella nobilis captiva superesset et violata, interfecta illa mox gladium in viscera sua compegit. Nunc redeam unde diverti.", "st": "16.7"}, {"sp": "N", "t": "Superato ut dixi Marcello, reversoque Serdicam, unde oriebatur, in castris Augusti per simulationem tuendae maiestatis imperatoriae, multa et nefanda perpetrabantur.", "st": "16.8"}, {"sp": "N", "t": "Nam si super occentu soricis vel occursu mustelae, vel similis signi gratia consuluisset quisquam peritum, aut anile incantamentum ad leniendum adhibuisset dolorem, quod medicinae quoque admittit auctoritas, reus unde non poterat opinari delatus, raptusque in iudicium, poenaliter interibat.", "st": "16.8"}, {"sp": "N", "t": "Per id tempus fere servum quendam, nomine Danum, terrore tenus uxor rerum levium incusarat: hanc incertum unde notam Rufinus subsedit, —quo indicante quaedam cognita per Gaudentium, agentem in rebus, consularem Pannoniae tunc Africanum, cum convivis rettulimus interfectum—apparitionis praefecturae praetorianae tum etiam princeps ob devotionem.", "st": "16.8"}, {"sp": "N", "t": "Is (ut loquebatur iactantius) versabilem feminam, post nefandum concubitum, in periculosam fraudem illexit; suasit consarcinatis mendaciis laesae maiestatis arcessere maritum insontem, et fingere quod velamen purpureum, a Diocletiani sepulcro furatus, quibusdam consciis occultabat.", "st": "16.8"}, {"sp": "N", "t": "Hisque ad multorum exitium ita formatis, ipse spe potiorum ad imperatoris pervolat castra, excitaturus calumnias consuetas. Reque comperta, iubetur Mavortius, tunc praefectus praetorio, vir sublimis constantiae, crimen acri inquisitione spectare, iuncto ad audiendi societatem Ursulo (largitionum comite) severitatis itidem non improbandae.", "st": "16.8"}, {"sp": "N", "t": "Exaggerato itaque negotio ad arbitrium temporum, cum nihil post tormenta multorum inveniretur, iudicesque haererent ambigui, tandem veritas respiravit oppressa, et in abrupto necessitatis mulier Rufinum totius machinae confitetur auctorem, nec adulterii foeditate suppressa; statimque legibus contemplatis, illi amore recti concordes et iusti, ambos sententia damnavere letali.", "st": "16.8"}, {"sp": "N", "t": "Quo cognito Constantius fremens, et tamquam vindicem salutis suae lugens exstinctum, missis equitibus citis, Ursulum redire ad comitatum minaciter iussit. Qui cum eo venisset adireque principem vellet, ab aulicis arcebatur, ne defendendae posset assistere veritati; sed ille spretis qui prohibebant, perrupit intrepidus, ingressusque consistorium, ore et pectore libero docuit gesta; hacque fiducia linguis adulatorum occlusis, et praefectum et se discrimine gravi subtraxit.", "st": "16.8"}, {"sp": "N", "t": "Tune illud apud Aquitanos evenit, quod latior fama vulgarat. Veterator quidam ad lautum convivium rogatus et mundum, qualia sunt in his regionibus plurima, cum vidisset linteorum toralium purpureos clavos ita latissimos, ut sibi vicissim arte ministrantium cohaererent, mensamque operimentis paribus tectam, anteriorem chlamydis partem utraque manu vehens intrinsecus, structuram omnem ut amictus adornaverat principalis; quae res patrimonium dives evertit.", "st": "16.8"}, {"sp": "N", "t": "Malignitate simili quidam agens in rebus in Hispania ad cenam itidem invitatus, cum inferentes vespertina lumina pueros exclamasse audisset ex usu “vincamus,” verbum sollemne interpretatum atrociter delevit nobilem domum.", "st": "16.8"}, {"sp": "N", "t": "Haec taliaque ideo magis magisque crescebant, quod Constantius impendio timidus et de vita sollicitus, semper se ferro peti sperabat, ut Dionysius tyrannus ille Siciliae, qui ob hoc idem vitium et tonstrices docuit filias, necui alieno ora committeret leviganda, aedemque brevem, ubi cubitare sueverat, alta circumdedit fossa eamque ponte solubili superstravit, cuius disiectos asseres et axiculos secum in somnum abiens transferebat, eosdemque compaginabat, lucis initio processurus.", "st": "16.8"}, {"sp": "N", "t": "Inflabant itidem has malorum civilium bucinas potentes in regia, ea re ut damnatorum petita bona suis accorporarent, essetque materia per vicinitates eorum late grassandi.", "st": "16.8"}, {"sp": "N", "t": "Namque ut documenta liquida prodiderunt, proximorum fauces aperuit primus omnium Constantinus, sed eos medullis provinciarum saginavit Constantius.", "st": "16.8"}, {"sp": "N", "t": "Sub hoc enim ordinum singulorum auctores, infinita cupidine divitiarum arserunt, sine iustitiae distinctione vel recti, inter ordinarios iudices Rufinus primus praefectus praetorio, et inter militares equitum magister Arbetio, praepositusque cubiculi Eusebius, … anus quaestor, et in urbe Anicii, quorum ad avorum aemulationem posteritas tendens, satiari numquam potuit cum possessione multo maiore.", "st": "16.8"}, {"sp": "N", "t": "At Persae in oriente per furta et latrocinia potius quam (ut solebant antea) per concursatorias pugnas, hominum praedas agitabant et pecorum, quas non numquam lucrabantur ut repentini, aliquotiens superati multitudine militum amittebant, interdum nihil conspicere prorsus quod poterat rapi permittebantur.", "st": "16.9"}, {"sp": "N", "t": "Musonianus tamen praefectus praetorio, multis (ut ante diximus) bonis artibus eruditus, sed venalis et flecti a veritate pecunia facilis, per emissarios quosdam, fallendi perstringendique gnaros, Persarum scitabatur consilia, assumpto in deliberationes huius modi Cassiano Mesopotamiae duce, stipendiis et discriminibus indurato diversis.", "st": "16.9"}, {"sp": "N", "t": "Qui cum fide concinente speculatorum aperte cognossent Saporem in extremis regni limitibus, suorum sanguine fuso multiplici, aegre propulsare gentes infestas, Tamsaporem ducem parti nostrae contiguum, occultis per ignotos milites temptavere colloquiis, ut si copiam fors dedisset, suaderet regi per litteras pacem tandem aliquando cum principe Romano firmare, ut hoc facto ab occidentali latere omni securus, perduelles involaret assiduos.", "st": "16.9"}, {"sp": "N", "t": "Paruit Tamsapor, hisque fretus refert ad regem, quod bellis acerrimis Constantius implicatus, pacem postulat precativam. Dumque ad Chionitas et Eusenos haec scripta mittuntur, in quorum confiniis agebat hiemem Sapor, tempus interstitit longum.", "st": "16.9"}, {"sp": "N", "t": "Haec dum per eoas partes et Gallias pro captu temporum disponuntur, Constantius quasi cluso Iani templo stratisque hostibus cunctis, Romam visere gestiebat, post Magnenti exitium absque nomine ex sanguine Romano triumphaturus.", "st": "16.10"}, {"sp": "N", "t": "Nec enim gentem ullam bella cientem per se superavit, aut victam fortitudine suorum comperit ducum, vel addidit quaedam imperio, aut usquam in necessitatibus summis primus vel inter primos est visus, sed ut pompam nimis extentam, rigentiaque auro vexilla, et pulcritudinem stipatorum ostenderet agenti tranquillius populo, haec vel simile quicquam videre nec speranti umquam nec optanti.", "st": "16.10"}, {"sp": "N", "t": "Ignorans fortasse, quosdam veterum principum in pace quidem lictoribus fuisse contentos, ubi vero proeliorum ardor nihil perpeti poterat segne, alium anhelante rabido flatu ventorum lenunculo se commisisse piscantis, alium ad Deciorum exempla vovisse pro re publica spiritum, alium hostilia castra per semet ipsum cum militibus infimis explorasse, diversos denique actibus inclaruisse magnificis, ut glorias suas posteritatis celebri memoriae commendarent.", "st": "16.10"}, {"sp": "N", "t": "Ut igitur multa quaeque consumpta sunt in apparatu regio, pro meritis cuilibet munera reddita, secunda Orfiti praefectura, transcurso Ocriculo, elatus honoribus magnis, stipatusque agminibus formidandis, tamquam acie ducebatur instructa, omnium oculis in eum contuitu pertinaci intentis.", "st": "16.10"}, {"sp": "N", "t": "Cumque urbi propinquaret, senatus officia, reverendasque patriciae stirpis effigies, ore sereno contemplans, non ut Cineas ille Pyrri legatus, in unum coactam multitudinem regum, sed asylum mundi totius adesse existimabat.", "st": "16.10"}, {"sp": "N", "t": "Unde cum se vertisset ad plebem, stupebat qua celebritate omne quod ubique est hominum genus confluxerit Romam. Et tamquam Euphraten armorum specie territurus aut Rhenum, altrinsecus praeeuntibus signis, insidebat aureo solus ipse carpento, fulgenti claritudine lapidum variorum, quo micante lux quaedam misceri videbatur alterna.", "st": "16.10"}, {"sp": "N", "t": "Eumque post antegressos multiplices alios, purpureis subtegminibus texti, circumdedere dracones, hastarum aureis gemmatisque summitatibus illigati, hiatu vasto perflabiles, et ideo velut ira perciti sibilantes, caudarumque volumina relinquentes in ventum.", "st": "16.10"}, {"sp": "N", "t": "Et incedebat hinc inde ordo geminus armatorum, clipeatus atque cristatus, corusco lumine radians, nitidis loricis indutus, sparsique cataphracti equites (quos clibanarios dictitant) personati thoracum muniti tegminibus, et limbis ferreis cincti, ut Praxitelis manu polita crederes simulacra, non viros; quos laminarum circuli tenues, apti corporis flexibus ambiebant, per omnia membra diducti, ut quocumque artus necessitas commovisset, vestitus congrueret, iunctura cohaerenter aptata.", "st": "16.10"}, {"sp": "N", "t": "Augustus itaque faustis vocibus appellatus, non montium litorumque intonante fragore cohorruit, talem se tamque immobilem, qualis in provinciis suis visebatur, ostendens.", "st": "16.10"}, {"sp": "N", "t": "Nam et corpus perhumile curvabat portas ingrediens celsas, et velut collo munito, rectam aciem luminum tendens, nec dextra vultum nec laeva flectebat et (tamquam figmentum hominis) nec cum rota concuteret nutans, nec spuens, aut os aut nasum tergens vel fricans, manumve agitans visus est umquam.", "st": "16.10"}, {"sp": "N", "t": "Quae licet affectabat, erant tamen haec et alia quaedam in citeriore vita, patientiae non mediocris indicia, ut existimari dabatur, uni illi concessae.", "st": "16.10"}, {"sp": "N", "t": "Quod autem per omne tempus imperil, nec in consessum vehiculi quemquam suscepit, nec in trabea socium privatum asscivit, ut fecere principes consecrati, et similia multa elatus in arduum supercilium, tamquam leges aequissimas observavit, praetereo, memor ea me rettulisse cum incidissent.", "st": "16.10"}, {"sp": "N", "t": "Proinde Romam ingressus imperil virtutumque omnium larem, cum venisset ad rostra, perspectissimum priscae potentiae forum, obstipuit, perque omne latus quo se oculi contulissent, miraculorum densitate praestrictus, allocutus nobilitatem in curia, populumque e tribunali, in palatium receptus favore multiplici, laetitia fruebatur optata, et saepe, cum equestres ederet ludos, dicacitate plebis oblectabatur, nec superbae nec a libertate coalita desciscentis, reverenter modum ipse quoque debitum servans.", "st": "16.10"}, {"sp": "N", "t": "Non enim (ut per civitates alias) ad arbitrium suum certamina finiri patiebatur, sed (ut mos est) variis casibus permittebat. Deinde intra septem montium culmina, per acclivitates planitiemque posita urbis membra collustrans et suburbana, quicquid viderat primum, id eminere inter alia cuncta sperabat: Iovis Tarpei delubra, quantum terrenis divina praecellunt; lavacra in modum provinciarum exstructa; amphitheatri molem solidatam lapidis Tiburtini compage, ad cuius summitatem aegre visio humana conscendit; Pantheum velut regionem teretem speciosa celsitudine fornicatam; elatosque vertices qui scansili suggestu consurgunt, priorum principum imitamenta portantes, et Urbis templum forumque Pacis, et Pompei theatrum et Odeum et Stadium, aliaque inter haec decora urbis aeternae.", "st": "16.10"}, {"sp": "N", "t": "Verum cum ad Traiani forum venisset, singularem sub omni caelo structuram, ut opinamur, etiam numinum assensione mirabilem, haerebat attonitus, per giganteos contextus circumferens mentem, nec relatu effabiles, nec rursus mortalibus appetendos. Omni itaque spe huius modi quicquam conandi depulsa, Traiani equum solum, locatum in atrii medio, qui ipsum principem vehit, imitari se velle dicebat et posse.", "st": "16.10"}, {"sp": "N", "t": "Cui prope adstans regalis Ormisda, cuius e Perside discessum supra monstravimus, respondit astu gentili: “Ante” inquit “imperator, stabulum tale condi iubeto, si vales; equus quem fabricare disponis, ita late succedat, ut iste quem videmus.” Is ipse interrogatus quid de Roma sentiret, id tantum sibi placuisse aiebat, quod didicisset ibi quoque homines mori.", "st": "16.10"}, {"sp": "N", "t": "Multis igitur cum stupore visis horrendo, imperator de fama querebatur, ut invalida vel maligna, quod augens omnia semper in maius, erga haec explicanda quae Romae sunt obsolescit, deliberansque diu quid ibi ageret, urbis addere statuit ornamentis, ut in maximo circo erigeret obeliscum, cuius originem formamque loco competenti monstrabo.", "st": "16.10"}, {"sp": "N", "t": "Inter haec Helenae sorori Constanti, Iuliani coniugi Caesaris, Romam affectionis specie ductae, regina tunc insidiabatur Eusebia, ipsa quoad vixerat sterilis, quaesitumque venenum bibere per fraudem illexit, ut quotienscumque concepisset, immaturum abiceret partum.", "st": "16.10"}, {"sp": "N", "t": "Nam et pridem in Galliis, cum marem genuisset infantem, hoc perdidit dolo, quod obstetrix corrupta mercede, mox natum, praesecto plus quam convenerat umbilico, necavit; tanta tamque diligens opera navabatur, ne fortissimi viri soboles appareret.", "st": "16.10"}, {"sp": "N", "t": "Cupiens itaque augustissima omnium sede morari diutius imperator, ut otio puriore frueretur et voluptate, assiduis nuntiis terrebatur et certis, indicantibus Suebos Raetias incursare, Quadosque Valeriam, et Sarmatas, latrocinandi peritissimum genus, superiorem Moesiam et secundam populari Pannoniam; quibus percitus tricensimo postquam ingressus est die, quartum kal. lunias ab urbe profectus, per Tridentum iter in Illyricum festinavit.", "st": "16.10"}, {"sp": "N", "t": "Unde misso in locum Marcelli Severo, bellorum usu et maturitate firmato, Ursicinum ad se venire praecepit. Et ille litteris gratanter acceptis, Sirmium venit, comitantibus sociis, libratisque diu super pace consiliis, quam fundari posse cum Persis Musonianus rettulerat, in orientem cum magisterii remittitur potestate, provectis e consortio nostro ad regendos milites natu maioribus, adulescentes eum sequi iubemur, quicquid pro re publica mandaverit impleturi.", "st": "16.10"}, {"sp": "N", "t": "At Caesar exacta apud Senonas hieme turbulenta, Augusto novies seque iterum consule, Germanicis undique circumfrementibus minis, secundis ominibus motus, Remos properavit alacrior, magisque laetus quod exercitum regebat Severus, nec discors nec arrogans, sed longa militiae frugalitate compertus, et eum recta praeeuntem secutus, ut ductorem morigerus miles.", "st": "16.11"}, {"sp": "N", "t": "Parte alia Barbatio, post Silvani interitum promotus ad peditum magisterium, ex Italia iussu principis cum XXV milibus armatorum Rauracos venit.", "st": "16.11"}, {"sp": "N", "t": "Cogitatum est enim, solliciteque praestructum, ut saevientes ultra solitum Alamanni vagantesque fusius, multitudine geminata nostrorum, forcipis specie, trusi in angustias caederentur.", "st": "16.11"}, {"sp": "N", "t": "Dum haec tamen rite disposita celerantur, Laeti barbari ad tempestiva furta sollertes, inter utriusque exercitus castra occulte transgressi, invasere Lugdunum incautam, eamque populatam vi subita concremassent, ni clausis aditibus repercussi, quicquid extra oppidum potuit inveniri vastassent.", "st": "16.11"}, {"sp": "N", "t": "Qua clade cognita, agili studio Caesar missis cuneis tribus equitum expeditorum et fortium, tria observavit itinera, sciens per ea erupturos procul dubio grassatores; nec conatus ei insidianti irritus fuit.", "st": "16.11"}, {"sp": "N", "t": "Cunctis enim qui per eos tramites exiere truncatis, receptaque praeda omni intacta, hi soli innoxii absoluti sunt, qui per vallum Barbationis transiere securi, ideo labi permissi, quod Bainobaudes tribunus, et Valentinianus postea imperator, cum equestribus turmis quas regebant, ad exsequendum id ordinati, a Cella tribuno scutariorum, qui Barbationi sociatus venerat ad procinctum, iter observare sunt vetiti, unde redituros didicere Germanos.", "st": "16.11"}, {"sp": "N", "t": "Quo non contentus, magister peditum ignavus et gloriarum Iuliani pervicax obtrectator, sciens se id contra utilitatem Romanae rei iussisse—hoc enim cum argueretur, Cella confessus est—relatione fefellit Constantium, finxitque hos eosdem tribunos, ad sollicitandos milites quos duxerat per speciem venisse negotii publici; qua causa abrogata potestate ad lares rediere privati.", "st": "16.11"}, {"sp": "N", "t": "Eisdem diebus, exercituum adventu perterriti barbari, qui domicilia fixere cis Rhenum, partim difficiles vias et suapte natura clivosas, concaedibus clausere sollerter, arboribus immensi roboris caesis; alii occupatis insulis sparsis crebro per flumen Rhenum, ferum ululantes et lugubre, conviciis Romanos incessebant et Caesarem; qui graviore motu animi percitus, ad corripiendos aliquos septem a Barbatione petierat naves, ex his quas velut transiturus amnem ad compaginandos paraverat pontes; qui, nequid per eum impetraretur, omnes incendit.", "st": "16.11"}, {"sp": "N", "t": "Doctus denique exploratorum delatione recens captorum, aestate iam torrida fluvium vado posse transiri, hortatus auxiliares velites cum Bainobaude Cornutorum misit tribuno, facinus memorabile si iuvisset fors patraturos, qui nunc incedendo per brevia, aliquotiens scutis in modum alveorum suppositis, nando ad insulam venere propinquam, egressique promiscue virile et muliebre secus sine aetatis ullo discrimine trucidabant ut pecudes, nanctique vacuas lintres, per eas licet vacillantes evecti, huius modi loca plurima perruperunt, et ubi caedendi satias cepit, opimitate praedarum onusti, cuius partem vi fluminis amiserunt, rediere omnes incolumes.", "st": "16.11"}, {"sp": "N", "t": "Hocque comperto, residui Germani, ut infido praesidio insularum relicto, ad ulteriora necessitudines et fruges opesque barbaricas contulerunt.", "st": "16.11"}, {"sp": "N", "t": "Conversus hinc Iulianus ad reparandas Tres Tabernas (munimentum ita cognominatum,) haut ita dudum obstinatione subversum hostili, quo aedificato constabat ad intima Galliarum (ut consueverant) adire Germanos arceri, et opus spe celerius consummavit, et victum defensoribus ibi locandis, ex barbaricis messibus non sine discriminis metu collectum militis manu, condidit ad usus anni totius.", "st": "16.11"}, {"sp": "N", "t": "Nec sane hoc solo contentus, sibi quoque viginti dierum alimenta parata collegit. Libentius enim bellatores quaesito dexteris propriis utebantur, admodum indignati, quoniam ex commeatu, qui eis recens advectus est, ideo nihil sumere potuerunt, quod partem eius Barbatio, cum transiret iuxta, superbe praesumpsit; residuumque quod superfuit congestum in acervum exussit, quae utrum ut vanus gerebat et demens, an mandatu principis confidenter nefanda multa temptabat, usque in id temporis latuit.", "st": "16.11"}, {"sp": "N", "t": "Illud tamen rumore tenus ubique iactabatur, quod Iulianus non levaturus incommoda Galliarum electus est, sed ut possit per bella deleri saevissima, rudis etiam tum ut existimabatur, et ne sonitum quidem duraturus armorum.", "st": "16.11"}, {"sp": "N", "t": "Dum castrorum opera mature consurgunt, militisque pars stationes praetendit agrarias, alia frumenta insidiarum metu colligit caute, multitude barbarica rumorem nimia velocitate praeversa, Barbationem cum exercitu quem regebat (ut praedictum est) Gallico vallo discretum impetu repentino aggressa, sequensque fugientes ad usque Rauracos et ultra quoad potuit, rapta sarcinarum et iumentorum cum calonibus parte maxima redit ad suos.", "st": "16.11"}, {"sp": "N", "t": "Et ille tamquam expeditione eventu prospero terminata, milite disperso per stationes hibernas, ad comitatum imperatoris revertit, crimen compositurus in Caesarem (ut solebat).", "st": "16.11"}, {"sp": "N", "t": "Quo dispalato foedo terrore, Alamannorum reges Chonodomarius et Vestralpus, Urius quin etiam et Ursicinus, cum Serapione et Suomario et Hortario, in unum robore virium suarum omni collecto, bellicumque canere bucinis iussis, venere prope urbem Argentoratum, extrema metuentem Caesarem arbitrati retrocessisse, cum ille tum etiam perficiendi munimenti studio stringeretur.", "st": "16.12"}, {"sp": "N", "t": "Erexit autem confidentiam caput altius attollentum scutarius perfuga, qui commissi criminis metuens poenam, transgressus ad eos post ducis fugati discessum, armatorum tredecim milia tantum remansisse cum Iuliano docebat—is enim numerus eum sequebatur—barbara feritate certaminum rabiem undique concitante.", "st": "16.12"}, {"sp": "N", "t": "Cuius asseveratione eadem subinde replicantis, ad maiora stimulati fiducia, missis legatis, satis pro imperio Caesari mandaverunt, ut terris abscederet virtute sibi quaesitis et ferro; qui ignarus pavendi, nec ira nec dolore perculsus, sed fastus barbaricos ridens, tentis legatis ad usque perfectum opus castrorum, in eodem gradu constantiae stetit immobilis.", "st": "16.12"}, {"sp": "N", "t": "Agitabat autem miscebatque omnia, sine modo ubique sese diffunditans, et princeps audendi periculosa, rex Chonodomarius, ardua subrigens supercilia, ut saepe secundis rebus elatus.", "st": "16.12"}, {"sp": "N", "t": "Nam et Decentium Caesarem superavit, aequo Marte congressus, et civitates erutas multas vastavit et opulentas, licentiusque diu nullo refragante Gallias persultavit. Ad cuius roborandam fiduciam, recens quoque fuga ducis accessit, numero praestantis et viribus.", "st": "16.12"}, {"sp": "N", "t": "Alamanni enim scutorum insignia contuentes, norant eos milites permisisse paucis suorum latronibus terrain, quorum metu aliquotiens, antequam gradum conferrent, amissis pluribus abiere dispersi. Quae anxie ferebat sollicitus Caesar, quod trudente ipsa necessitate, digresso periculi socio, cum paucis (licet fortibus) populosis gentibus occurrere cogebatur.", "st": "16.12"}, {"sp": "N", "t": "Iamque solis radiis rutilantibus, tubarumque concinente clangore, pedestres copiae lentis incessibus educuntur, earumque lateri equestres iunctae sunt turmae, inter quas cataphractarii erant et sagittarii, formidabile genus armorum.", "st": "16.12"}, {"sp": "N", "t": "Et quoniam a loco, unde Romana promota sunt signa, ad usque vallum barbaricum quarta leuga signabatur et decima, id est unum et viginti milia passuum, utilitati securitatique recte consulens Caesar, revocatis procursatoribus iam antegressis, indictaque solitis vocibus quiete, cuneatim circumsistentes alloquitur, genuina placiditate sermonis:", "st": "16.12"}, {"sp": "N", "t": "“Urget ratio salutis tuendae communis, ut parcissime dicam, non iacentis animi Caesarem hortari vos et orare,—commilitones mei—ut adulta robustaque virtute confisi, cautiorem viam potius eligamus, ad toleranda vel ad depellenda quae sperantur, non praeproperam et ancipitem.", "st": "16.12"}, {"sp": "N", "t": "“Ut enim in periculis iuventutem impigram esse convenit et audacem, ita (cum res postulat) regibilem et consultam. Quid igitur censeo, si arbitrium affuerit vestrum, iustaque sustinet indignatio, paucis absolvam.", "st": "16.12"}, {"sp": "N", "t": "“Iam dies in meridiem vergit, lassitudine nos itineris fatigatos, scrupulosi tramites excipient et obscuri, nox senescente luna nullis sideribus adiuvanda, terrae protinus aestu flagrantes, nullis aquarum subsidiis fultae; quae si dederit quisquam commode posse transiri, ruentibus hostium examinibus post otium cibique refectionem et potus, quid nos agamus? Quo vigore inedia siti laboreque membris marcentibus occurramus?", "st": "16.12"}, {"sp": "N", "t": "“Ergo quoniam negotiis difficillimis quoque saepe dispositio tempestiva prospexit, et statum nutantium rerum, recto consilio in bonam partem accepto, aliquotiens divina remedia repararunt, hic quaeso vallo fossaque circumdati, divisis vigiliis, quiescamus, somnoque et victu congruis potiti pro tempore, pace dei sit dictum, triumphaturas aquilas et vexilla victricia primo lucis moveamus exordio.”", "st": "16.12"}, {"sp": "N", "t": "Nec finiri perpessi quae dicebantur, stridore dentium infrendentes, ardoremque pugnandi hastis illidendo scuta monstrantes, in hostem se duci iam conspicuum exorabant, caelestis dei favore, fiduciaque sui, et fortunati rectoris expertis virtutibus freti, atque (ut exitus docuit) salutaris quidam genius praesens ad dimicandum eos (dum adesse potuit), incitabat.", "st": "16.12"}, {"sp": "N", "t": "Accessit huic alacritati plenus celsarum potestatum assensus, maximeque Florenti praefecti praetorio, periculose quidem sed ratione secunda pugnandum esse censentis, dum starent barbari conglobati, qui si diffluxissent, motum militis in seditiones nativo calore propensioris ferri non posse aiebat, extortam sibi victoriam (ut putavit) non sine ultimorum conatu graviter toleraturi.", "st": "16.12"}, {"sp": "N", "t": "Addiderat autem fiduciam nostris consideratio gemina, recordantibus quod anno nuper emenso, Romanis per transrhenana spatia fusius volitantibus, nec visus est quisquam laris sui defensor, nec obvius stetit, sed concaede arborum densa undique semitis clausis, sidere urente brumali, aegre vixere barbari longius amendati, quodque imperatore terras eorum ingresso, nec resistere ausi, nec apparere, pacem impetraverunt, suppliciter obsecrantes.", "st": "16.12"}, {"sp": "N", "t": "Sed nullus mutatam rationem temporis advertebat, quod tune tripertito exitio premebantur, imperatore urgente per Raetias, Caesare proximo nusquam elabi permittente, finitimis, quos hostes fecere discordiae, modo non occipitia conculcantibus hinc indeque cinctorum. Postea vero pace data discesserat imperator, et sedata iurgiorum materia, vicinae gentes iam concordabant, et turpissimus ducis Romani digressus ferociam natura conceptam auxit in maius.", "st": "16.12"}, {"sp": "N", "t": "Alio itidem modo res est aggravata Romana, ex negotio tali. Regii duo fratres vinculo pacis adstricti, quam anno praeterito impetraverant a Constantio, nec tumultuare nec commoveri sunt ausi. Sed paulo postea uno ex his Gundomado, qui potior erat, fideique firmioris, per insidias interempto, omnis eius populus cum nostris hostibus conspiravit et confestim Vadomarii plebs (ipso invito, ut asserebat) agminibus bella cientium barbarorum sese coniunxit.", "st": "16.12"}, {"sp": "N", "t": "Cunctis igitur summis infimisque approbantibus tune opportune congrediendum, nec de rigore animorum quicquam remittentibus, exclamavit subito signifer “Perge, felicissime omnium Caesar, quo te fortuna prosperior ducit; tandem per te virtutem et consilia militare sentimus. Praevius ut faustus antesignanus et fortis, experieris quid miles sub conspectu bellicosi ductoris testisque individui gerendorum, modo adsit superum numen, viribus efficiet excitatis.”", "st": "16.12"}, {"sp": "N", "t": "His auditis cum nullae laxarentur indutiae, promotus exercitus prope collem advenit molliter editum, opertum segetibus iam maturis, a superciliis Rheni haut longo intervallo distantem; ex cuius summitate speculatores hostium tres equites exciti, subito nuntiaturi Romanum exercitum adventare, festinarunt ad sues, unus vero pedes qui sequi non potuit, captus agilitate nostrorum, indicavit per triduum et trinoctium flumen transisse Germanos.", "st": "16.12"}, {"sp": "N", "t": "Quos cum iam prope densantes semet in cuneos nostrorum conspexere ductores, steterunt vestigiis fixis, antepilanis hastatisque et ordinum primis, velut insolubili muro fundatis, et pari cautela hostes stetere cuneati.", "st": "16.12"}, {"sp": "N", "t": "Cumque ita ut ante dictus docuerat perfuga, equitatum omnem a dextro latere sibi vidissent oppositum, quicquid apud eos per equestres copias praepollebat, in laevo cornu locavere confertum. Eisdemque sparsim pedites miscuere discursatores et leves, profecto ratione tuta poscente.", "st": "16.12"}, {"sp": "N", "t": "Norant enim licet prudentem ex equo bellatorem cum clibanario nostro congressum, frena retinentem et scutum, hasta una manu vibrata, tegminibus ferreis abscondito bellatori nocere non posse, peditem vero inter ipsos discriminum vertices, cum nihil caveri solet praeter id quod occurrit, humiliter et occulte reptantem, latere forato iumenti, incautum rectorem praecipitem agere, levi negotio trucidandum.", "st": "16.12"}, {"sp": "N", "t": "Hoc itaque disposito, dextrum sui latus struxere clandestinis insidiis et obscuris. Ductabant autem populos omnes pugnaces et saevos Chonodomarius et Serapio, potestate excelsiores ante alios reges.", "st": "16.12"}, {"sp": "N", "t": "Et Chonodomarius quidem nefarius turbinis totius incentor, cuius vertici flammeus torulus aptabatur, anteibat cornu sinistrum, audax et fidens ingenti robore lacertorum, ubi ardor proelii sperabatur, immanis, equo spumante sublimior, erectus in iaculum formidandae vastitatis, armorumque nitore conspicuus ante alios, et strenuus miles et utilis praeter ceteros ductor.", "st": "16.12"}, {"sp": "N", "t": "Latus vero dextrum Serapio agebat etiam tum adultae lanuginis iuvenis, efficacia praecurrens aetatem; Mederichi fratris Chonodomarii filius, hominis quoad vixerat perfidissimi; ideo sic appellatus, quod pater eius diu obsidatus pignore tentus in Galliis, doctusque Graeca quaedam arcana, hunc filium suum, Agenarichum genitali vocabulo dictitatum, ad Serapionis transtulit nomen.", "st": "16.12"}, {"sp": "N", "t": "Hos sequebantur potestate proximi reges, numero quinque, regalesque decem, et optimatum series magna, armatorumque milia triginta et quinque, ex variis nationibus partim mercede, partim pacto vicissitudinis reddendae quaesita.", "st": "16.12"}, {"sp": "N", "t": "Iamque torvum concrepantibus tubis, Severus dux Romanorum, aciem dirigens laevam, cum prope fossas armatorum refertas venisset, unde dispositum erat ut abditi repente exorti cuncta turbarent, stetit impavidus, suspectiorque de obscuris, nec referre gradum nec ulterius ire temptavit.", "st": "16.12"}, {"sp": "N", "t": "Quo viso, animosus contra labores maximos Caesar, ducentis equitibus saeptus, ut ardor negotii flagitabat, agmina peditum impetu veloci discurrerent, verbis hortabatur et gestu.", "st": "16.12"}, {"sp": "N", "t": "Et quoniam alloqui pariter omnes nec longitude spatiorum extenta, nec in unum coactae multitudinis permitteret crebritas, (et alioqui vitabat gravioris invidiae pondus, ne videretur id affectasse quod soli sibi deberi Augustus existimabat) incautior sui hostium tela praetervolans, his et similibus notos pariter et ignotos ad faciendum fortiter accendebat.", "st": "16.12"}, {"sp": "N", "t": "“Advenit—o socii—iustum pugnandi iam tempus, olim exoptatum mihi vobiscum, quod antehac arcessentes, arma inquietis motibus poscebatis.”", "st": "16.12"}, {"sp": "N", "t": "Item cum ad alios postsignanos, in acie locatos extrema, venisset, “En” inquit “commilitones, diu speratus praesto est dies, compellens nos omnes, elutis pristinis maculis, Romanae maiestati reddere proprium decus. Hi sunt barbari quos rabies et immodicus furor ad perniciem rerum suarum coegit occurrere, nostris viribus opprimendos.”", "st": "16.12"}, {"sp": "N", "t": "Alios itidem bellandi usu diutino callentes, aptius ordinans, his exhortationibus adiuvabat: “Exsurgamus—viri fortes—propulsemus fortitudine congrua illisa nostris partibus probra, quae contemplans Caesaris nomen cunctando suscepi.”", "st": "16.12"}, {"sp": "N", "t": "Quoscumque autem pugnae signum inconsulte poscentes, rupturosque imperium irrequietis motibus praevideret, “Quaeso” inquit “ne hostes vertendos in fugam sequentes avidius, futurae victoriae gloriam violetis, neu quis ante necessitatem ultimam cedat. Nam fugituros procul dubio deseram, hostium terga caesuris adero indiscretus, si hoc pensatione moderata fiat et cauta.”", "st": "16.12"}, {"sp": "N", "t": "Haec aliaque in eundem modum saepius replicando, maiorem exercitus partem primae barbarorum opposuit fronti, et subito Alamannorum peditum fremitus, indignationi mixtus auditus est, unanimi conspiratione vociferantium, relictis equis secum oportere versari regales, ne siquid contigisset adversum, deserta miserabili plebe, facilem discedendi copiam reperirent.", "st": "16.12"}, {"sp": "N", "t": "Hocque comperto, Chonodomarius iumento statim desiluit, et secuti eum residui idem fecere, nihil morati; nec enim eorum quisquam ambigebat partem suam fore victricem.", "st": "16.12"}, {"sp": "N", "t": "Dato igitur aeneatorum accentu sollemniter signo ad pugnandum utrimque, magnis concursum est viribus. Paulisper praepilabantur missilia, et properantes concito quam considerato cursu Germani, telaque dextris explicantes, involavere nostrorum equitum turmas, frendentes immania, eorumque ultra solitum saevientium, comae fluentes horrebant, et elucebat quidam ex oculis furor, quos contra pertinax miles, scutorum obicibus vertices tegens, eiectansque gladios, vel tela concrispans, mortem minitantia perterrebat.", "st": "16.12"}, {"sp": "N", "t": "Cumque in ipso proeliorum articulo eques se fortiter conturmaret, et muniret latera sua firmius pedes, frontem artissimis conserens parmis, erigebantur crassi pulveris nubes, variique fuere discursus, nunc resistentibus, nunc cedentibus nostris, et obnixi genibus quidam barbari peritissimi bellatores, hostem propellere laborabant, sed destinatione nimia dexterae dexteris miscebantur et umbo trudebat umbonem, caelumque exsultantium cadentiumque resonabat a vocibus magnis, et cum cornu sinistrum artius gradiens, urgentium tot agmina Germanorum vi nimia pepulisset, iretque in barbaros fremens, equites nostri cornu tenentes dextrum, praeter spem incondite discesserunt, dumque primi fugientium postremos impediunt, gremio legionum protecti, fixerunt integrate proelio gradum.", "st": "16.12"}, {"sp": "N", "t": "Hoc autem exinde acciderat, quod dum ordinum restituitur series, cataphracti equites viso rectore suo leviter vulnerato, et consorte quodam per cervicem equi labente, pondere armorum oppressi, dilapsi qua quisque poterat, peditesque calcando cuncta turbassent, ni conferti illi sibique vicissim innexi stetissent immobiles. Igitur cum equites nihil praeter fugae circumspectantes praesidia, vidisset longius Caesar, concito equo, eos velut repagulum quoddam cohibuit.", "st": "16.12"}, {"sp": "N", "t": "Quo agnito per purpureum signum draconis, summitati hastae longioris aptatum, velut senectutis pandentis exuvias, stetit unius turmae tribunus, et pallore timoreque perculsus, ad aciem integrandam recurrit.", "st": "16.12"}, {"sp": "N", "t": "Utque in rebus amat fieri dubiis, eosdem lenius increpans Caesar, “Quo” inquit “cedimus, viri fortissimi? an ignoratis, fugam quae salutem numquam repperit, irriti conatus stultitiam indicare? Redeamus ad nostros, saltim gloriae futuri participes, si eos pro re publica dimicantes reliquimus inconsulte.”", "st": "16.12"}, {"sp": "N", "t": "Haec reverenter dicendo, reduxit omnes ad munia subeunda bellandi, imitatus salva differentia veterem Sullam, qui cum contra Archelaum (Mithridatis ducem) educta acie proelio fatigabatur ardenti, relictus a militibus cunctis, cucurrit in ordinem primum, raptoque et coniecto vexillo in partem hostilem, “Ite” dixerat “socii periculorum electi, et scitantibus ubi relictus sim imperator, respondete nihil fallentes: ‘solus in Boeotia pro omnibus nobis cum dispendio sanguinis sui decernens.’”", "st": "16.12"}, {"sp": "N", "t": "Proinde Alamanni, pulsis disiectisque equitibus nostris, primam aciem peditum incesserunt, eam abiecta resistendi animositate pulsuri.", "st": "16.12"}, {"sp": "N", "t": "Sed postquam comminus ventum est, pugnabatur paribus diu momentis. Cornuti enim et Bracchiati, usu proeliorum diuturno firmati, eos iam gestu terrentes, barritum ciere vel maximum: qui clamor ipso fervore certaminum, a tenui susurro exoriens, paulatimque adulescens ritu extollitur fluctuum, cautibus illisorum; iaculorum deinde stridentium crebritate, hinc indeque convolante, pulvis aequali motu adsurgens, et prospectum eripiens arma armis corporaque corporibus obtrudebat.", "st": "16.12"}, {"sp": "N", "t": "Sed violentia iraque incompositi, barbari in modum exarsere flammarum, nexamque scutorum compagem, quae nostros in modum testudinis tuebatur, scindebant ictibus gladiorum assiduis.", "st": "16.12"}, {"sp": "N", "t": "Quo cognito opitulatum conturmalibus suis celeri cursu Batavi venere cum Regibus, formidabilis manus, extremae necessitatis arficulo circumventos, (si iuvisset fors) ereptura, torvumque canentibus classicis, adultis viribus certabatur.", "st": "16.12"}, {"sp": "N", "t": "Verum Alamanni bella alacriter ineuntes, altius anhelabant, velut quodam furoris afflatu, opposita omnia deleturi. Spicula tamen verrutaque missilia non cessabant, ferrataeque arundines fundebantur, quamquam etiam comminus mucro feriebat contra mucronem, et loricae gladiis findebantur, et vulnerati nondum effuso cruore ad audendum exsertius consurgebant.", "st": "16.12"}, {"sp": "N", "t": "Pares enim quodam modo coiere cum paribus, Alamanni robusti et celsiores, milites usu nimio dociles; illi feri et turbidi, hi quieti et cauti; animis isti fidentes, grandissimis illi corporibus freti.", "st": "16.12"}, {"sp": "N", "t": "Resurgebat tamen aliquotiens armorum pondere pulsus loco Romanus, lassatisque impressus genibus laevum reflectens poplitem barbarus subsidebat, hostem ultro lacessens, quod indicium est obstinationis extremae.", "st": "16.12"}, {"sp": "N", "t": "Exsiluit itaque subito ardens optimatium globus, inter quos decernebant et reges, et sequente vulgo ante alios agmina nostrorum irrupit, et iter sibi aperiendo, ad usque Primanorum legionem pervenit locatam in medio—quae confirmatio castra praetoria dictitatur,-ubi densior et ordinibus frequens, miles instar turrium fixa firmitate consistens, proelium maiore spiritu repetivit, et vulneribus declinandis intentus, seque in modum mirmillonis operiens, hostium latera, quae nudabat ira flagrantior, districtis gladiis perforabat.", "st": "16.12"}, {"sp": "N", "t": "At illi prodigere vitam pro victoria contendentes, temptabant agminis nostri laxare compagem. Sed continuata serie peremptorum, quos Romanus iam fidentior stravit, succedebant barbari superstites interfectis, auditoque occumbentium gemitu crebro, pavore perfusi torpebant.", "st": "16.12"}, {"sp": "N", "t": "Fessi denique tot aerumnis, et ad solam deinceps strenui fugam, per diversos tramites tota celeritate digredi festinabant, ut e mediis saevientis pelagi fluctibus, quocumque avexerit ventus, eici nautici properant et vectores; quod voti magis quam spei fuisse fatebitur quilibet tunc praesens.", "st": "16.12"}, {"sp": "N", "t": "Aderatque propitiati numinis arbitrium clemens, et secans terga cedentium miles cum interdum flexis ensibus feriendi non suppeterent instrumenta, erepta ipsis barbaris tela eorum vitalibus immergebat, nec quisquam vulnerantium sanguine iram explevit nec satiavit caede multiplici dexteram, vel miseratus supplicantem abscessit.", "st": "16.12"}, {"sp": "N", "t": "Iacebant itaque plurimi transfixi letaliter, remedia mortis compendio postulantes, alii semineces, labente iam spiritu, lucis usuram oculis morientibus inquirebant, quorundam capita discissa trabalibus telis, et pendentia iugulis cohaerebant, pars per limosum et lubricum solum, in sociorum cruore relapsi, intactis ferro corporibus, acervis superruentium obruti necabantur.", "st": "16.12"}, {"sp": "N", "t": "Quae ubi satis evenere prosperrime, validius instante victore, acumina densis ictibus hebescebant, splendentesque galeae sub pedibus volvebantur et scuta, ultimo denique trudente discrimine, barbari, cum elati cadaverum aggeres exitus impedirent, ad subsidia fluminis petivere, quae sola restabant, eorum terga iam perstringentis.", "st": "16.12"}, {"sp": "N", "t": "Et quia cursu sub armis concito, fugientes miles indefessus urgebat, quidam nandi peritia eximi se posse discriminibus arbitrati, animas fluctibus commiserunt. Qua causa celeri corde futura praevidens Caesar, cum tribunis et ducibus clamore obiugatorio prohibebat, ne hostem avidius sequens, nostrorum quisquam se gurgitibus committeret verticosis.", "st": "16.12"}, {"sp": "N", "t": "Unde id observatum est, ut marginibus insistentes, confoderent telorum varietate Germanos, quorum siquenm morti velocitas subtraxisset, iacti corporis pondere ad ima fluminis subsidebat.", "st": "16.12"}, {"sp": "N", "t": "Et velut in quodam theatrali spectaculo, aulaeis miranda monstrantibus multa, licebat iam sine metu videre nandi strenuis quosdam nescios adhaerentes, fluitantes alios cum expeditioribus linquerentur ut stipites, et velut luctante amnis violentia vorari quosdam fluctibus involutos, non nullos clipeis vectos, praeruptas undarum occursantium molis, obliquatis meatibus declinantes, ad ripas ulteriores post multa discrimina pervenire. Spumans denique cruore barbarico, decolor alveus insueta stupebat augmenta.", "st": "16.12"}, {"sp": "N", "t": "Dum haec ita aguntur, rex Chonodomarius reperta copia discedendi, lapsus per funerum strues, cum satellitibus paucis, celeritate rapida properabat ad castra, quae prope Tribuncos et Concordiam munimenta Romana, fixit intrepidus, ut escensis navigiis, dudum paratis ad casus ancipites, in secretis secessibus se amendaret.", "st": "16.12"}, {"sp": "N", "t": "Et quia non nisi Rheno transito ad territoria sua poterat pervenire, vultum ne agnosceretur operiens, sensim retulit pedem. Cumque propinquaret iam ripis, lacunam palustribus aquis interfusam circumgrediens ut transiret, calcata mollitie glutinosa, equo est evolutus, et confestim licet obeso corpore gravior, ad subsidium vicini collis evasit, quem agnitum (nec enim potuit celare qui fuerit, fortunae prioris magnitudine proditus), statim anhelo cursu cohors cum tribuno secuta, armis circumdatum aggerem nemorosum, cautius obsidebat, perrumpere verita, ne fraude latenti inter ramorum tenebras exciperetur occultas.", "st": "16.12"}, {"sp": "N", "t": "Quibus visis, compulsus ad ultimos metus, ultro se dedidit solus egressus, comitesque eius ducenti numero et tres amici iunctissimi, flagitium arbitrati post regem vivere, vel pro rege non mori, si ita tulerit casus, tradidere se vinciendos.", "st": "16.12"}, {"sp": "N", "t": "Utque nativo more sunt barbari humiles in adversis, disparesque in secundis, servus alienae voluntatis trahebatur pallore confusus, claudente noxarum conscientia linguam, immensum quantum ab eo differens, qui post feros lugubresque terrores, cineribus Galliarum insultans, multa minabatur et saeva.", "st": "16.12"}, {"sp": "N", "t": "Quibus ita favore superni numinis terminatis, post exactum iam diem, occinente liticine revocatus invitissimus miles, prope supercilia Rheni tendebat, scutorumque ordine multiplicato vallatus, victu fruebatur et somno.", "st": "16.12"}, {"sp": "N", "t": "Ceciderunt autem in hac pugna Romani quidem CCXL et III, rectores vero III: Bainobaudes Cornutorum tribunus, adaeque Laipso et Innocentius cataphractarios ducens, et vacans quidam tribunus, cuius non suppetit nomen; ex Alamannis vero sex milia corporum numerata sunt, in campo constrata, et alii inaestimabiles mortuorum acervi per undas fluminis ferebantur.", "st": "16.12"}, {"sp": "N", "t": "Tune Iulianus, ut erat fortuna sui spectatior, meritisque magis quam imperio potens, Augustus acclamatione concordi totius exercitus appellatus, ut agentes petulantius milites increpabat, id se nec sperare nec adipisci velle iurando confirmans.", "st": "16.12"}, {"sp": "N", "t": "Et ut augeret eventus secundi laetitiam, concilio convocato propositisque praemiis, propitio ore Chonodomarium sibi iussit offerri. Qui primo curvatus, deinde humi suppliciter fusus, gentilique prece veniam poscens, bono animo esse est iussus.", "st": "16.12"}, {"sp": "N", "t": "Et diebus postea paucis ductus ad comitatum imperatoris, missusque exinde Romam, in castris peregrinis, quae in monte sunt Caelio, morbo veterni consumptus est.", "st": "16.12"}, {"sp": "N", "t": "His tot ac talibus prospero peractis eventu, in palatio Constanti quidam Iulianum culpantes, ut princeps ipse delectaretur, irrisive Victorinum ideo nominabant, quod verecunde referens quotiens imperaret, superatos indicabat saepe Germanos.", "st": "16.12"}, {"sp": "N", "t": "Interque exaggerationem inanium laudum, ostentationemque aperte lucentium, inflabant ex usu imperatorem, suopte ingenio nimium, quicquid per omnem terrae ambitum agebatur, felicibus eius auspiciis assignantes.", "st": "16.12"}, {"sp": "N", "t": "Quocirca magniloquentia elatus adulatorum, tune et deinde edictis propositis, arroganter satis multa mentiebatur, se solum (cum gestis non adfuisset) et dimicasse et vicisse et supplices reges gentium erexisse aliquotiens scribens, et si verbi gratia eo agente tune in Italia, dux quidam egisset fortiter contra Persas, nulla eius mentione per textum longissimum facta, laureatas litteras ad provinciarum damna mittebat, se inter primores versatum cum odiosa sui iactatione significans.", "st": "16.12"}, {"sp": "N", "t": "Exstant denique eius dicta, in tabulariis principis publicis condita, in quibus ambitiose delata narrandi extollendique semet in caelum. Ab Argentorato cum pugnaretur, mansione quadragesima disparatus, describens proelium aciem ordinasse, et stetisse inter signiferos, et barbaros fugasse praecipites, sibique oblatum falso indicat Chonodomarium (pro rerum indignitas) super Iuliani gloriosis actibus conticescens, quos sepelierat penitus, ni fama res maximas, vel obumbrantibus plurimis, silere nesciret.", "st": "16.12"}, {"sp": "HDR", "t": "Liber XVII", "st": "17"}, {"sp": "N", "t": "Hac rerum varietate, quam iam digessimus, ita conclusa, Martius iuvenis, Rheno post Argentoratensem pugnam otiose fluente, securus, sollicitusque idem ne dirae volucres consumerent corpora peremptorum, sine discretione cunctos humari mandavit, absolutisque legatis, quos ante certamen superba quaedam portasse praediximus, ad Tres Tabernas revertit.", "st": "17.1"}, {"sp": "N", "t": "Unde cum captivis omnibus praedam Mediomatricos servandam ad reditum usque suum duci praecipit, et petiturus ipse Mogontiacum, ut ponte compacto transgressus, in suis regionibus requireret barbaros, cum nullum reliquisset in nostris, refragante vetabatur exercitu; verum facundia iucunditateque sermonum allectum, in voluntatem traduxerat suam. Amor enim post documenta flagrantior, sequi libenter hortatus est omnis operae conturmalem, auctoritate magnificum ducem, plus laboris indicere sibi quam militi, sicut perspicue contigit, assuetum. Moxque ad locum praedictum est ventum, flumine pontibus constratis transmisso, occupavere terras hostiles.", "st": "17.1"}, {"sp": "N", "t": "At barbari perstricti negotii magnitudine, qui se in tranquillo positos otio, tunc parum inquietari posse sperabant, aliorum exitio quid fortunis suis immineret anxie cogitantes, simulata pacis petitione, ut primae vertiginis impetum declinarent, misere legatos cum verbis compositis, quae denuntiarent concordem foederum firmitatem; incertumque quo consilio statim instituto, mutata voluntate, per alios cursu celeri venire compulsos, acerrimum nostris minati sunt bellum, ni eorum regionibus excessissent.", "st": "17.1"}, {"sp": "N", "t": "Quibus clara fide compertis, Caesar noctis prima quiete, navigiis modicis et velocibus octingentos imposuit milites, ut spatio stadiorum xx sursum versum decurso egressi, quicquid invenire potuerint, ferro violarent et flammis.", "st": "17.1"}, {"sp": "N", "t": "Quo ita disposito, solis primo exortu, visis per montium vertices barbaris, ad celsiora ducebatur alacrior miles, nulloque invento (hoc si quidem opinati discessere confestim) eminus ingentia fumi volumina visebantur, indicantia nostros perruptas populari terras hostiles.", "st": "17.1"}, {"sp": "N", "t": "Quae res Germanorum perculit animos, atque desertis insidiis, quas per arta loca et latebrosa struxerant nostris, trans Menum nomine fluvium ad opitulandum suis necessitudinibus avolarunt.", "st": "17.1"}, {"sp": "N", "t": "Ut enim in rebus amat fieri dubiis et turbatis, hinc equitum nostrorum accursu, inde navigiis vectorum militum impetu repentino perterrefacti, evadendi subsidium velox locorum invenere prudentes, quorum digressu miles libere gradiens, opulentas pecore villas et frugibus rapiebat, nulli parcendo, extractisque captivis, domicilia cuncta, curatius ritu Romano constructa, flammis subditis exurebat.", "st": "17.1"}, {"sp": "N", "t": "Emensaque aestimatione decimi lapidis, cum prope silvam venisset squalore tenebrarum horrendam, stetit dux diu cunctando, indicio perfugae doctus per subterranea quaedam occulta, fossasque multifidas, latere hostium plurimos, ubi habile visum fuerit erupturos.", "st": "17.1"}, {"sp": "N", "t": "Ausi tamen omnes accedere fidentissime, ilicibus incisis et fraxinis, roboreque abietum magno, semitas invenere constratas. Ideoque gradientes cautius retro, non nisi per anfractus longos et asperos ultra progredi posse, vix indignationem capientibus animis, advertebant.", "st": "17.1"}, {"sp": "N", "t": "Et quoniam aeris urente saevitia cum discriminibus ultimis laboratur in cassum (aequinoctio quippe autumnali exacto, per eos tractus superfusae nives opplevere montes simul et campos) opus arreptum est memorabile.", "st": "17.1"}, {"sp": "N", "t": "Et dum nullus obsisteret, munimentum quod in Alamannorum solo conditum Traianus suo nomine voluit appellari, dudum violentius oppugnatum, tumultuario studio reparatum est; locatisque ibi pro tempore defensoribus, ex barbarorum visceribus alimenta congesta sunt.", "st": "17.1"}, {"sp": "N", "t": "Quae illi maturata ad suam perniciem contemplantes, metuque rei peractae volucriter congregati, precibus et humilitate suprema, petiere missis oratoribus pacem; quam Caesar omni consiliorum via firmatam, causatus veri similia plurima, per decem mensium tribuit intervallum; id nimirum sollerti colligens mente, quod castra supra quam optari potuit occupata sine obstaculo, tormentis muralibus et apparatu deberent valido communiri.", "st": "17.1"}, {"sp": "N", "t": "Hac fiducia tres immanissimi reges venerunt tandem aliquando iam trepidi, ex his qui misere victis apud Argentoratum auxilia, iurantes conceptis ritu patrio verbis nihil inquietum acturos, sed foedera ad praestitutum usque diem, quia id nostris placuerat, cum munimento servaturos intacto, frugesque portaturos humeris suis, si defuisse sibi docuerint defensores. Quod utrumque, metu perfidiam frenante, fecerunt.", "st": "17.1"}, {"sp": "N", "t": "Hoc memorabili bello, comparando quidem Punicis et Teutonicis, sed dispendiis rei Romanae peracto levissimis, ut faustus Caesar exultabat et felix; credique obtrectatoribus potuit, ideo fortiter eum ubique fecisse fingentibus, quod oppetere dimicando gloriose magis optabat, quam damnatorum sorte (sicut sperabat,) ut frater Gallus occidi, ni pari proposito post excessum quoque Constanti actibus mirandis inclaruisset.", "st": "17.1"}, {"sp": "N", "t": "Quibus ut in tali re compositis firmiter, ad sedes revertens hibernas, sudorum reliquias repperit tales. Remos Severus magister equitum per Agrippinam petens et Iuliacum, Francorum validissimos cuneos, in sexcentis velitibus (ut postea claruit,) vacua praesidiis loca vastantes, offendit; hac opportunitate in scelus audaciam erigente, quod Caesare in Alamannorum secessibus occupato, nulloque vetante, expleri se posse praedarum opimitate sunt arbitrati. Sed metu iam reversi exercitus, munimentis duobus, quae olim exinanita sunt, occupatis, se quoad fieri poterat, tuebantur.", "st": "17.2"}, {"sp": "N", "t": "Hac Iulianus rei novitate perculsus, et coniciens quorsum erumperet, si eisdem transisset intactis, retento milite circumvallare disposuit castella munita, quae Mosa fluvius praeterlambit, et ad usque quartum et quinquagesimum diem, Decembri scilicet et Ianuario mense, obsidionales tractae sunt morae, destinatis barbarorum animis incredibili pertinacia reluctantibus.", "st": "17.2"}, {"sp": "N", "t": "tunc pertimescens sollertissimus Caesar, ne observata nocte inluni, barbari gelu vinctum amnem pervaderent, cotidie a sole in vesperam flexo, ad usque lucis principium, lusoriis navibus discurrere flumen ultro citroque milites ordinavit, ut crustis pruinarum diffractis, nullus ad erumpendi copiam facile perveniret. Hocque commento, inedia et vigiliis et desperatione postrema lassati, sponte se propria dederunt, statimque ad comitatum Augusti sunt missi.", "st": "17.2"}, {"sp": "N", "t": "Ad quos eximendos periculo, multitudo Francorum egressa, cum captos comperisset et asportatos, nihil amplius ausa, repedavit ad sua, hisque perfectis, acturus hiemem revertit Parisios Caesar.", "st": "17.2"}, {"sp": "N", "t": "Quia igitur plurimae gentes vi maiore collaturae capita sperabantur, dubia bellorum coniectans, sobrius rector magnis curarum molibus stringebatur. Dumque per indutias, licet negotiosas et breves, aerumnosis possessorum damnis mederi posse credebat, tributi ratiocinia dispensavit.", "st": "17.3"}, {"sp": "N", "t": "Cumque Florentius praefectus praetorio, cuncta permensus (ut contendebat,) quicquid in capitatione deesset, ex conquisitis se supplere firmaret, talium gnarus, animam prius amittere quam hoc sinere fieri memorabat.", "st": "17.3"}, {"sp": "N", "t": "Norat enim huius modi provisionum, immo eversionum, ut verius dixerim, insanabilia vulnera, saepe ad ultimam egestatem provincias contrusisse, quae res (ut docebitur postea,) penitus evertit Illyricum.", "st": "17.3"}, {"sp": "N", "t": "Ob quae praefecto praetorio ferri non posse clamante, se repente factum infidum, cui Augustus summam commiserit rerum, Iulianus eum sedatius leniens, scrupulose computando et vere, docuit non sufficere solum, verum etiam exuberare capitationis calculum ad commeatuum necessarios apparatus.", "st": "17.3"}, {"sp": "N", "t": "Nihilo minus tamen, diu postea indictionale augmentum oblatum sibi nec recitare nec subnotare perpessus, humi proiecit. Litterisque Augusti monitus ex relatione praefecti, non agere ita perplexe, ut videretur parum Florentio credi, rescripsit, gratandum esse si provincialis, hinc inde vastatus, saltem sollemnia praebeat nedum incrementa quae nulla supplicia egenis possent hominibus extorquere. Factumque est tunc et deinde, unius animi firmitate, ut praeter solita nemo Gallis quicquam exprimere conaretur.", "st": "17.3"}, {"sp": "N", "t": "Denique, inusitato exemplo, id petendo Caesar impetraverat a praefecto, ut secundae Belgicae multiformibus malis oppressae, dispositio sibi committeretur, ea videlicet lege, ut nec praefectianus nec praesidialis apparitor ad solvendum quemquam urgeret. Quo levati solatio cuncti, quos in curam susceperat suam, nec interpellati, ante praestitutum tempus debita contulerunt.", "st": "17.3"}, {"sp": "N", "t": "Inter haec recreandarum exordia Galliarum, administrante secundam adhuc Orfito praefecturam, obeliscus Romae in circo erectus est maximo. Super quo nunc (quia tempestivum est) pauca discurram.", "st": "17.4"}, {"sp": "N", "t": "Urbem priscis saeculis conditam, ambitiosa moenium strue et portarum centum quondam aditibus celebrem, hecatompylos Thebas, institutores ex facto cognominarunt, cuius vocabulo provincia nunc usque Thebais appellatur.", "st": "17.4"}, {"sp": "N", "t": "Hanc inter exordia pandentis se late Carthaginis, improviso excursu duces oppressere Poenorum, posteaque reparatam, Persarum rex ille Cambyses, quoad vixerat alieni cupidus et immanis, Aegypto perrupta aggressus est, ut opes exinde raperet invidendas, ne deorum quidem donariis parcens.", "st": "17.4"}, {"sp": "N", "t": "Qui dum inter praedatores turbulente concursat, laxitate praepeditus indumentorum, concidit pronus, ac suomet pugione, quem aptatum femori dextro gestabat, subita vi ruinae nudato, vulneratus paene letaliter interisset.", "st": "17.4"}, {"sp": "N", "t": "Longe autem postea Cornelius Gallus Octaviano res tenente Romanas, Aegypti procurator, exhausit civitatem plurimis interceptis, reversusque cum furtorum arcesseretur, et populatae provinciae, metu nobilitatis acriter indignatae, cui negotium spectandum dederat imperator, stricto incubuit ferro. Is est (si recte existimo) Gallus poeta, quem flens quodam modo in postrema Bucolicorum parte Vergilius carmine leni decantat.", "st": "17.4"}, {"sp": "N", "t": "In hac urbe inter delubra ingentia, diversasque moles, figmenta Aegyptiorum numinum exprimentes, obeliscos vidimus plures, aliosque iacentes et comminutos, quos antiqui reges bello domitis gentibus, aut prosperitatibus summarum rerum elati, montium venis vel apud extremos orbis incolas perscrutatis excisos, et erectos dis superis in religione dicarunt.", "st": "17.4"}, {"sp": "N", "t": "Est autem obeliscus asperrimus lapis, in figuram metae cuiusdam sensim ad proceritatem consurgens excelsam, utque radium imitetur, gracilescens paulatim, specie quadrata in verticem productus angustum, manu levigatus artifici.", "st": "17.4"}, {"sp": "N", "t": "Formarum autem innumeras notas, hieroglyphicas appellatas, quas ei undique videmus incisas, initialis sapientiae vetus insignivit auctoritas.", "st": "17.4"}, {"sp": "N", "t": "Volucrum enim ferarumque etiam alieni mundi genera multa sculpentes, ut ad aevi quoque sequentis aetates, impetratorum vulgatius perveniret memoria, promissa vel soluta regum vota monstrabant.", "st": "17.4"}, {"sp": "N", "t": "Non enim ut nunc litterarum numerus praestitutus et facilis exprimit, quicquid humana mens concipere potest, ita prisci quoque scriptitarunt Aegyptii, sed singulae litterae singulis nominibus serviebant et verbis; non numquam significabant integros sensus.", "st": "17.4"}, {"sp": "N", "t": "Cuius rei scientiam his interim duobus exemplis monstrari sufficiet: per vulturem naturae vocabulum pandunt, quia mares nullos posse inter has alites inveniri, rationes memorant physicae, perque speciem apis mella conficientis, indicant regem, moderatori cum iucunditate aculeos quoque innasci debere his rerum insignibus ostendentes. Et similia plurima.", "st": "17.4"}, {"sp": "N", "t": "Et quia sufflantes adulatores ex more Constantium id sine modo strepebant, quod cum Octavianus Augustus obeliscos duos ab Heliopolitana civitate transtulisset Aegyptia, quorum unus in Circo Maximo alter in Campo locatus est Martio, hunc recens advectum, difficultate magnitudinis territus, nec contrectare ausus est nec movere, discant qui ignorant, veterem principem translatis aliquibus hunc intactum ideo praeterisse, quod Deo Soli speciali munere dedicatus, fixusque intra ambitiosi templi delubra, quae contingi non poterant, tamquam apex omnium eminebat.", "st": "17.4"}, {"sp": "N", "t": "Verum Constantinus id parvi ducens, avulsam hanc molem sedibus suis, nihilque committere in religionem recte existimans, si ablatum uno templo miraculum Romae sacraret, id est in templo mundi totius, iacere diu perpessus est, dum translationi pararentur utilia. Quo convecto per alveum Nili, proiectoque Alexandriae, navis amplitudinis antehac inusitatae aedificata est, sub trecentis remigibus agitanda.", "st": "17.4"}, {"sp": "N", "t": "Quibus ita provisis, digressoque vita principe memorato, urgens effectus intepuit, tandemque sero impositus navi, per maria fluentaque Tibridis, velut paventis, ne quod paene ignotus miserat Nilus, ipse parum sub emeatus sui discrimine moenibus alumnis inferret, defertur in vicum Alexandri, tertio lapide ab urbe seiunctum. Unde chamulcis impositus, tractusque lenius per Ostiensem portam piscinamque publicam, Circo illatus est Maximo.", "st": "17.4"}, {"sp": "N", "t": "Sola post haec restabat erectio, quae vix aut ne vix quidem sperabatur posse compleri. At ea ita est facta: aggestis erectisque digestisque ad perpendiculum altis trabibus (ut machinarum cerneres nemus) innectuntur vasti funes et longi, ad speciem multiplicium liciorum, caelum densitate nimia subtexentes. Quibus colligatus mons ipse effigiatus scriptilibus elementis, paulatimque in arduum per inane protentus, diu pensilis, hominum milibus multis tamquam molendinarias rotantibus metas, cavea locatur in media, eique sphaera superponitur ahenea, aureis lamminis nitens, qua confestim vi ignis divini contacta, ideoque sublata, facis imitamentum infigitur aereum, itidem auro imbracteatum, velut abundanti flamma candentis.", "st": "17.4"}, {"sp": "N", "t": "Secutaeque aetates alios transtulerunt, quorum unus in Vaticano, alter in hortis Sallusti, duo in Augusti monumento erecti sunt.", "st": "17.4"}, {"sp": "N", "t": "Qui autem notarum textus obelisco incisus est veteri, quem videmus in Circo, Hermapionis librum secuti interpretatum litteris subiecimus Graecis. ΑΡΧΗΝ ΑΠΟ ΤΟΥ ΝΟΤΙΟΥ ΔΙΕΡΜΗΝΕΥΜΕΝΑ ΕΧΕΙ ΣΤΙΧΟΣ ΠΡΩΤΟΣ ΤΑΔΕ ΛΕΓΕΙ", "st": "17.4"}, {"sp": "N", "t": "Ἥλιος βασιλεῖ Ῥαμέστῃ· δεδώρημαί σοι ἀνὰ πᾶσαν οἰκουμένην μετὰ χαρᾶς βασιλεύειν, ὃν Ἥλιος φιλεῖ.— [καὶ] Ἀπόλλων κρατερὸς φιλαλήθης υἱὸς Ἥρωνος, θεογέννητος κτιστὴς τῆς οἰκουμένης, ὃν Ἥλιος προέκρινεν, ἄλκιμος Ἄρεως βασιλεὺς Ῥαμέστης. ᾧ πᾶσα ὑποτέτακται ἡ γῆ μετὰ ἀλκῆς καὶ θάρσους. βασιλεὺς Ῥαμέστης Ἡλίου παῖς αἰωνόβιος.", "st": "17.4"}, {"sp": "N", "t": "ΣΤΙΧΟΣ ΔΕΥΤΕΡΟΣ", "st": "17.4"}, {"sp": "N", "t": "Ἀπόλλων κρατερός, ὁ ἑστὼς ἐπ’ ἀληθείας, δεσπότης διαδήματος, τὴν Αἴγυπτον δοξάσας κεκτημένος, ὁ ἀγλαοποιήσας Ἡλίου πόλιν, καὶ κτίσας τὴν λοιπὴν οἰκουμένην, καὶ πολυτιμήσας τοὺς ἐν Ἡλίου πόλει θεοὺς ἀνιδρυμένους, ὃν Ἥλιος φιλεῖ.", "st": "17.4"}, {"sp": "N", "t": "ΤΡΙΤΟΣ ΣΤΙΧΟΣ", "st": "17.4"}, {"sp": "N", "t": "Ἀπόλλων κρατερὸς Ἡλίου παῖς παμφεγγὴς, ὃν Ἥλιος προέκρινεν καὶ Ἄρης ἄλκιμος ἐδωρήσατο. οὗ τὰ ἀγαθὰ ἐν παντὶ διαμένει καιρῷ. ὃν Ἄμμων ἀγαπᾷ, πληρώσας τὸν νέων τοῦ φοίνικος ἀγαθῶν. ᾧ οἱ θεοὶ ζωῆς χρόνον ἐδωρήσαντο.", "st": "17.4"}, {"sp": "N", "t": "Ἀπόλλων κρατερὸς υἱὸς Ἥρωνος βασιλεὺς οἰκουμένης Ῥαμέστης, ὃς ἐφύλαξεν Αἴγυπτον τοὺς ἀλλοεθνεῖς νικήσας, ὃν Ἥλιος φιλεῖ, ᾧ πολὺν χρόνον ζωῆς ἐδωρήσαντο θεοὶ. δεσπότης οἰκουμένης Ῥαμέστης αἰωνόβιος.", "st": "17.4"}, {"sp": "N", "t": "ΛΙΒΟΣ ΣΤΙΧΟΣ ΔΕΥΤΕΡΟΣ", "st": "17.4"}, {"sp": "N", "t": "Ἥλιος θεὸς μέγας δεσπότης οὐρανοῦ. δεδώρημαί σοι βίον ἀπρόσκοπον. Ἀπόλλων κρατερὸς κύριος διαδήματος ἀνείκαστος, ὃς τῶν θεῶν ἀνδριάντας ἀνέθηκεν ἐν τῇδε τῇ βασιλείᾳ, δεσπότης Αἰγύπτου, καὶ ἐκόσμησεν Ἡλίου πόλιν ὁμοίως καὶ αυτὸν Ἥλιον δεσπότην οὐρανοῦ. συνετελεύτησεν ἔργον ἀγαθὸν Ἡλίου παῖς βασιλεὺς αἰωνόβιος.", "st": "17.4"}, {"sp": "N", "t": "ΤΡΙΤΟΣ ΣΤΙΧΟΣ", "st": "17.4"}, {"sp": "N", "t": "Ἥλιος θεὸς δεσπότης οὐρανοῦ Ῥαμέστῃ βασιλεῖ. δεδώρημαι τὸ κράτος καὶ τὴν κατὰ πάντων ἐξουσίαν. ὃν Ἀπόλλων φιλαλήθης δεσπότης χρόνων καὶ Ἥφαιστος ὁ τῶν θεῶν πατὴρ προέκρινεν διὰ τὸν Ἄρεα. βασιλεὺς παγχαρὴς Ἡλίου παῖς, καὶ ὑπὸ Ἡλίου φιλούμενος.", "st": "17.4"}, {"sp": "N", "t": "ΑΦΗΛΙΩΤΗΣ. ΠΡΩΤΟΣ ΣΤΙΧΟΣ", "st": "17.4"}, {"sp": "N", "t": "Ὁ ἀφ’ Ἡλίου πόλεως μέγας θεὸς ἐνουράνιος Ἀπόλλων κρατερός, Ἥρωνος υἱὸς, ὃν Ἥλιος ἠγάπησεν, ὃν οἱ θεοὶ ἐτιμησαν, ὁ πάσης γῆς βασιλεύων, ὃν Ἥλιος προέκρινεν, ὁ ἄλκιμος διὰ τὸν Ἀρεα βασιλεύς, ὅν Ἄμμων φιλεῖ. καὶ ὁ παμφεγγὴς συγκρίνας αἰώνιον βασιλέα et reliqua.", "st": "17.4"}, {"sp": "N", "t": "Datiano et Cereali consulibus, cum universa per Gallias studio cautiore disponerentur, formidoque praeteritorum barbaricos hebetaret excursus, rex Persarum in confiniis agens adhuc gentium extimarum, iamque cum Chionitis et Gelanis, omnium acerrimis bellatoribus, pignore icto societatis, rediturus ad sua, Tamsaporis scripta suscepit, pacem Romanum principem nuntiantis poscere precativam.", "st": "17.5"}, {"sp": "N", "t": "Ideoque non nisi infirmato imperii robore temptari talia suspicatus, latius semet extentans, pacis amplectitur nomen, et condiciones proposuit graves, missoque cum muneribus Narseo quodam legato, litteras ad Constantium dedit nusquam a genuino fastu declinans, quarum hunc fuisse accepimus sensum:", "st": "17.5"}, {"sp": "N", "t": "“Rex regum Sapor, particeps siderum, frater Solis et Lunae, Constantio Caesari fratri meo salutem plurimam dico.", "st": "17.5"}, {"sp": "N", "t": "“Gaudeo tandemque mihi placet, ad optimam viam te revertisse, et incorruptum aequitatis agnovisse suffragium, rebus ipsis expertum pertinax alieni cupiditas quas aliquotiens ediderit strages.", "st": "17.5"}, {"sp": "N", "t": "“Quia igitur veritatis ratio soluta esse debet et libera, et celsiores fortunas idem loqui decet atque sentire, propositum meum in pauca conferam reminiscens, haec quae dicturus sum me saepius replicasse.", "st": "17.5"}, {"sp": "N", "t": "“Ad usque Strymona flumen et Macedonicos fines tenuisse maiores imperium meos, antiquitates quoque vestrae testantur; haec me convenit flagitare (ne sit arrogans quod affirmo) splendore virtutumque insignium serie, vetustis regibus antistantem. Sed ubique mihi cordi est recta ratio, cui coalitus ab adulescentia prima, nihil umquam paenitendum admisi.", "st": "17.5"}, {"sp": "N", "t": "“Ideoque Armeniam recuperare cum Mesopotamia debeo, avo meo composita fraude praereptam. Illud apud nos numquam in acceptum feretur, quod asseritis vos exsultantes, nullo discrimine virtutis ac doli, prosperos omnes laudari debere bellorum eventus.", "st": "17.5"}, {"sp": "N", "t": "“Postremo si morem gerere suadenti volueris recte, contemne partem exiguam, semper luctificam et cruentam, ut cetera regas securus, prudenter reputans medellarum quoque artifices urere non numquam et secare et partes corporum amputare, ut reliquis uti liceat integris, hocque bestias factitare: quae cum advertant cur maximo opere capiantur, illud propria sponte amittunt, ut vivere deinde possint impavidae.", "st": "17.5"}, {"sp": "N", "t": "“Id sane pronuntio, quod si haec mea legatio redierit irrita, post tempus hiemalis quietis exemptum, viribus totis accinctus, fortuna condicionumque aequitate spem successus secundi fundante, venire, quoad ratio siverit, festinabo.”", "st": "17.5"}, {"sp": "N", "t": "His litteris diu libratis, recto pectore (quod dicitur) considerateque responsum est, hoc modo:", "st": "17.5"}, {"sp": "N", "t": "“Victor terra marique Constantius, semper Augustus, fratri meo Sapori regi salutem plurimam dico.", "st": "17.5"}, {"sp": "N", "t": "“Sospitati quidem tuae gratulor ut futurus (si velis,) amicus, cupiditatem vero semper indeflexam fusiusque vagantem, vehementer insimulo.", "st": "17.5"}, {"sp": "N", "t": "“Mesopotamiam poscis ut tuam, perindeque Armeniam, et suades integro corpori adimere membra quaedam, ut salus eius deinceps locetur in solido, quod infindendum est potius quam ulla consensione firmandum. Accipe igitur veritatem, non obtectam praestigiis, sed perspicuam, nullisque minis inanibus perterrendam.", "st": "17.5"}, {"sp": "N", "t": "“Praefectus praetorio meus, opinatus aggredi negotium publicae utilitati conducens, cum duce tuo per quosdam ignobiles, me inconsulto, sermones conseruit super pace. Non refutamus hanc nec repellimus: adsit modo cum decore et honestate, nihil pudori nostro praereptura vel maiestati.", "st": "17.5"}, {"sp": "N", "t": "“Est enim absonum et insipiens nunc cum gestarum rerum ordines (placatae sint aurae invidiae!) nobis multipliciter illuxerunt, cum deletis tyrannis, totus orbis Romanus nobis obtemperat, ea prodere, quae contrusi in orientales angustias, diu servavimus inlibata.", "st": "17.5"}, {"sp": "N", "t": "“Cessent autem quaeso formidines, quae nobis intentantur ex more, cum ambigi nequeat, non inertia nos sed modestia, pugnas interdum excepisse potius quam intulisse, et nostra quotiens lacessimur, fortissimo bonae conscientiae spiritu defensare, id experiendo legendoque scientes, in proeliis quibusdam raro rem titubasse Romanam, in summa vero bellorum numquam ad deteriora prolapsam.”", "st": "17.5"}, {"sp": "N", "t": "Hanc legationem nullo impetrato remissam,— nec enim effrenatae regis cupiditati responderi amplius quicquam potuit—post paucissimos dies secutus est Prosper comes et Spectatus tribunus, et notarius itemque Eustathius, Musoniano suggerente philosophus, ut opifex suadendi; imperatoris scripta perferentes et munera, enisuri apparatum interim Saporis arte quadam suspendere, ne supra humanum modum provinciae munirentur arctoae.", "st": "17.5"}, {"sp": "N", "t": "Inter quae ita ambigua, Iuthungi Alamannorum pars Italicis conterminans tractibus, obliti pacis et foederum, quae adepti sunt obsecrando, Raetias turbulente vastabant, adeo ut etiam oppidorum temptarent obsidia praeter solitum.", "st": "17.6"}, {"sp": "N", "t": "Ad quos repellendos cum valida manu missus Barbatio, in locum Silvani peditum promotus magister, ignavus sed verbis effusior, alacritate militum vehementer erecta, prostravit acerrime multos, ita ut exigua portio, quae periculi metu se dedit in fugam, aegre dilapsa, lares suos non sine lacrimis reviseret et lamentis.", "st": "17.6"}, {"sp": "N", "t": "Huic pugnae Nevitta, postea consul, equestris praepositus turmae, et adfuisse et fortiter fecisse firmatur.", "st": "17.6"}, {"sp": "N", "t": "Eisdem diebus terrae motus horrendi, per Macedoniam Asiamque et Pontum, assiduis pulsibus oppida multa concusserunt et montes. Inter monumenta tamen multiformium aerumnarum, eminuere Nicomediae clades, Bithyniae urbium matris, cuius ruinarum eventum vere breviterque absolvam.", "st": "17.7"}, {"sp": "N", "t": "Primo lucis exortu, diem nonum kal. Septembrium, concreti nubium globi nigrantium, laetam paulo ante caeli speciem confuderunt, et amendato solis splendore, nec contigua vel apposita cernebantur; ita oculorum obtutu praestricto, humo involutus crassae caliginis squalor insedit.", "st": "17.7"}, {"sp": "N", "t": "Dein velut numine summo fatales contorquente manubias, ventosque ab ipsis excitante cardinibus, magnitudo furentium incubuit procellarum, cuius impetu pulsorum auditus est montium gemitus, et elisi litoris fragor, haecque secuti typhones atque presteres, cum horrifico tremore terrarum, civitatem et suburbana funditus everterunt.", "st": "17.7"}, {"sp": "N", "t": "Et quoniam acclivitate collium aedes pleraeque vehebantur, aliae super alias concidebant, reclangentibus cunctis sonitu ruinarum immenso. Inter quae clamoribus variis celsa culmina resultabant, quaeritantium coniugium liberosque, et siquid necessitudines artae constringunt.", "st": "17.7"}, {"sp": "N", "t": "Post horam denique secundam (multo ante tertiam) aer iam sudus et liquidus latentes retexit funereas strages. Non nulli enim superruentium ruderum vi nimia constipati, sub ipsis interiere ponderibus; quidam collo tenus aggeribus obruti, cum superesse possent siqui iuvissent, auxiliorum inopia necabantur; alii lignorum exstantium acuminibus fixi pendebant.", "st": "17.7"}, {"sp": "N", "t": "Uno ictu caesi complures, paulo ante homines tunc promiscae strages cadaverum cernebantur. Quosdam domorum inclinata fastigia intrinsecus servabant intactos, angore et inedia consumendos. Inter quos Aristaenetus affectatam recens dioecensin curans vicaria potestate, quam Constantius ad honorem uxoris Eusebiae, Pietatis cognominarat, animam hoc casu cruciatam diutius exhalavit.", "st": "17.7"}, {"sp": "N", "t": "Alii subita magnitudine ruinae oppressi, eisdem adhuc molibus conteguntur. Collisis quidam capitibus, vel umeris praesectis aut cruribus, inter vitae mortisque confinia, aliorum adiumenta paria perferentium implorantes, cum obtestatione magna deserebantur.", "st": "17.7"}, {"sp": "N", "t": "Et superesse potuit aedium sacrarum et privatarum, hominumque pars maior, ni palantes abrupti flammarum ardores per quinque dies et noctes, quicquid consumi poterat exussissent.", "st": "17.7"}, {"sp": "N", "t": "Adesse tempus existimo, pauca dicere quae de terrae pulsibus coniectura veteres collegerunt. Ad ipsius enim veritatis arcana, non modo haec nostra vulgaris inscitia, sed ne sempiterna quidem lucubrationibus longis nondum exhausta, physicorum iurgia penetrarunt.", "st": "17.7"}, {"sp": "N", "t": "Unde et in ritualibus et pontificio sacerdotio obtemperantibus libris super auctore motus terrae nihil dicitur caute, ne alio deo pro alio nominato, cum qui eorum terram concutiat, sit in abstruse, piacula committantur.", "st": "17.7"}, {"sp": "N", "t": "Accidunt autem, (ut opiniones aestimant inter quas Aristoteles aestuat et laborat), aut in cavernis minutis terrarum, quas Graece σύριγγας appellamus, impulsu crebriore aquis undabundis; aut certe (ut Anaxagoras affirmat,) ventorum vi subeuntium ima terrarum; qui cum soliditatibus concrustatis inciderint, eruptiones nullas reperientes, eas partes soli convibrant, quas subrepserint tumidi. Unde plerumque observatur, terra tremente, ventorum apud nos spiramina nulla sentiri, quod in ultimis eius secessibus occupantur.", "st": "17.7"}, {"sp": "N", "t": "Anaximander ait, arescentem nimia aestuum siccitate, aut post madores imbrium terram rimas pandere grandiores, quas penetrat supernus aer violentus et nimius, ac per eas vehementi spiritu quassatam, cieri propriis sedibus. Qua de causa terrores huius modi, vaporatis temporibus, aut nimia aquarum caelestium superfusione, contingunt. Ideoque Neptunum, umentis substantiae potestatem, Ennosigaeon et Sisichthona poetae veteres et theologi nuncuparunt.", "st": "17.7"}, {"sp": "N", "t": "Fiunt autem terrarum motus modis quattuor: aut enim brasmatiae sunt, qui humum more aestus imitus suscitantes, sursum propellunt immanissimas moles, ut in Asia Delos emersit, et Hiera et Anaphe et Rhodus, Ophiusa et Pelagia, prioribus saeculis dictitata, aureo quondam imbri perfusa, et Eleusin in Boeotia, et apud Tyrrenos Vulcanus, insulaeque plures; aut climatiae qui limes ruentes atque obliqui, urbes aedificia montesque complanant; aut chasmatiae qui grandiore motu patefactis subito voratrinis, terrarum partes absorbent, ut in Atlantico mari, Europaeo orbe spatiosior insula, et in Crisaeo sinu Helice et Bura, et in Ciminia Italiae parte, oppidum Saccumum, ad Erebi profundos hiatus abactae, aeternis tenebris occultantur.", "st": "17.7"}, {"sp": "N", "t": "Inter haec tria genera terrae motuum, mycematiae sonitu audiuntur minaci, cum dissolutis elementa compagibus, ultro assiliunt, vel relabuntur considentibus terris. Tune enim necesse est velut taurinis reboare mugitibus, fragores fremitusque terrenos. Sed hinc ad exorsa.", "st": "17.7"}, {"sp": "N", "t": "At Caesar hiemem apud Parisios agens, Alamannos praevenire studio maturabat ingenti, nondum in unum coactos, sed ad insaniam post Argentoratum audaces omnes et saevos, opperiensque Iulium mensem, unde sumunt Gallicani procinctus exordia, diutius angebatur. Nec enim egredi poterat, antequam ex Aquitania aestatis remissione, solutis frigoribus et pruinis, veheretur annona.", "st": "17.8"}, {"sp": "N", "t": "Sed ut est difficultatum paene omnium diligens ratio victrix, multa mente versans et varia, id tandem repperit solum, ut anni maturitate non exspectata, barbaris occurreret insperatus, firmatoque consilio, XX dierum frumentum, ex eo quod erat in sedibus consumendum, ad usus diuturnitatem excoctum, bucellatum (ut vulgo appellant,) umeris imposuit libentium militum, hocque subsidio fretus, secundis (ut ante,) auspiciis profectus est, intra mensem quintum vel sextum, duas expeditiones consummari posse urgentes et necessarias arbitratus.", "st": "17.8"}, {"sp": "N", "t": "Quibus paratis, petit primos omnium Francos, eos videlicet quos consuetudo Salios appellavit, ausos olim in Romano solo apud Toxandriam locum habitacula sibi figere praelicenter. Cui cum Tungros venisset, occurrit legatio praedictorum, opinantium reperiri imperatorem etiam tum in hibernis, pacem sub hac lege praetendens, ut quiescentes eos tamquam in suis, nec lacesseret quisquam nec vexaret. Hos legatos negotio plene digesto, oppositaque condicionum perplexitate, ut in eisdem tractibus moraturus, dum redeunt, muneratos absolvit.", "st": "17.8"}, {"sp": "N", "t": "Dictoque citius secutus profectos, Severo duce misso per ripam, subito cunctos aggressus, tamquam fulminis turbo perculsit, iamque precantes potius quam resistentes, in opportunam clementiae partem effectu victoriae flexo, dedentes se cum opibus liberisque suscepit.", "st": "17.8"}, {"sp": "N", "t": "Chamavos itidem ausos similia adortus, eadem celeritate partim cecidit, partim acriter repugnantes, vivosque captos, compegit in vincula, alios praecipiti fuga repedantes ad sua, ne militem spatio longo defatigaret, abire interim permisit innocuos; quorum legatis paulo postea missis precatum consultumque rebus suis, humi prostratis sub obtutibus eius, pacem hoc tribuit pacto, ut ad sua redirent incolumes.", "st": "17.8"}, {"sp": "N", "t": "Cunctis igitur ex voto currentibus, studio pervigili properans, modis omnibus utilitatem fundare provinciarum, munimenta tria recta serie superciliis imposita fluminis Mosae, subversa dudum obstinatione barbarica, reparare pro tempore cogitabat, et ilico sunt instaurata, procinctu paulisper omisso.", "st": "17.9"}, {"sp": "N", "t": "Atque ut consilium prudens celeritas faceret tutum, ex annona decem dierum et septem, quam in expeditionem pergens vehebat cervicibus miles, portionem subtractam in eisdem condidit castris, sperans ex Chamavorum segetibus id suppleri posse quod ablatum est.", "st": "17.9"}, {"sp": "N", "t": "Longe autem aliter accidit. Frugibus enim nondum etiam maturis, miles, expensis quae portabat, nusquam reperiens victus, extrema minitans Iulianum compellationibus incessebat et probris, Asianum appellans Graeculum et fallacem, et specie sapientiae stolidum. Utque inveniri solent quidam inter armatos verborum volubilitate conspicui, haec et similia multa strepebant:", "st": "17.9"}, {"sp": "N", "t": "“Quo trahimur spe meliorum abolita, olim quidem dura et perpessu asperrima per nives tolerantes et acumina crudelium pruinarum? Sed nunc (pro nefas!) cum ultimis hostium fatis instamus, fame, ignavissimo mortis genere tabescentes.", "st": "17.9"}, {"sp": "N", "t": "“Et nequi nos turbarum existimet concitores, pro vita loqui sola testamur, non aurum neque argentum petentes, quae olim nec contrectare potuimus nec videre, ita nobis negata, velut contra rem publicam, tot suscepisse labores et pericula confutatis.”", "st": "17.9"}, {"sp": "N", "t": "Et erat ratio iusta querellarum. Inter tot enim rerum probabilium cursus, articulosque necessitatum ancipites, sudoribus Gallicanis miles exhaustus, nec donativum meruit nec stipendium, iam inde ut Iulianus illo est missus, ea re quod nec ipsi quod daret suppetere poterat usquam, nec Constantius erogari more solito permittebat.", "st": "17.9"}, {"sp": "N", "t": "Hocque exinde claruit fraude potius quam tenacitate committi, quod cum idem Caesar petenti ex usu gregario cuidam, ut barbas detonderet, dedisset aliquid vile, contumeliosis calumniis appetitus est a Gaudentio tunc notario, ad explorandos eius actus diu morato per Gallias, quem postea ipse interfici iusserat, ut loco monstrabitur competenti.", "st": "17.9"}, {"sp": "N", "t": "Lenito tandem tumultu, non sine blanditiarum genere vario, contextoque navali ponte transito Rheno, terris Alamannorum calcatis, Severus magister equitum, bellicosus ante haec et industrius, repente conmarcuit.", "st": "17.10"}, {"sp": "N", "t": "Et qui saepe universos ad fortiter faciendum hortabatur et singulos, tunc dissuasor pugnandi, contemptus videbatur et timidus, mortem fortasse metuens adventantem, ut in Tageticis libris legitur vel Vegonicis fulmine mox tangendos adeo hebetari, ut nec tonitruum nec maiores aliquos possint audire fragores. Et iter ignaviter egerat praeter solitum, ut ductores, viarum praeeuntes alacri gradu, ultima minitando terreret, ni omnes conspirantes in unum, se loca penitus ignorare firmarent. Qui interdicti, metuentes auctoritatem, nusquam deinde sunt progressi.", "st": "17.10"}, {"sp": "N", "t": "Inter has tamen moras, Alamannorum rex Suomarius ultro cum suis improvisus occurrit, ferox ante saeviensque in damna Romana, sed tum lucrum existimans insperatum, si propria retinere permitteretur. Et quia vultus incessusque supplicem indicabat, susceptus bonoque animo esse iussus et placido, nihil arbitrio suo relinquens, pacem genibus curvatis oravit.", "st": "17.10"}, {"sp": "N", "t": "Et eam cum concessione praeteritorum sub hac meruit lege, ut captivos redderet nostros, et quotiens sit necesse, militibus alimenta praeberet, susceptorum vilium more securitates accipiens pro illatis: quas si non ostendisset in tempore, sciret se rursus eadem flagitandum.", "st": "17.10"}, {"sp": "N", "t": "Quod ita recte dispositum est, impraepedite completo, Hortari nomine petendus erat regis alterius pagus, et quia nihil videbatur deesse praeter ductores, Nesticae tribuno scutariorum, et Chariettoni viro fortitudinis mirae, imperaverat Caesar, ut magna quaesitum industria, comprehensumque offerrent sibi captivum, et correptus velociter, adulescens ducitur Alamannus, pacto obtinendae salutis pollicitus itinera se monstraturum.", "st": "17.10"}, {"sp": "N", "t": "Hoc progresso secutus exercitus, celsarum arborum obsistente concaede, ire protinus vetabatur. Verum per circuitus longos et flexuosos ubi ventum est tandem ad loca, ira quisque percitus armorum urebat agros et peoora diripiebat et homines, resistentesque sine ulla parsimonia contruncabant.", "st": "17.10"}, {"sp": "N", "t": "His malis perculsus, rex cum multiplices legiones, vicorumque reliquias cerneret exustorum, ultimas fortunarum iacturas adesse iam contemplatus, oravit ipse quoque veniam, facturum se imperanda iurandi exsecratione promisit. Captivos restituere universos—id enim cura agebatur impensiore—iussus fidem non praestitit. Detentisque plurimis reddidit paucos.", "st": "17.10"}, {"sp": "N", "t": "Quo cognito ad indignationem iustam Iulianus erectus, cum munerandus venisset ex more, quattuor comites eius, quorum ope et fide maxime nitebatur, non ante absolvit, dum omnes rediere captivi.", "st": "17.10"}, {"sp": "N", "t": "Ad colloquium tandem accitus a Caesare, trementibus oculis adorato, victorisque superatus aspectu, condicione difficili premebatur, hac scilicet ut quoniam consentaneum erat, post tot secundos eventus, civitates quoque reparari, vi barbarorum excisas, carpenta et materias ex opibus suis suorumque praeberet; et haec pollicitus imprecatusque (si perfidum quicquam egisset,) luenda sibi cruore supplicia, ad propria remeare permissus est. Annonam enim transferre, ita ut Suomarius, ea re compelli non potuit, quod ad internicionem regione eius vastata, nihil inveniri poterat quod daretur.", "st": "17.10"}, {"sp": "N", "t": "Ita reges illi tumentes quondam immaniter, rapinisque ditescere assueti nostrorum, Romanae potentiae iugo subdidere colla iam domita, et velut inter tributarios nati et educati, obsecundabant imperiis ingravate. Quibus hoc modo peractis, disperso per stationes milite consuetas, ad hiberna regressus est Caesar.", "st": "17.10"}, {"sp": "N", "t": "Haec cum in comitatu Constantii subinde noscerentur—erat enim necesse, tamquam apparitorem, Caesarem super omnibus gestis ad Augusti referre scientiam—omnes qui plus poterant in palatio, adulandi professores iam docti, recte consulta prospereque completa vertebant in deridiculum, talia sine modo strepentes insulse: “In odium venit cum victoriis suis capella, non homo,” ut hirsutum Iulianum carpentes, appellantesque “loquacem talpam” et “purpuratam simiam” et “litterionem Graecum,” et his congruentia plurima. Atque ut tintinnabula principi resonantes, audire haec taliaque gestienti, virtutes eius obruere verbis impudentibus conabantur ut segnem incessentes et timidum et umbratilem, gestaque secus verbis comptioribus exornantem; quod non tunc primitus accidit.", "st": "17.11"}, {"sp": "N", "t": "Namque ut solet amplissima quaeque gloria obiecta esse semper invidiae, legimus in veteres quoque magnificos duces vitia criminaque, etiam si inveniri non poterant, finxisse malignitatem, spectatissimis actibus eorum offensam.", "st": "17.11"}, {"sp": "N", "t": "Ut Cimonem Miltiadis filium, insimulatum incesti, qui saepe ante et prope Eurymedonta Pamphylium flumen Persarum populum delevit innumerum, coegitque gentem insolentia semper elatam obsecrare suppliciter pacem; Aemilianum itidem Scipionem ut somniculosum aemulorum incusari malivolentia, cuius impetrabili vigilantia, obstinatae in perniciem Romae, duae potentissimae sunt urbes excisae.", "st": "17.11"}, {"sp": "N", "t": "Nec non etiam in Pompeium obtrectatores iniqui, multa scrutantes, cum nihil unde vituperari deberet, inveniretur, duo haec observarunt ludibriosa et irrita: quod genuino quodam more caput digito uno scalpebat, quodque aliquandiu tegendi ulceris causa deformis fasciola candida crus colligatum gestabat: quorum alterum factitare ut dissolutum, alterum ut novarum rerum cupidum asserebant; nihil interesse oblatrantes argumento subfrigido, quam partem corporis redimiret regiae maiestatis insigni; eum virum, quo nec fortior nec autem cautior quisquam patriae fuit, ut documenta praeclara testantur.", "st": "17.11"}, {"sp": "N", "t": "Dum haec ita aguntur, Romae Artemius curans vicariam praefecturam, pro Basso quoque agebat, qui recens promotus urbi praefectus, fatali decesserat sorte, cuius administratio seditiones perpessa est turbulentas, nec memorabile quicquam habuit quod narrari sit dignum.", "st": "17.11"}, {"sp": "N", "t": "Augusto inter haec quiescenti per hiemem apud Sirmium, indicabant nuntii graves et crebri, permixtos Sarmatas et Quados, vicinitate et similitudine morum armaturaeque concordes, Pannonias Moesiarumque alteram cuneis incursare dispersis.", "st": "17.12"}, {"sp": "N", "t": "Quibus ad latrocinia magis quam aperto habilibus Marti, hastae sunt longiores et loricae ex cornibus rasis et laevigatis, plumarum specie linteis indumentis innexae; equorumque plurimi ex usu castrati, ne aut feminarum visu exagitati, raptentur, aut in subsidiis ferocientes, prodant hinnitu densiore vectores.", "st": "17.12"}, {"sp": "N", "t": "Et per spatia discurrunt amplissima, sequentes alios vel ipsi terga vertentes, insidendo velocibus equis et morigeris, trahentesque singulos, interdum et binos, uti permutatio vires foveat iumentorum, vigorque otio integretur alterno.", "st": "17.12"}, {"sp": "N", "t": "Aequinoctio itaque temporis verni confecto, imperator coacta militum valida manu, ductu laetioris fortunae profectus, cum ad locum aptissimum pervenisset, flumen Histrum exundantem pruinarum iam resoluta congerie, super navium foros ponte contexto transgressus, populandis barbarorum incubuit terris. Qui itinere festinato praeventi, catervasque bellatoris exercitus iugulis suis imminere cernentes, quem nondum per anni tempus colligi posse rebantur, nec spirare ausi nec stare, sed vitantes exitium insperatum, semet omnes effuderunt in fugam.", "st": "17.12"}, {"sp": "N", "t": "Stratisque plurimis, quorum gressus vinxerat timor, si quos exemit celeritas morti, inter latebrosas convalles montium occultati, videbant patriam ferro pereuntem, quam vindicassent profecto, si vigore quo discesserant restitissent.", "st": "17.12"}, {"sp": "N", "t": "Gerebantur haec in ea parte Sarmatiae, quae secundam prospectat Pannoniam, parique fortitudine circa Valeriam opes barbaras urendo rapiendoque occurrentia militaris turbo vastabat.", "st": "17.12"}, {"sp": "N", "t": "Cuius cladis immensitate permoti, posthabito latendi consilio, Sarmatae petendae specie pacis, agmine tripertito agentes, securius nostros aggredi cogitarunt ut nec expedire tela nec vim vulnerum declinare, nec quod est in rebus artissimis ultimum, verti possent in fugam.", "st": "17.12"}, {"sp": "N", "t": "Aderant autem ilico Sarmatis periculorum Quadi participes, qui noxarum saepe socii fuerant indiscreti, sed ne eos quidem prompta iuvit audacia, in discrimina ruentes aperta.", "st": "17.12"}, {"sp": "N", "t": "Caesis enim compluribus, pars quae potuit superesse, per notos calles evasit; quo eventu vires et animos incitante, iunctis densius cuneis, ad Quadorum regna properabat exercitus, qui ex praeterito casu impendentia formidantes, rogaturi suppliciter pacem, fidentes ad principis venere conspectum, erga haec et similia lenioris, dictoque die statuendis condicionibus pari modo Zizais quoque etiam tum regalis, ardui corporis iuvenis, ordines Sarmatarum more certaminis instruxit ad preces; visoque imperatore, abiectis armis pectore toto procubuit, exanimis stratus. Et amisso vocis officio prae timore, tum cum orare deberet, maiorem misericordiam movit, conatus aliquotiens, parumque impediente singultu, permissus explicare quae poscebat.", "st": "17.12"}, {"sp": "N", "t": "Recreatus denique tandem, iussusque exsurgere, genibus nixus, usu linguae recuperate, concessionem delictorum sibi tribui supplicavit et veniam, eoque ad precandum admissa multitudo, cuius ora formido muta claudebat, periculo adhuc praestantioris ambiguo, ubi ille solo iussus attolli orandi signum exspectantibus diu monstravit, omnes clipeis telisque proiectis, manus precibus dederunt plura excogitantes, ut vincerent humilitate supplicandi regalem.", "st": "17.12"}, {"sp": "N", "t": "Duxerat potior cum ceteris Sarmatis etiam Rumonem et Zinafrum et Fragiledum subregulos, plurimosque optimates, cum impetrandi spe similia petituros. Qui, licet elati gaudio salutis indultae, condicionum sarcina compensare inimice facta pollicebantur, seque cum facultatibus et liberis et coniugibus terrarumque suarum ambitu Romanae potentiae libenter offerrent. Praevaluit tamen aequitati iuncta benignitas, iussique obtinere sedes impavidi, nostros reddidere captivos. Duxeruntque obsides postulatos, et obedire praeceptis deinde promptissime spoponderunt.", "st": "17.12"}, {"sp": "N", "t": "Hortante hoc exemplo clementiae, advolarunt regalis cum suis omnibus Araharius, et Usafer inter optimates excellens, agminum gentilium duces, quorum alter Transiugitanorum Quadorumque parti, alter quibusdam Sarmatis praeerat, locorum confiniis et feritate iunctissimis; quorum plebem veritus imperator, ne ferire foedera simulans, in arma repente consurgeret, discreto consortio, pro Sarmatis obsecrantes iussit paulisper abscedere, dum Araharii et Quadorum negotium spectaretur.", "st": "17.12"}, {"sp": "N", "t": "Qui cum reorum ritu oblati, stantes curvatis corporibus, facinora gravia purgare non possent, ultimae sortis infortunia metuentes, dederunt obsides imperatos, numquam antea pignora foederis exhibere compulsi.", "st": "17.12"}, {"sp": "N", "t": "His ex aequo bonoque compositis Usafer in preces admissus est, Arahario pertinaciter obstrepente, firmanteque pacem quam ipse meruit, ei quoque debere proficere, ut participi licet inferiori, et obtemperare suis imperiis consueto.", "st": "17.12"}, {"sp": "N", "t": "Verum quaestione discussa, aliena potestate eripi Sarmatae iussi (ut semper Romanorum clientes,) offerre obsides quietis vincula conservandae, gratanter amplexi sunt.", "st": "17.12"}, {"sp": "N", "t": "Ingerebat autem se post haec maximus numerus catervarum confluentium nationum et regum, suspendi a iugulis suis gladios obsecrantium, postquam Araharium impune compererat abscessisse; et pari modo ipsi quoque adepti pacem quam poscebant, accitos ex intimis regni procerum filios obsidatus sorte opinione celerius obtulerunt, itidemque captivos (ut placuerat) nostros, quos haut minore gemitu perdidere quam suos.", "st": "17.12"}, {"sp": "N", "t": "Quibus ordinatis translata est in Sarmatas cura, miseratione dignos potius quam simultate. Quibus incredibile quantum prosperitatis haec attulit causa: ut verum illud aestimaretur, quod opinantur quidam, fatum vinci principis potestate vel fieri.", "st": "17.12"}, {"sp": "N", "t": "Potentes olim ac nobiles erant huius indigenae regni, sed coniuratio clandestina servos armavit in facinus. Atque ut barbaris esse omne ius in viribus adsuevit, vicerunt dominos ferocia pares, et numero praeminentes.", "st": "17.12"}, {"sp": "N", "t": "Qui confundente metu consilia, ad Victohalos discretos longius confugerunt, obsequi defensoribus, (ut in malis) optabile, quam servire mancipiis arbitrati; quae deplorantes, post impetratam veniam recepti in fidem, poscebant praesidia libertati, eosque iniquitate rei permotus, inspectante omni exercitu, convocatos allocutus verbis mollioribus imperator, nulli nisi sibi ducibusque Romanis parere praecepit.", "st": "17.12"}, {"sp": "N", "t": "Atque ut restitutio libertatis haberet dignitatis augmentum, Zizaim regem eisdem praefecit, conspicuae fortunae tum insignibus aptum profecto, (ut res docuit) et fidelem, nec discedere quisquam post haec gloriose gesta permissus est, antequam (ut placuerat) remearent nostri captivi.", "st": "17.12"}, {"sp": "N", "t": "His in barbarico gestis, Bregetionem castra commota sunt, ut etiam ibi belli Quadorum reliquias, circa illos agitantium tractus, lacrimae vel sanguis extingueret. Quorum regalis Vitrodorus, Viduari filius regis, et Agilimundus subregulus, aliique optimates et iudices, variis populis praesidentes, viso exercitu in gremio regni solique genitalis, sub gressibus militum iacuere, et adepti veniam iussa fecerunt, sobolemque suam obsidatus pignore (ut obsecuturi condicionibus impositis) tradiderunt, eductisque mucronibus, quos pro numinibus colunt, iuravere se permansuros in fide.", "st": "17.12"}, {"sp": "N", "t": "His (ut narratum est) secundo finitis eventu, ad Limigantes, Sarmatas servos, ocius signa transferri utilitas publica flagitabat, quos erat admodum nefas, impune multa et nefaria perpetrasse. Nam velut obliti priorum, tunc erumpentibus Liberis, ipsi quoque tempus aptissimum nancti, limitem perrupere Romanum, ad hanc solam fraudem dominis suis hostibusque concordes.", "st": "17.13"}, {"sp": "N", "t": "Deliberatum est tamen, id quoque lenius vindicari, quam criminum magnitudo poscebat, hactenus ultione porrecta, ut ad longinqua translati, amitterent copiam nostra vexandi, quos pericula formidare monebat scelerum conscientia diutius commissorum.", "st": "17.13"}, {"sp": "N", "t": "Ideoque in se pugnae molem suspicati vertendam, dolos parabant et ferrum et preces. Verum aspectu primo exercitus tamquam fulminis ictu perculsi, ultimaque cogitantes, vitam precati, tributum annuum delectumque validae iuventutis et servitium spoponderunt, abnuere parati si iuberentur aliorsum migrare, ut gestibus indicabant et vultibus, locorum confisi praesidio, ubi lares post exactos dominos fixere securi.", "st": "17.13"}, {"sp": "N", "t": "Has enim terras Parthiscus irruens obliquatis meatibus, Histro miscetur. Sed dum solus licentius fluit, spatia longa et lata sensim praelabens, et ea coartans prope exitum in angustias, accolas ab impetu Romanorum alveo Danubii defendit, a barbaricis vero excursibus suo tutos praestat obstaculo, ubi pleraque umidioris soli natura, et incrementis fluminum redundantia, stagnosa sunt et referta salicibus, ideoque invia, nisi perquam gnaris; et super his insularem anfractum, aditu Parthisci paene contiguum, amnis potior ambiens, terrae consortio separavit.", "st": "17.13"}, {"sp": "N", "t": "Hortante igitur principe, cum genuino fastu ad citeriorem venere fluminis ripam, ut exitus docuit, non iussa facturi, sed ne viderentur militis praesentiam formidasse, stabantque contumaciter, ideoque propinquasse monstrantes, ut iubenda repudiarent.", "st": "17.13"}, {"sp": "N", "t": "Quae imperator accidere posse contemplans, in agmina plurima clam distributo exercitu, celeritate volucri morantes intra suorum acies clausit. Stansque in aggere celsiore cum paucis, et stipatorum praesidio tectus, eos ne ferocirent lenius admonebat.", "st": "17.13"}, {"sp": "N", "t": "Sed fluctuantes ambiguitate mentium in diversa rapiebantur, et furori mixta versutia, temptabant cum precibus proelium, vicinumque sibi in nostros parantes excursum, proiecere consulto longius scuta, ut ad ea recuperanda sensim progressi, sine ullo fraudis indicio spatia furarentur.", "st": "17.13"}, {"sp": "N", "t": "Iamque vergente in vesperum die, cum moras rumpere lux moneret excedens, erectis vexillis in eos igneo miles impetu ferebatur. Qui conferti acieque densiore contracta, adversus ipsum principem stantem (ut dictum est) altius, omnem impetum contulerunt, eum oculis incessentes et vocibus truculentis.", "st": "17.13"}, {"sp": "N", "t": "Cuius furoris amentiam exercitus ira ferre non potuit, eosque imperatori (ut dictum est) acriter imminentes, desinente in angustum fronte (quem habitum caput porci simplicitas militaris appellat,) impetu disiecit ardenti, et dextra pedites catervas peditum obtruncabant, equites laeva equitum se turmis agilibus infuderunt.", "st": "17.13"}, {"sp": "N", "t": "Cohors praetoria ex adverso Augustum cautius stipans, resistentium pectora moxque terga fugientium incidebat, et cadentes insuperabili contumacia barbari non tam mortem dolere, quam nostrorum laetitiam, horrendo stridore monstrabant, et iacentes absque mortuis plurimi, succisis poplitibus ideoque adempto fugiendi subsidio, alii dexteris amputatis, non nulli ferro quidem intacti, sed superruentium collisi ponderibus, cruciatus alto silentio perferebant.", "st": "17.13"}, {"sp": "N", "t": "Nec eorum quisquam inter diversa supplicia veniam petit aut ferrum proiecit, aut exoravit celerem mortem, sed arma iugiter retinentes, licet afflicti, minus criminis aestimabant, alienis viribus potius quam conscientiae suae iudicio vinci; mussantesque audiebantur interdum, fortunae non meriti fuisse quod evenit. Ita in semihorae curriculo discrimine proeliorum emenso, tot procubuere subito barbari, ut pugnam fuisse sola victoria declararet.", "st": "17.13"}, {"sp": "N", "t": "Vix dum populis hostilibus stratis, gregatim peremptorum necessitudines ducebantur, humilibus extractae tuguriis, aetatis sexusque promiscui, et fastu vitae prioris abolito, ad infimitatem obsequiorum venere servilium, et exiguo temporis intervallo decurso, caesorum aggeres et captivorum agmina cernebantur.", "st": "17.13"}, {"sp": "N", "t": "Incitante itaque fervore certaminum, fructuque vincendi, consurrectum est in perniciem eorum qui deseruerant proelia, vel in tuguriis latitantes occultabantur. Hos, cum ad loca venisset avidus barbarici sanguinis miles, disiectis culmis levibus obtruncabant, nec quemquam casa, vel trabibus compacta firmissimis, periculo mortis extraxit.", "st": "17.13"}, {"sp": "N", "t": "Denique cum inflammarentur omnia nullusque latere iam posset, cunctis vitae praesidiis circumcisis, aut obstinate igni peribat absumptus, aut incendium vitans, egressusque uno supplicio declinato, ferro sternebatur hostili.", "st": "17.13"}, {"sp": "N", "t": "Fugientes tamen aliqui tela, incendiorumque magnitudinem, amnis vicini se commisere gurgitibus, peritia nandi ripas ulteriores occupare posse sperantes, quorum plerique summersi necati sunt, alii iaculis periere confixi, adeo ut abunde cruore diffuso, meatus fluminis spumaret immensi; ita per elementum utrumque, Sarmatas vincentium ira virtusque delevit.", "st": "17.13"}, {"sp": "N", "t": "Placuerat igitur post hunc rerum ordinem cunctis adimi spem omnem vitaeque solacium. Et post lares incensos, raptasque familias, navigia iussa sunt colligi, ad indagandos eos quos a nostrorum acie ulterior discreverat ripa.", "st": "17.13"}, {"sp": "N", "t": "Statimque ne alacritas intepesceret pugnatorum, impositi lintribus, per abdita ducti, velites expediti occuparunt latibula Sarmatarum, quos repentinus fefellit aspectus, gentiles lembos et nota remigia conspicantes.", "st": "17.13"}, {"sp": "N", "t": "Ubi vero procul micantibus telis, quod verebantur, propinquare senserunt, ad suffugia locorum palustrium se contulerunt, eosque secutus infestius miles, caesis plurimis ibi victoriam repperit, ubi nec caute posse consistere, nec audere aliquid credebatur.", "st": "17.13"}, {"sp": "N", "t": "Post absumptos paene diffusosque Amicenses, petiti sunt sine mora Picenses, ita ex regionibus appellati conterminis; quos tutiores fecere sociorum aerumnae, rumorum assiduitate compertae. Ad quos opprimendos, (erat enim arduum sequi per diversa conspersos, imprudentia viarum arcente,) Taifalorum auxilium et Liberorum adaeque Sarmatarum assumptum est.", "st": "17.13"}, {"sp": "N", "t": "Cumque auxiliorum agmina locorum ratio separaret, tractus contiguos Moesiae sibi miles elegit, Taifali proxima suis sedibus obtinebant, Liberi terras occupaverant e regione sibi oppositas.", "st": "17.13"}, {"sp": "N", "t": "Quae perpessi Limigantes territique subactorum exemplis et subitum prostratorum, diu haesitabant ambiguis mentibus, utrum oppeterent an rogarent, cum utriusque rei suppeterent documenta non levia. Vicit tamen ad ultimum coetu seniorum urgente, dedendi sese consilium. Variaeque palmae victoriarum accessit eorum quoque supplicatio, qui armis libertatem invaserant, et reliqui eorum cum precibus, ut superatos et imbelles dominos aspernati, fortioribus visis inclinavere cervices.", "st": "17.13"}, {"sp": "N", "t": "Accepta itaque publica fide, deserto montium propugnaculo, ad castra Romana convolavit eorum pars maior, diffusa per spatia ampla camporum, cum parentibus et natis atque coniugibus, opumque vilitate, quam eis celeritatis ratio furari permisit.", "st": "17.13"}, {"sp": "N", "t": "Et qui animas amittere potius, quam cogi solum vertere putabantur, dum licentem amentiam libertatem existimarent, parere imperiis, et sedes alias suscipere sunt assensi, tranquillas et fidas, ut nec bellis vexari, nec mutari seditionibus possint. Eisdemque ex sententia (ut credebatur,) acceptis, quievere paulisper, post feritate nativa in exitiale scelus erecti, ut congruo docebitur textu.", "st": "17.13"}, {"sp": "N", "t": "Hoc rerum prospero currente successu, tutela Illyrico competens gemina est ratione firmata, cuius negotii duplicem magnitudinem imperator aggressus utramque perfecit. Infidis attritis stratisque, exsules populos (licet mobilitate suppares) acturos tamen paulo verecundius, tandem reductos in avitis sedibus collocavit. Eisdemque ad gratiae cumulum, non ignobilem quempiam regem, sed quem ipsi antea sibi praefecere regalem, imposuit, bonis animi corporisque praestantem.", "st": "17.13"}, {"sp": "N", "t": "Tali textu recte factorum, Constantius iam metuente sublimior, militarique consensu, secundo Sarmaticus appellatus, ex vocabulo subactorum, iamque discessurus, convocatis cohortibus, et centuriis, et manipulis omnibus, tribunal insistens, signisque ambitus et aquilis, et agmine multiplicium potestatum, his exercitum allocutus est, ore omnium favorabilis, (ut solebat).", "st": "17.13"}, {"sp": "N", "t": "“Hortatur recordatio rerum gloriose gestarum, omni iucunditate viris fortibus gratior, ea ad modum verecundiae replicare, quae divinitus delata sorte vincendi, et ante proelia et in ipso correximus fervore pugnarum, Romanae rei fidissimi defensores. Quid enim tam pulchrum tamque posteritatis memoriae iusta ratione mandandum, quam ut miles strenue factis, ductor prudenter consultis exultet?", "st": "17.13"}, {"sp": "N", "t": "“Persultabat Illyricum furor hostilis, absentiam nostram inanitate tumenti despiciens, dum Italos tueremur et Gallos, variisque discursibus vastabat extima limitum, nunc cavatis roboribus, aliquotiens peragrans pedibus flumina, non congressibus nec armis fretus aut viribus, sed latrociniis assuetus occultis, astu et ludificandi varietate, iam inde ab instituta gente nostris quoque maioribus formidatus; quae longius disparati, qua ferri poterant tulimus, saeviores iacturas efficacia ducum vitari posse sperantes.", "st": "17.13"}, {"sp": "N", "t": "“Ubi vero per licentiam scandens in maius, ad funestas provinciarum clades erepsit et crebras, communitis aditibus Raeticis, tutelaque pervigili Galliarum securitate fundata, terrore nullo relicto post terga, venimus in Pannonias, si placuerit numini sempiterno, labentia firmaturi; cunctisque paratis (ut nostis,) vere adulto egressi, arripuimus negotiorum maximas moles: primum ne struendo textis compagibus ponti, telorum officeret multitudo, quo opera levi perfecto, visis terris hostilibus et calcatis, obstinatis ad mortem animis conatos resistere Sarmatas, absque nostrorum dispendio stravimus, parique petulantia ruentes in agmina nobilium legionum, Quados Sarmatis adiumenta ferentes attrivimus. Qui post aerumnosa dispendia, inter discursus et repugnandi minaces anhelitus, quid nostra valeat virtus experti, manus ad dimicandum aptatas, armorum abiecto munimine, pone terga vinxerunt, restareque solam salutem contemplantes in precibus, affusi sunt vestigiis Augusti clementis, cuius proelia saepe compererant exitus habuisse felices.", "st": "17.13"}, {"sp": "N", "t": "“His sequestratis Limigantes quoque fortitudine superavimus pari, interfectisque pluribus, alios periculi declinatio adegit suffugia petere latebrarum palustrium.", "st": "17.13"}, {"sp": "N", "t": "“Hisque secundo finitis eventu, lenitatis tempus aderat tempestivae. Limigantes ad loca migrare compulimus longe discreta, ne in perniciem nostrorum se commovere possent ulterius et pepercimus plurimis, et Zizaim praefecimus Liberis, dicatum nobis futurum et fidum, plus aestimantes creare quam auferre barbaris regem, hoc decore augente sollemnitatem, quod eisdem quoque rector tributus antehac electus est et acceptus.", "st": "17.13"}, {"sp": "N", "t": "“Quadruplex igitur praemium, quod unus procinctus absolvit, nos quaesivimus et res publica, primo ultione parta de grassatoribus noxiis, deinde quod vobis abunde sufficient ex hostibus capta. His enim virtutem oportet esse contentam, quae sudore quaesivit et dexteris.", "st": "17.13"}, {"sp": "N", "t": "“Nobis amplae facultates opumque sunt magni thesauri, si integra omnium patrimonia nostri labores et fortitudo servarint. Hoc enim boni principis menti, hoc successibus congruit prosperis.", "st": "17.13"}, {"sp": "N", "t": "“Postremo ego quoque hostilis vocabuli spolium prae me fero, secundo Sarmatici cognomentum, quod vos unum idemque sentientes, mihi (ne sit arrogans dicere,) merito tribuistis.”", "st": "17.13"}, {"sp": "N", "t": "Post hunc dicendi finem contio omnis alacrior solito, aucta spe potiorum et lucris, vocibus festis in laudes imperatoris adsurgens, deumque ex usu testata non posse Constantium vinci, tentoria repetit laeta. Et reductus imperator ad regiam, otioque bidui recreatus, Sirmium cum pompa triumphali regressus est, et militares numeri destinatas remearunt ad sedes.", "st": "17.13"}, {"sp": "N", "t": "Hisce eisdem diebus, Prosper et Spectatus atque Eustathius, legati ad Persas (ut supra docuimus) missi, Ctesiphonta reversum regem adiere, litteras perferentes imperatoris et munera, poscebantque rebus integris pacem, et mandatorum principis memores, nusquam ab utilitate Romanae rei maiestateque discedebant, amicitiae foedus sub hac lege firmari debere adseverantes, ne super turbando Armeniae vel Mesopotamiae statu quicquam moveretur.", "st": "17.14"}, {"sp": "N", "t": "Diu igitur ibi morati, cum obstinatissimum regem, nisi harum regionum dominio sibi adiudicato, obdurescentem ad suscipiendam cernerent pacem, negotio redierunt infecto.", "st": "17.14"}, {"sp": "N", "t": "Post quod id ipsum condicionum robore pari impetraturi, Lucillianus missus est comes, et Procopius tunc notarius, qui postea nodo quodam violentae necessitatis adstrictus, ad res consurrexerat novas.", "st": "17.14"}, {"sp": "HDR", "t": "Liber XVIII", "st": "18"}, {"sp": "N", "t": "Haec per orbis varias partes uno eodemque anno sunt gesta. At in Galliis cum in meliore statu res essent, et Eusebium atque Hypatium fratres sublimarent vocabula consulum, Iulianus contextis successibus clarus, apud Parisios hibernans, sequestratis interim sollicitudinibus bellicis, haut minore cura provinciarum fortunis multa conducentia disponebat, diligenter observans nequem tributorum sarcina praegravaret, neve potentia praesumeret aliena, aut hi versarentur in medio, quorum patrimonia publicae clades augebant, vel iudicum quisquam ab aequitate deviaret impune.", "st": "18.1"}, {"sp": "N", "t": "Idque ea re levi labore correxit, quod ipse iurgia dirimens, ubi causarum cogebat magnitude vel personarum, erat indeclinabilis iustorum iniustorumque distinctor.", "st": "18.1"}, {"sp": "N", "t": "Et licet multa sint eius laudanda in huius modi controversiis, unum tamen sufficiet poni, ad cuius similitudinem acta vel dicta sunt.", "st": "18.1"}, {"sp": "N", "t": "Numerium Narbonensis paulo ante rectorem, accusatum ut furem, inusitato censorio vigore, pro tribunali palam admissis volentibus audiebat, qui cum infitiatione defenderet obiecta, nec posset in quoquam confutari, Delphidius orator acerrimus, vehementer eum impugnans, documentorum inopia percitus, exclamavit: “Ecquis, florentissime Caesar, nocens esse poterit usquam, si negare sufficiet?” Contra quem Iulianus prudenter motus ex tempore, “Ecquis” ait “innocens esse poterit, si accusasse sufficiet?” Et haec quidem et huius modi multa civilia.", "st": "18.1"}, {"sp": "N", "t": "Egressurus autem ad procinctum urgentem, cum Alamannorum pagos aliquos esse reputaret hostiles, et ausuros immania, ni ipsi quoque ad ceterorum sternerentur exempla, haerebat anxius qua vi qua celeritate, cum primum ratio copiam tribuisset, rumore praecurso, terras eorum invaderet repentinus.", "st": "18.2"}, {"sp": "N", "t": "Seditque tandem multa et varia cogitanti, id temptare quod utile probavit eventus. Hariobaudem vacantem tribunum, fidei fortitudinisque notae, nullo conscio legationis specie ad Hortarium miserat regem iam pacatum, ut exinde facile ad collimitia progressus eorum, in quos erant arma protinus commovenda, scitari possit quid molirentur, sermonis barbarici perquam gnarus.", "st": "18.2"}, {"sp": "N", "t": "Quo fidenter ad haec patranda digresso, ipse anni tempore opportuno, ad expeditionem undique milite convocato, profectus, id inter potissima mature duxit implendum, ut ante proeliorum fervorem, civitates multo ante excisas ac vacuas introiret, receptasque communiret, horrea quin etiam exstrueret pro incensis, ubi condi possit annona, a Britanniis sueta transferri.", "st": "18.2"}, {"sp": "N", "t": "Et utrumque perfectum est spe omnium citius. Nam et horrea veloci opere surrexerunt, alimentorumque in eisdem satias condita, et civitates occupatae sunt septem: Castra Herculis Quadriburgium Tricensima et Novesium, Bonna Antennacum et Vingo, ubi laeto quodam eventu, etiam Florentius praefectus apparuit subito, partem militum ducens, et commeatuum perferens copiam, sufficientem usibus longis.", "st": "18.2"}, {"sp": "N", "t": "Post haec impetrata, restabat adigente necessitatum articulo, receptarum urbium moenia reparari, nullo etiam tum interturbante; idque claris indiciis apparet, ea tempestate utilitati publicae metu barbaros oboedisse, rectoris amore Romanos.", "st": "18.2"}, {"sp": "N", "t": "Reges ex pacto superioris anni aedificiis habilia multa suis misere carpentis, et auxiliarii milites semper munia spernentes huius modi, ad obsequendi sedulitatem Iuliani blanditiis deflexi, quinquagenarias longioresque materias vexere cervicibus ingravate, et fabricandi ministeriis opem maximam contulerunt.", "st": "18.2"}, {"sp": "N", "t": "Quae dum diligenti maturantur effectu, Hariobaudes exploratis omnibus rediit, docuitque comperta. Post cuius adventum incitatis viribus omnes venere Mogontiacum, ubi Florentio et Lupicino (Severi successore) destinate certantibus, per pontem illic constitutum transiri debere, renitebatur firmissime Caesar, asserens pacatorum terras non debere calcari, ne (ut saepe contigit) per incivilitatem militis occurrentia vastitantis, abrupte foedera frangerentur.", "st": "18.2"}, {"sp": "N", "t": "Alamanni tamen omnes quos petebat exercitus, confine periculum cogitantes, Suomarium regem amicum nobis ex pactione praeterita monuerunt minaciter, ut a transitu Romanos arceret. Eius enim pagi Rheni ripis ulterioribus adhaerebant. Quo testante resistere solum non posse, in unum coacta barbara multitude venit prope Mogontiacum, prohibitura viribus magnis exercitum, ne transmitteret flumen.", "st": "18.2"}, {"sp": "N", "t": "Gemina itaque ratione visum est habile quod suaserat Caesar, ne pacatorum terrae corrumperentur, neve renitente pugnacissima plebe, pons cum multorum discrimine iungeretur iri in locum ad compaginandum pontem aptissimum.", "st": "18.2"}, {"sp": "N", "t": "Quod hostes sollertissime contemplati, per contrarias ripas leniter incedentes, ubi nostros figere tentoria, procul cernebant, ipsi quoque noctes agebant exsomnes, custodientes pervigili studio, ne transitus temptaretur.", "st": "18.2"}, {"sp": "N", "t": "Verum cum nostri locum adventarent provisum, vallo fossaque quievere circumdati, et asscito Lupicino in consilium, Caesar certis imperavit tribunis, ut trecentenos pararent cum sudibus milites expedites, quid agi quove iri deberet penitus ignorantes.", "st": "18.2"}, {"sp": "N", "t": "Et collecti nocte provecta, impositique omnes quos lusoriae naves quadraginta quae tune aderant solae, ceperunt, decurrere iubentur per flumen, adeo taciti, ut etiam remi suspenderentur, ne barbaros sonitus excitaret undarum, atque mentis agilitate et corporum, dum hostes nostrorum ignes observant, adversas perrumpere milites ripas.", "st": "18.2"}, {"sp": "N", "t": "Dum haec celerantur, Hortarius rex nobis antea foederatus, non novaturus quaedam, sed amicus finitimis quoque suis, reges omnes et regales et regulos ad convivium corrogatos retinuit, epulis ad usque vigiliam tertiam gentili more extentis; quos discedentes inde casu nostri ex improviso adorti, nec interficere nec corripere ullo genere potuerunt, tenebrarum equorumque adiumento, quo dubius impetus trusit, abreptos; lixas vero vel servos, qui eos pedibus sequebantur, (nisi quos exemit discrimine temporis obscuritas) occiderunt.", "st": "18.2"}, {"sp": "N", "t": "Cognito denique transitu Romanorum, qui tune perque expeditiones praeteritas, ibi levamen sumere laborum opinabantur, ubi hostem contingeret inveniri, perculsi reges eorumque populi, qui pontem ne strueretur, studio servabant intento, metu exhorrescentes diffuse vertuntur in pedes; et indomito furore sedato, necessitudines opesque suas transferre longius festinabant. Statimque difficultate omni depulsa, ponte constrato, sollicitarum gentium opinione praeventa, visus in barbarico miles per Hortarii regna transibat intacta.", "st": "18.2"}, {"sp": "N", "t": "Ubi vero terras infestorum etiam tum tetigit regum, urens omnia rapiensque, per medium rebellium solum grassabatur intrepidus.", "st": "18.2"}, {"sp": "N", "t": "Postque saepimenta fragilium penatium inflammata, et obtruncatam hominum multitudinem, visosque cadentes multos aliosque supplicantes, cum ventum fuisset ad regionem (cui Capillacii vel Palas nomen est) ubi terminales lapides Alamannorum et Burgundiorum confinia distinguebant, castra sant posita, ea propter ut Macrianus et Hariobaudus, germani fratres et reges, susciperentur impavidi, qui propinquare sibi perniciem sentientes, venerant pacem anxiis animis precaturi.", "st": "18.2"}, {"sp": "N", "t": "Post quos statim rex quoque Vadomarius venit, cuius erat domicilium contra Rauracos, scriptisque Constantii principis, quibus commendatus est artius, allegatis, leniter susceptus est (ut decebat), olim ab Augusto in clientelam rei Romanae susceptus.", "st": "18.2"}, {"sp": "N", "t": "Et Macrianus quidem cum fratre inter aquilas admissus et signa, stupebat armorum viriumque varium decus, visa tune primitus, proque suis orabat. Vadomarius vero nostris coalitus (utpote vicinus limiti) mirabatur quidem apparatum ambitiosi procinctus, sed vidisse se talia saepe ab adulescentia meminerat prima.", "st": "18.2"}, {"sp": "N", "t": "Libratis denique diu consiliis, concordi assensione cunctorum, Macriano quidem et Hariobaudo pax est attributa, Vadomario vero, qui suam locaturus securitatem in tuto, et legationis nomine precator venerat, pro Urio et Ursicino et Vestralpo regibus pacem itidem obsecrans, interim responderi non poterat, ne (ut sunt fluxioris fidei barbari) post abitum recreati nostrorum, parum acquiescerent per alios impetratis.", "st": "18.2"}, {"sp": "N", "t": "Sed cum ipsi quoque missis legatis, post messes incensas et habitacula, captosque plures et interfectos, ita supplicarent tamquam ipsi haec deliquissent in nostros, pacem condicionum similitudine meruerunt. Inter quas id festinatum est maxime, ut captives restituerent omnes, quos rapuerant excursibus crebris.", "st": "18.2"}, {"sp": "N", "t": "Haec dum in Galliis caelestis corrigit cura, in comitatu Augusti turbo novarum exoritur rerum, a primordiis levibus ad luctus et lamenta progressus. In domo Barbationis, pedestris militiae tunc rectoris, examen apes fecere perspicuum. Superque hoc ei prodigiorum gnaros sollicite consulenti, discrimen magnum portendi responsum est, coniectura videlicet tali, quod hae volucres post compositas sedes, opesque congestas, fumo pelluntur, et turbulento sonitu cymbalorum.", "st": "18.3"}, {"sp": "N", "t": "Huic uxor erat Assyria nomine, nec taciturna nec prudens, quae eo ad expeditionem profecto, et multiplici metu suspenso, ob ea quae meminerat sibi praedicta, perculsa vanitate muliebri, ancilla asscita notarum perita, quam e patrimonio Silvani possederat, ad maritum scripsit intempestive, velut flens obtestans ne post obitum Constanti propinquantem, in imperium ipse ut sperabat admissus, despecta se anteponeret Eusebiae matrimonium tune reginae, decore corporis inter multas feminas excellentis.", "st": "18.3"}, {"sp": "N", "t": "Quibus litteris occulte quantum fieri potuit missis, ancilla, quae domina dictante perscripserat, reversis omnibus e procinctu, exemplum ferens ad Arbetionem noctis prima quiete confugit, avideque suscepta, chartulam prodidit.", "st": "18.3"}, {"sp": "N", "t": "Hocque indicio ille confisus, ut erat ad criminandum aptissimus, principi detulit, atque ex usu, nec mora ulla negotio tributa nec quiete, Barbatio epistulam suscepisse confessus, et mulier scripsisse documento convicta non levi, cervicibus interiere praecisis.", "st": "18.3"}, {"sp": "N", "t": "Hisque punitis, quaestiones longe serpebant, vexatique multi nocentes sunt et innocentissimi. Inter quos etiam Valentinus ex primicerio protectorum tribunus, ut conscius inter complures alios tortus aliquotiens supervixit, penitus quid erat gestum ignorans. Ideoque ad iniuriae periculique compensationem, ducis in Illyrico meruit potestatem.", "st": "18.3"}, {"sp": "N", "t": "Erat autem idem Barbatio subagrestis, arrogantisque propositi, ea re multis exosus, quod et dum domesticos protectores sub Gallo regeret Caesare, proditor erat et perfidus, et post eius excessum, nobilioris militiae fastu elatus, in Iulianum itidem Caesarem paria confingebat, crebroque detestantibus bonis, sub Augusti patulis auribus multa garriebat et saeva.", "st": "18.3"}, {"sp": "N", "t": "Ignorans profecto veteris Aristotelis sapiens dictum, qui Callisthenem sectatorem et propinquum suum ad regem Alexandrum mittens, ei saepe mandabat, ut quam rarissime et iucunde apud hominem loqueretur, vitae potestatem et necis in acie linguae portantem.", "st": "18.3"}, {"sp": "N", "t": "Ne sit hoc mirum, homines profutura discernere non numquam et nocentia, quorum mentes cognatas caelestibus arbitramur, animalia ratione carentia salutem suam interdum alto tueri silentio solent, ut exemplum est hoc perquam notum.", "st": "18.3"}, {"sp": "N", "t": "Linquentes orientem anseres ob calorem, plagamque petentes occiduam, cum montem penetrare coeperint Taurum, aquilis abundantem, timentes fortissimas volucres, rostra lapillis occludunt, ne eis eliciat vel necessitas extrema clangorem, eisdemque collibus agiliore volatu transcursis, proiciunt calculos, atque ita securius pergunt.", "st": "18.3"}, {"sp": "N", "t": "Dum apud Sirmium haec diligentia quaeruntur impensa, Orientis fortuna periculorum terribiles tubas reflabat. Rex enim Persidis, ferarum gentium quas placarat adiumentis accinctus, augendique regni cupiditate supra homines flagrans, arma viresque parabat et commeatus, consilia tartareis manibus miscens, et superstitiones omnes consulens de futuris; hisque satis collectis, pervadere cuncta prima verni temperie cogitabat.", "st": "18.4"}, {"sp": "N", "t": "Et cum haec primo rumores, dein nuntii certi perferrent, omnesque suspensos adventantium calamitatum complicaret magna formido, comitatensis fabrica eandem incudem (ut dicitur) diu noctuque tundendo, ad spadonum arbitrium, imperatori suspicaci ac timido intendebat Ursicinum, velut vultus Gorgonei torvitatem, haec saepe taliaque replicans, quod interempto Silvano, quasi paenuria meliorum, ad tuendas partes eoas denuo missus, altius anhelabat.", "st": "18.4"}, {"sp": "N", "t": "Hac autem assentandi nimia foeditate, mercari complures nitebantur Eusebi favorem, cubiculi tunc praepositi, apud quem (si vere dici debeat) multa Constantius posuit, ante dicti magistri equitum salutem acriter impugnantis ratione bifaria, quod omnium solus nec opes eius augebat, ut ceteri, et domo sua non cederet Antiochiae, quam molestissime flagitabat.", "st": "18.4"}, {"sp": "N", "t": "Qui ut coluber copia virus exuberans, natorum multitudinem etiam tum aegre serpentium, excitans ad nocendum, emittebat cubicularios iam adultos, ut inter ministeria vitae secretioris, gracilitate vocis semper puerilis et blandae, apud principis aures nimium patulas, existimationem viri fortis invidia gravi pulsarent. Et brevi iussa fecerunt.", "st": "18.4"}, {"sp": "N", "t": "Horum et similium taedio iuvat veterem laudare Domitianum, qui licet patris fratrisque dissimilis, memoriam nominis sui inexpiabili detestatione perfudit, tamen receptissima inclaruit lege, qua minaciter interdixerat ne intra terminos iuris dictionis Romanae castraret quisquam puerum; quod ni contigisset, quis eorum ferret examina, quorum raritas difficile toleratur?", "st": "18.4"}, {"sp": "N", "t": "Actum est tamen cautius, ne (ut fingebat) rursus accitus idem Ursicinus, metu cuncta turbaret, sed cum fors copiam detulisset, raperetur ad mortem.", "st": "18.4"}, {"sp": "N", "t": "Haec operientibus illis, et ancipiti cogitatione districtis, nobis apud Samosatam, Commageni quondam regni clarissimam sedem, parumper morantibus, repente novi motus rumoribus densis audiuntur et certis. Quos docebit orationis progrediens textus.", "st": "18.4"}, {"sp": "N", "t": "Antoninus quidam ex mercatore opulento rationarius apparitor Mesopotamiae ducis, tunc protector exercitatus et prudens, perque omnes illas notissimus terras, aviditate quorundam nexus ingentibus damnis, cum iurgando contra potentis, se magis magisque iniustitia frangi contemplaretur, ad deferendam potioribus gratiam, qui spectabant negotium, inclinatis, ne contra acumina calcitraret, flexus in blanditias molliores, confessusque debitum per colludia in nomen fisci translatum, iamque ausurus immania, rimabatur tectius rei publicae membra totius, et utriusque linguae litteras sciens, circa ratiocinia versabatur, qui vel quarum virium milites ubi agant, vel procinctus tempore quo sint venturi describens, itidem armorum et commeatuum copiae, aliaque usui bello futura, an abunde suppetant indefessa scitatione percontans.", "st": "18.5"}, {"sp": "N", "t": "Et cum totius Orientis didicisset interna, virorum stipendiique parte maxima per Illyricum distributa, ubi distinebatur ex negotiis seriis imperator, allapsuro iam praestituto die solvendae pecuniae, quam per syngrapham debere se confiteri, vi metuque compulsus est, cum omnibus se prospiceret undique periculis opprimendum, largitionum comite ad alterius gratiam infestius perurgente, fugam ad Persas cum coniage liberis et omni vinculo caritatum, ingenti molimine conabatur.", "st": "18.5"}, {"sp": "N", "t": "Atque ut lateret stationarios milites, fundum in Iaspide (qui locus Tigridis fluentis adluitur,) pretio non magno mercatur. Hocque commento cum nullus causam veniendi ad extremas Romani limitis partes, iam possessorem cum plurimis auderet exigere, per familiares fidos peritosque nandi, occultis saepe colloquiis cum Tamsapore habitis, qui tractus omnes adversos ducis potestate tune tuebatur, et antea cognitus, misso a Persicis castris auxilio virorum pernicium, lembis impositus, cum omni penatium dulcedine, nocte concubia transfretatur ex contraria specie Zopyri illius similis Babylonii proditoris.", "st": "18.5"}, {"sp": "N", "t": "Rebus per Mesopotamiam in hunc statum deductis, Palatina cohors palinodiam in exitium concinens nostrum, invenit tandem amplam nocendi fortissimo viro, auctore et incitatore coetu spadonum, qui feri et acidi semper, carentesque necessitudinibus ceteris, divitias solas ut filiolas iucundissimas amplectuntur.", "st": "18.5"}, {"sp": "N", "t": "Stetitque sententia, ut Sabinianus cultus quidem senex et bene nummatus, sed imbellis et ignavus et ab impetranda magisterii dignitate per obscuritatem adhuc longe discretus, praeficiendus eois partibus mitteretur, Ursicinus vero curaturus pedestrem militiam, et successurus Barbationi, ad comitatum reverteretur, quo praesens rerum novarum avidus concitor, (ut iactabant,) a gravibus inimicis et metuendis incesseretur.", "st": "18.5"}, {"sp": "N", "t": "Dum haec in castris Constantii quasi per lustra aguntur et scaenam, et diribitores venundatae subito potestatis pretium per potiores diffunditant domos, Antoninus ad regis hiberna perductus, aventer suscipitur, et apicis nobilitatus auctoritate, quo honore participantur mensae regales, et meritorum apud Persas ad suadendum, ferendasque sententias in contionibus ora panduntur, non contis nec remulco (ut aiunt,) id est non flexiloquis ambagibus vel obscuris, sed velificatione plena in rem publicam ferebatur, eundemque incitans regem, ut quondam Maharbal lentitudinis Hannibalem increpans, posse eum vincere, sed victoria uti nescire, assidue praedicabat.", "st": "18.5"}, {"sp": "N", "t": "Educatus enim in medio, ut rerum omnium gnarus, auditorum nanctus vegetos sensus, et aurium delenimenta captantes, nec laudantium, sed secundum Homericos Phaeacas cum silentio admirantium, iam inde quadragesimi anni memoriam replicabat, post bellorum assiduos casus, et maxime apud Hileiam et Singaram, ubi acerrima illa nocturna concertatione pugnatum est, nostrorum copiis ingenti strage confossis, quasi dirimente quodam medio fetiali, Persas nondum Edessam nec pontes Euphratis tetigisse victores quos armipotentia fretos, successibusque magnificis, ita dilatasse decuerat regna, ut toti Asia imperarent, eo maxime tempore quo diuturnis bellorum civilium motibus, sanguis utrimque Romani roboris fundebatur.", "st": "18.5"}, {"sp": "N", "t": "His ac talibus subinde inter epulas sobrius perfuga, ubi de apparatu bellorum et seriis rebus apud eos Graiorum more veterum consultatur, regem incendebat ardentem, ut exacta hieme statim arma fretus fortunae suae magnitudine concitaret, ipse quoque in multis ac necessariis operam suam fidenter promittens.", "st": "18.5"}, {"sp": "N", "t": "Sub eisdem fere diebus, Sabinianus adepta repentina potestate sufflatus, et Ciliciae fines ingressus, decessori suo principis litteras dedit, hortantis ut ad comitatum dignitate afficiendus superiore citius properaret, eo necessitatum articulo, quo etiam si apud Thulen moraretur Ursicinus, acciri eum magnitude rerum ratione probabili flagitabat, utpote disciplinae veteris et longo usu bellandi artis Persicae scientissimum.", "st": "18.6"}, {"sp": "N", "t": "Quo rumore provinciis percitis, ordines civitatum et populi, decretis et acclamationibus densis, iniecta manu detinebant paene publicum defensorem, memores quod relictus ad sui tutelam, cum inerti et umbratili milite, nihil amiserat per decennium; simul metuentes saluti, quod tempore dubio, remoto illo advenisse hominem compererant inertissimum.", "st": "18.6"}, {"sp": "N", "t": "Credimus (neque enim dubium est) per aerios tramites Famam praepetem volitare, cuius indicio haec gesta pandente, consiliorum apud Persas summa proponebatur; et multis ultro citroque deliberatis, placuit Antonino suadente, ut Ursicino procul amoto, despectoque duce novello, posthabitis civitatum perniciosis obsidiis, perrumperetur Euphrates, ireturque prorsus, ut occupari possint provinciae, fama celeritate praeventa, omnibus ante bellis (nisi temporibus Gallieni,) intactae, paceque longissima locupletes, cuius rei prosperante deo ductorem commodissimum fore spondebat.", "st": "18.6"}, {"sp": "N", "t": "Laudato firmatoque concordi omnium voluntate consilio, conversisque universis ad ea quae erant citius congerenda, commeatus milites arma ceteraque instrumenta, quae poscebat procinctus adventans, perpetua hieme parabantur.", "st": "18.6"}, {"sp": "N", "t": "Nos interea paulisper cis Taurum morati, ex imperio ad partes Italiae festinantes, prope flumen venimus Hebrum, ex Odrysarum montibus decurrentem, ibique principis scripta suscepimus, iubentia omni causatione posthabita, reverti Mesopotamiam, sine apparitione ulla expeditionem curaturi periculosam, ad alium omni potestate translata.", "st": "18.6"}, {"sp": "N", "t": "Quod ideo per molestos formatores imperil struebatur, ut si Persae frustra habiti redissent ad sua, ducis novi virtuti facinus adsignaretur egregium; si fortuna sequior ingruisset, Ursicinus reus proditae rei publicae deferretur.", "st": "18.6"}, {"sp": "N", "t": "Agitatis itaque rationibus, diu cunctati reversique, fastidii plenum Sabinianum invenimus, hominem mediocris staturae, et parvi angustique animi, vix sine turpi metu sufficientem ad levem convivii, nedum proelii strepitum, perferendum.", "st": "18.6"}, {"sp": "N", "t": "Tamen quoniam speculatores apparatus omnes apud hostes fervere, constanti asseveratione perfugis concinentibus, affirmabant, oscitante homunculo, Nisibin propere venimus, utilia paraturi, ne dissimulantes obsidium, Persae civitati supervenirent incautae.", "st": "18.6"}, {"sp": "N", "t": "Dumque intra muros maturanda perurgerentur, fumus micantesque ignes assidue a Tigride per Castra Maurorum et Sisara et collimitia reliqua, ad usque civitatem continui perlucebant, solito crebriores, erupisse hostium vastatorias manus superato flumine permonstrantes.", "st": "18.6"}, {"sp": "N", "t": "Qua causa ne occuparentur itinera, celeri cursu praegressi, cum ad secundum lapidem venissemus, liberalis formae puerum torquatum, (ut coniectabamus) octennem, in aggeris medio vidimus heiulantem, ingenui cuiusdam filium (ut aiebat); quem mater dum imminentium hostium terrore percita fugeret, impeditior trepidando reliquerat solum. Hunc dum imperatu ducis miseratione commoti, impositum equo, prae me ferens ad civitatem reduco, circumvallato murorum ambitu praedatores latius vagabantur.", "st": "18.6"}, {"sp": "N", "t": "Et quia me obsidionales aerumnae terrebant, intra semiclausam posticam exposito puero, nostrorum agmen agilitate volucri repetebam exanimis, nec multum afuit quin caperer.", "st": "18.6"}, {"sp": "N", "t": "Nam cum Abdigildum quendam tribunum, fugientem cum calone ala sequeretur hostilis, lapsoque per fugam domino servum deprehensum, cum ego rapido ictu transirem, interrogassent, quisnam provectus sit iudex, audissentque Ursicinum paulo ante urbem ingressum, montem Izalam petere; occiso indice in unum quaesiti complures nos irrequietis cursibus sectabantur.", "st": "18.6"}, {"sp": "N", "t": "Quos cum iumenti agilitate praegressus, apud Amudin munimentum infirmum, dispersis per pabulum equis, recubantes nostros securius invenissem, porrecto extentius brachio, et summitatibus sagi contortis elatius, adesse hostes signo solito demonstrabam, eisdemque iunctus impetu communi ferebar, equo iam fatiscente.", "st": "18.6"}, {"sp": "N", "t": "Terrebat autem nos plenilunium noctis, et planities supina camporum, nulla (si occupasset artior casus,) latibula praebere sufficiens, ubi nec arbores nec frutecta nec quicquam praeter herbas humiles visebatur.", "st": "18.6"}, {"sp": "N", "t": "Excogitatum est ergo ut ardente superposita lampade, et circumligata ne rueret, iumentum solum quod eam vehebat solutum, sine rectore laevorsus ire permitteretur, cum nos ad montanos excessus dextra positos tenderemus, ut praelucere sebalem facem duci lenius gradienti, Persae credentes, eum tenerent potissimum cursum; quod ni fuisset praevisum, circumventi et capti, sub dicionem venissemus hostilem.", "st": "18.6"}, {"sp": "N", "t": "Hoc extracti periculo, cum ad nemorosum quendam locum vineis arbustisque pomiferis consitum, Meiacarire nomine venissemus, cui fontes dedere vocabulum gelidi, dilapsis accolis omnibus, solum in remoto secessu latentem invenimus militem, qui oblatus duci et locutus varia prae timore, ideoque suspectus, adigente metu qui intentabatur, pandit rerum integram fidem, docetque quod apud Parisios natus in Galliis, et equestri militans turma, vindictam quondam commissi facinoris timens, ad Persas abierat profugus, exindeque morum probitate spectata, sortita coniuge liberisque susceptis, speculatorem se missum ad nostra, saepe veros nuntios reportasse. At nunc se a Tamsapore et Nohodare optimatibus missum, qui catervas ductaverant praedatorum, ad eos redire quae didicerat perlaturum. Post haec, adiectis quae agi in parte diversa norat, occiditur.", "st": "18.6"}, {"sp": "N", "t": "Proinde curarum crescente sollicitudine, inde passibus citis Amidam pro temporis copia venimus, civitatem postea secutis cladibus inclutam. Quo reversis exploratoribus nostris, in vaginae internis notarum figuris membranam repperimus scriptam, a Procopio ad nos perferri mandatam, quem legatum ad Persas antea missum cum comite Lucilliano praedixi, haec consulto obscurius indicantem, ne captis baiulis, sensuque intellecto scriptorum, excitaretur materia funestissima.", "st": "18.6"}, {"sp": "N", "t": "“Amendatis procul Graiorum legatis, forsitan et necandis, rex ille longaevus non contentus Hellesponto, iunctis Grenici et Rhyndaci pontibus, Asiam cum numerosis populis pervasurus adveniet, suopte ingenio irritabilis et asperrimus, auctore et incensore Hadriani quondam Romani Principis successore; actum et conclamatum est, ni caverit Graecia.”", "st": "18.6"}, {"sp": "N", "t": "Qui textus significabat Persarum regem transitis fluminibus Anzaba et Tigride, Antonino hortante, dominium Orientis affectare totius. His ob perplexitatem nimiam aegerrime lectis, consilium suscipitur prudens.", "st": "18.6"}, {"sp": "N", "t": "Erat eo tempore satrapa Corduenae, quae obtemperabat potestati Persarum, Iovinianus nomine appellatus in solo Romano, adulescens nobiscum occulte sentiens ea gratia, quod obsidatus sorte in Syriis detentus, et dulcedine liberalium studiorum illectus, remeare ad nostra ardenti desiderio gestiebat.", "st": "18.6"}, {"sp": "N", "t": "Ad hunc missus ego cum centurione quodam fidissimo, exploratius noscendi gratia quae gerebantur, per avios montes angustiasque praecipites veni. Visusque et agnitus, comiterque susceptus, causam praesentiae meae uni illi confessus, adiuncto taciturno aliquo locorum perito, mittor ad praecelsas rupes exinde longe distantes, unde nisi oculorum deficeret acies, ad quinquagesimum usque lapidem, quodvis etiam minutissimum apparebat.", "st": "18.6"}, {"sp": "N", "t": "Ibi morati integrum biduum, cum sol tertius affulsisset, cernebamus terrarum omnes ambitus subiectos, quos ὁριζοντας appellamus, agminibus oppletos innumeris, et antegressum regem vestis claritudine rutilantem. Quem iuxta laevus incedebat Grumbates, Chionitarum rex nervositate quidem media rugosisque membris, sed mente quadam grandifica, multisque victoriarum insignibus nobilis; dextra rex Albanorum, pari loco atque honore sublimis; post duces varii, auctoritate et potestatibus eminentes, quos ordinum omnium multitudo sequebatur, ex vicinarum gentium roboribus lecta, ad tolerandam rerum asperitatem diuturnis casibus erudita.", "st": "18.6"}, {"sp": "N", "t": "Quo usque nobis Doriscum Thraciae oppidum, et agminatim intra consaepta exercitus, recensitos Graecia fabulosa narrabis? cum nos cauti vel (ut verius dixerim) timidi, nihil exaggeremus, praeter ea quae fidei testimonia neque incerta monstrarunt.", "st": "18.6"}, {"sp": "N", "t": "Postquam reges Nineve Adiabenae ingenti civitate transmissa, in medio pontis Anzabae hostiis caesis, extisque prosperantibus, transiere laetissimi, coniectantes nos residuam plebem omnem aegre penetrare post triduum posse, citius exinde ad satrapen reversi quievimus, hospitalibus officiis recreati.", "st": "18.7"}, {"sp": "N", "t": "Unde per loca itidem deserta et sola, magno necessitatis ducente solacio, celerius quam potuit sperari reversi, confirmavimus animos haesitantium, unum e navalibus pontem transisse reges absque ulla circumitione perdoctos.", "st": "18.7"}, {"sp": "N", "t": "Extemplo igitur equites citi mittuntur ad Cassianum, Mesopotamiae ducem, rectoremque provinciae tune Euphronium, compulsuri agrestes cum familiis et pecoribus universis ad tutiora transire, et agiliter deseri Carras, oppidum invalidis circumdatum muris; super his campos omnes incendi, ne pabulorum suppeteret copia.", "st": "18.7"}, {"sp": "N", "t": "Et imperatis sine mora completis, iniecto igni furentis elementi vis maxima, frumenta omnia cum iam stipula flaventi turgerent, herbasque pubentes ita contorruit, ut ad usque Euphraten, ab ipsis marginibus Tigridis, nihil viride cerneretur. Tune exustae sunt ferae complures, maximeque leones, per ea loca saevientes immaniter, consumi vel caecari sueti paulatim hoc modo.", "st": "18.7"}, {"sp": "N", "t": "Inter harundineta Mesopotamiae fluminum et frutecta, leones vagantur innumeri, clementia hiemis ibi mollissimae semper innocui. At ubi solis radiis exarserit tempus, in regionibus aestu ambustis, vapore sideris et magnitudine culicum agitantur, quorum examinibus per eas terras referta sunt omnia. Et quoniam oculos, quasi umida et lucentia membra, eaedem appetunt volucres, palpebrarum libramentis mordicus insidentes, idem leones, cruciati diutius, aut fluminibus mersi sorbentur, ad quae remedii causa confugiunt, aut amissis oculis, quos unguibus crebro lacerantes effodiunt, immanius efferascunt; quod ni fieret, universus oriens huius modi bestiis abundaret.", "st": "18.7"}, {"sp": "N", "t": "Dum campi cremantur (ut dictum est) tribuni cum protectoribus missi, citerioris ripae Euphratis castellis et praeacutis sudibus omnique praesidiorum genere communibant, tormenta, qua parum erat voraginosum, locis opportunis aptantes.", "st": "18.7"}, {"sp": "N", "t": "Dum haec celerantur, Sabinianus inter rapienda momenta periculorum communium lectissimus moderator belli internecivi, per Edessena sepulchra, quasi fundata cum mortuis pace, nihil formidans, more vitae remissioris fluxius agens, militari pyrrice sonantibus modulis pro histrionicis gestibus, in silentio summo delectabatur, ominoso sane et incepto et loco, cum haec et huius modi factu dictuque tristia, futuros praenuntiantia motus, vitare optimum quemque debere saeculi progressione discamus.", "st": "18.7"}, {"sp": "N", "t": "Interea reges, Nisibi pro statione vili transmissa, incendiis arida nutrimentorum varietate crescentibus, fugitantes inopiam pabuli, sub montium pedibus per valles gramineas incedebant.", "st": "18.7"}, {"sp": "N", "t": "Cumque Bebasen villam venissent, unde ad Constantinam usque oppidum, quod centesimo lapide disparatur, arescunt omnia siti perpetua, nisi quod in puteis aqua reperitur exilis, quid agerent diu cunctati, iamque suorum duritiae fiducia transituri, exploratore fido docente, cognoscunt Euphratem, nivibus tabefactis inflatum, late fusis gurgitibus evagari, ideoque vado nequaquam posse transiri.", "st": "18.7"}, {"sp": "N", "t": "Convertuntur ergo ad ea quae amplectenda fortuita daret occasio, spe concepta praeter opinionem exclusi, ac proposito pro abrupto rerum praesentium statu urgenti consilio, Antoninus dicere quid sentiat iussus, orditur, flecti iter suadens in dexterum latus, ut per longiorem circumitum, omnium rerum usu regionum feracium, et consideratione ea qua rectus pergeret hostis, adhuc intactarum, castra duo praesidiaria Barzalo et Claudias peterentur, sese ductante, ubi tenuis fluvius prope originem et angustus, nullisque adhuc aquis advenis adolescens, facile penetrari poterit ut vadosus.", "st": "18.7"}, {"sp": "N", "t": "His auditis laudatoque suasore, et iusso ducere qua norat, agmina cuncta, ab institute itinere conversa, praevium sequebantur.", "st": "18.7"}, {"sp": "N", "t": "Quo certis speculationibus cognito, nos disposuimus properare Samosatam, ut superato exinde flumine, pontiumque apud Zeugma et Capersana iuncturis abscisis, hostiles impetus (si iuvisset fors ulla,) repelleremus.", "st": "18.8"}, {"sp": "N", "t": "Sed contigit atrox et silentio omni dedecus obruendum. Namque duarum turmarum equites circiter septingenti, ad subsidium Mesopotamiae recens ex Illyrico missi, enerves et timidi, praesidium per eos tractus agentes, nocturnasque paventes insidias, ab aggeribus publicis vesperi, quando custodiri magis omnes tramites conveniret, longius discedebant.", "st": "18.8"}, {"sp": "N", "t": "Hocque observato, eos vino oppresses et somno, viginti milia fere Persarum, Tamsapore et Nohodare ductantibus, nullo prospiciente transgressa, post tumulos celsos vicinos Amidae, occultabantur armata.", "st": "18.8"}, {"sp": "N", "t": "Moxque (ut dictum est) cum abituri Samosatam luce etiam tum dubia pergeremus, ab alta quadam specula radiantium armorum splendore perstricti, hostisque adesse excitatius clamitantes, signo dato quod ad proelium solet hortari, restitimus conglobati, nec fugam capessere, cum essent iam in contuitu qui sectarentur, nec congredi cum hoste equitatu et numero praevalente, metu indubitatae mortis cautum existimantes.", "st": "18.8"}, {"sp": "N", "t": "Denique ex ultima necessitate manibus iam conserendis, cum quid agi oporteat cunctaremur, occiduntur quidam nostrorum, temere procursantes, et urgente utraque parte, Antoninus ambitiosius praegrediens agmen, ab Ursicino agnitus, et obiurgatorio sonu vocis increpitus, proditorque et nefarius appellatus, sublata tiara, quam capiti summi ferebat honoris insigne, desiluit equo, curvatisque membris, humum vultu paene contingens, salutavit patronum appellans et dominum, manus post terga conectens, quod apud Assyrios supplicis indicat formam.", "st": "18.8"}, {"sp": "N", "t": "Et “Ignosce mihi” inquit “amplissime comes, necessitate non voluntate ad haec quae novi scelesta, prolapso; egere me praecipitem iniqui flagitatores, ut nosti, quorum avaritiae ne tua quidem excelsa illa fortuna, propugnans miseriis meis, potuit refragari.” Simul haec dicens, e medio prospectu abscessit, non aversus, sed dum evanesceret, verecunde retrogradiens et pectus ostentans.", "st": "18.8"}, {"sp": "N", "t": "Quae dum in curriculo semihorae aguntur, postsignani nostri, qui tenebant editiora collis exclamant, aliam cataphractorum multitudinem equitum pone visam, celeritate quam maxima propinquare.", "st": "18.8"}, {"sp": "N", "t": "Atque ut in rebus solent afflictis, ambigentes cuinam deberet aut posset occurri, trudente pondere plebis immensae, passim qua cuique proximum videbatur, diffundimur universi, dumque se quisque expedire discrimine magno conatur, sparsim disiecti hosti concursatori miscemur.", "st": "18.8"}, {"sp": "N", "t": "Itaque spreta iam vivendi cupiditate, fortiter decernentes, ad ripas pellimur Tigridis, alte excisas. Unde quidam praecipites pulsi, implicantibus armis, haeserunt, ubi vadosus est amnis, alii lacunarum hausti vertigine, vorabantur, non nulli cum hoste congressi, vario eventu certabant, quidam cuneorum densitate perterriti, petebant proximos Tauri montis excessus.", "st": "18.8"}, {"sp": "N", "t": "Inter quos dux ipse agnitus pugnatorumque mole circumdatus, cum Aiadalthe tribuno, caloneque uno, equi celeritate ereptus, abscessit.", "st": "18.8"}, {"sp": "N", "t": "Mihi dum avius ab itinere comitum quid agerem circumspicio, Verennianus domesticus protector occurrit, femur sagitta confixus, quam dum avellere obtestante collega conarer, cinctus undique antecedentibus Persis, civitatem petebam, anhelo cursu rependo, ex eo latere quo incessebamur in arduo sitam, unoque ascensu perangusto meabilem, quem scissis collibus molinae, ad calles aptandas aedificatae, densius constringebant.", "st": "18.8"}, {"sp": "N", "t": "Hic mixti cum Persis, eodem ictu procurrentibus ad superiora nobiscum, ad usque ortum alterius solis immobiles stetimus, ita conferti, ut caesorum cadavera multitudine fulta, reperire ruendi spatium nusquam possent, utque miles ante me quidam, discriminate capite, quod in aequas partes ictus gladii fiderat validissimus, in stipitis modum undique coartatus haereret.", "st": "18.8"}, {"sp": "N", "t": "Et licet multiplicia tela, per tormentorum omnia genera, volarent e propugnaculis, hoc tamen periculo murorum nos propinquitas eximebat, tandemque per posticam civitatem ingressus, refertam inveni, confluente ex finitimis virili et muliebri secus. Nam et casu illis ipsis diebus, in suburbanis peregrina commercia, circumacto anno solita celebrari, multitude convenarum augebat agrestium.", "st": "18.8"}, {"sp": "N", "t": "Interea sonitu vario cuncta miscentur, partim amissos gementibus, aliis cum exitio sauciis, multis caritates diversas, quas prae angustiis videre non poterant, invocantibus.", "st": "18.8"}, {"sp": "N", "t": "Hanc civitatem olim perquam brevem, Caesar etiam tum Constantius, ut accolae suffugium possint habere tutissimum, eo tempore quo Antoninupolim oppidum aliud struxit, turribus circumdedit amplis et moenibus, locatoque ibi conditorio muralium tormentorum, fecit hostibus formidatam, suoque nomine voluit appellari.", "st": "18.9"}, {"sp": "N", "t": "Et a latere quidem australi, geniculato Tigridis meatu subluitur, propius emergentis; qua Euri opponitur flatibus, Mesopotamiae plana despectat; unde aquiloni obnoxia est, Nymphaeo amni vicina, verticibus Taurinis umbratur, gentes Transtigritanas dirimentibus et Armeniam; spiranti zephyro contraversa Gumathenam contingit, regionem ubere et cultu iuxta fecundam, in qua vicus est Abarne nomine, sospitalium aquarum lavacris calentibus notus. In ipso autem Amidae meditullio sub arce fons dives exundat, potabilis quidem, sed vaporatis aestibus non numquam faetens.", "st": "18.9"}, {"sp": "N", "t": "Cuius oppidi praesidio erat semper Quinta Parthica legio destinata, cum indigenarum turma non contemnenda. Sed tunc ingruentem Persarum multitudinem sex legiones, raptim percursis itineribus antegressae, muris adstitere firmissimis, Magnentiaci et Decentiaci, quos post consummatos civiles procinctus, ut fallaces et turbidos, ad Orientem venire compulit imperator, ubi nihil praeter bella timetur externa, et Tricensimani Decimanique, Fortenses et Superventores atque Praeventores, cum Aeliano iam comite, quos tirones tum etiam novellos, hortante memorato adhuc protectore, erupisse a Singara, Persasque fusos in somnum retulimus trucidasse complures.", "st": "18.9"}, {"sp": "N", "t": "Aderat comitum quoque sagittariorum pars maior, equestris videlicet turmae ita cognominatae, ubi merent omnes ingenui barbari, armorum viriumque firmitudine inter alios eminentes.", "st": "18.9"}, {"sp": "N", "t": "Haec dum primi impetus turbo conatibus agitat insperatis, rex cum populo suo gentibusque quas ductabat, a Bebase loco itinere flexo dextrorsus ut monuerat Antoninus, per Horren et Meiacarire et Charcha, ut transiturus Amidam, cum prope castella Romana venisset, quorum unum Reman, alterum Busan appellatur, perfugarum indicio didicit, multorum opes illuc translatas servari, ut in munimentis praecelsis et fidis, additumque est, ibi cum suppellectili pretiosa, inveniri feminam pulchram cum filia parvula, Craugasii Nisibeni cuiusdam uxorem, in municipali ordine genere fama potentiaque circumspecti.", "st": "18.10"}, {"sp": "N", "t": "Aviditate itaque rapiendi aliena festinans, petit impetu fidenti castella, unde subita animi consternatione defensores armorum varietate praestricti, se cunctosque prodidere, qui ad praesidia confugerunt, et digredi iussi confestim claves obtulere portarum, patefactisque aditibus, quicquid ibi congestum erat eruitur, et productae sunt attonitae metu mulieres, et infantes matribus implicati, graves aerumnas inter initia tenerioris aetatis experti.", "st": "18.10"}, {"sp": "N", "t": "Cumque rex percontando cuiusnam coniux esset, Craugasii comperisset, vim in se metuentem, prope venire permisit intrepidam, et confisam opertamque ad usque labra ipsa atro velamine, certiore iam spe mariti recipiendi, et pudoris inviolati mansuri, benignius confirmavit. Audiens enim coniugem miro eius amore flagrare, hoc praemio Nisibenam proditionem mercari se posse arbitrabatur.", "st": "18.10"}, {"sp": "N", "t": "Inventas tamen alias quoque virgines, Christiano ritu cultui divino sacratas, custodiri intactas, et religioni servire solito more, nullo vetante, praecepit, lenitudinem profecto in tempore simulans, ut omnes quos antehac diritate crudelitateque terrebat, sponte sua metu remoto venirent, exemplis recentibus docti, humanitate eum et moribus iam placidis magnitudinem temperasse fortunae.", "st": "18.10"}, {"sp": "HDR", "t": "Liber XIX", "st": "19"}, {"sp": "N", "t": "Hoc miserae nostrorum captivitatis eventu rex laetus, successusque operiens similes, egressus exinde paulatimque incedens, Amidam die tertio venit.", "st": "19.1"}, {"sp": "N", "t": "Cumque primum aurora fulgeret, universa quae videri poterant armis stellantibus coruscabant, ac ferreus equitatus campos opplevit et colles.", "st": "19.1"}, {"sp": "N", "t": "Insidens autem equo, ante alios celsior, ipse praeibat agminibus cunctis, aureum capitis arietini figmentum, interstinctum lapillis, pro diademate gestans, multiplici vertice dignitatum, et gentium diversarum comitatu sublimis. Satisque eum constabat, colloquio tenus defensores moenium temptaturum, aliorsum Antonini consilio festinantem.", "st": "19.1"}, {"sp": "N", "t": "Verum caeleste numen ut Romanae rei totius aerumnas intra unius regionis concluderet ambitum, adegerat in immensum se extollentem, credentemque quod viso statim obsessi omnes metu exanimati, supplices venirent in preces.", "st": "19.1"}, {"sp": "N", "t": "Portis obequitabat, comitante cohorte regali, qui dum se prope confidentius inserit, ut etiam vultus eius possit aperte cognosci, sagittis missilibusque ceteris, ob decora petitus insignia, corruisset, ni pulvere iaculantium adimente conspectum parte indumenti tragulae ictu discissa, editurus postea strages innumeras evasisset.", "st": "19.1"}, {"sp": "N", "t": "Hinc quasi in sacrilegos violati saeviens templi, temeratumque tot regum et gentium dominum praedicans, eruendae urbis apparatu nisibus magnis instabat, et orantibus potissimis ducibus ne profusus in iram a gloriosis descisceret coeptis, leni summatum petitione placatus, postridie quoque super deditione moneri decreverat defensores.", "st": "19.1"}, {"sp": "N", "t": "Ideoque cum prima lux advenisset, rex Chionitarum Grumbates, fidenter domino suam operam navaturus, tendebat ad moenia, cum manu promptissima stipatorum, quem ubi venientem iam telo forte contiguum contemplator peritissimus advertisset, contorta ballista, filium eius primae pubis adulescentem, lateri paterno haerentem, thorace cum pectore perforato perfodit, proceritate et decore corporis aequalibus antestantem.", "st": "19.1"}, {"sp": "N", "t": "Cuius occasu in fugam dilapsi populares eius omnes, moxque ne raperetur, ratione iusta regressi, numerosas gentes ad arma clamoribus dissonis concitarunt, quarum concursu ritu grandinis hinc inde convolantibus telis, atrox committitur pugna.", "st": "19.1"}, {"sp": "N", "t": "Et post interneciva certamina, ad usque finem diei protenta, cum iam noctis esset initium, per acervos caesorum et scaturigines sanguinis aegre defensum caligine tenebrarum extrahitur corpus, ut apud Troiam quondam super comite Thessali ducis exanimi socii Marte acerrimo conflixerunt.", "st": "19.1"}, {"sp": "N", "t": "Quo funere regia maesta, et optimatibus universis cum parente subita clade perculsis, indicto iustitio, iuvenis nobilitate commendabilis et dilectus ritu nationis propriae lugebatur. Itaque ut armari solebat elatus, in amplo quodam suggestu locatur et celso, circaque eum lectuli decem sternuntur, figmenta vehentes hominum mortuorum, ita curate pollincta, ut imagines essent corporibus similes iam sepultis, ac per dierum spatium septem, viri quidem omnes per contubernia et manipulos epulis indulgebant, saltando, et cantando tristia quaedam genera naeniarum, regium iuvenem lamentantes.", "st": "19.1"}, {"sp": "N", "t": "Feminae vero miserabili planctu, in primaevo flore succisam spem gentis solitis fletibus conclamabant, ut lacrimare cultrices Veneris saepe spectantur, in sollemnibus Adonidis sacris, quod simulacrum aliquod esse frugum adultarum religiones mysticae docent.", "st": "19.1"}, {"sp": "N", "t": "Post incensum corpus ossaque in argenteam urnam collecta, quae ad gentem humo mandanda portari statuerat pater, agitata summa consiliorum, placuerat busto urbis subversae expiare perempti iuvenis manes; nec enim Grumbates, inulta unici pignoris umbra, ire ultra patiebatur.", "st": "19.2"}, {"sp": "N", "t": "Biduoque ad otium dato, ac missis abunde qui pacis modo patentes agros pingues cultosque vastarent, quinquiens ordine multiplicato scutorum, cingitur civitas ac tertiae principio lucis, corusci globi turmarum impleverunt cuncta quae prospectus humanus potuit undique contueri, et sorte loca divisa, clementi gradu incedentes ordines occuparunt.", "st": "19.2"}, {"sp": "N", "t": "Persae omnes murorum ambitus obsidebant. Pars, quae orientem spectabat, Chionitis evenit, qua funestus nobis ceciderat adulescens, cuius manibus excidio urbis parentari debebat, Gelani meridiano lateri sunt destinati, tractum servabant septentrionis Albani, occidentali portae oppositi sunt Segestani, acerrimi omnium bellatores, cum quibus elata in arduum specie elephantorum agmina rugosis horrenda corporibus, leniter incedebant, armatis onusta, ultra omnem diritatem taetri spectaculi formidanda, ut rettulimus saepe.", "st": "19.2"}, {"sp": "N", "t": "Cernentes populos tam indimensos, ad orbis Romani incendium diu quaesitos, in nostrum conversos exitium, salutis rata desperatione, gloriosos vitae exitus deinde curabamus, iamque omnibus nobis optatos.", "st": "19.2"}, {"sp": "N", "t": "A sole itaque orto usque diei ultimum, acies immobiles stabant, ut fixae nullo variato vestigio, nec sonitu vel equorum audito hinnitu, eademque figura digressi qua venerant, cibo recreati et somno, cum superesset exiguum noctis, aeneatorum clangore ductante, urbem ut mox casuram terribili corona cinxerunt.", "st": "19.2"}, {"sp": "N", "t": "Vixque ubi Grumbates hastam infectam sanguine ritu patrio nostrique more coniecerat fetialis, armis exercitus concrepans, involat muros, confestimque lacrimabilis belli turbo crudescit, rapido turmarum processu, in procinctum alacritate omni tendentium, et contra acri intentaque occursatione nostrorum.", "st": "19.2"}, {"sp": "N", "t": "Proinde diffractis capitibus, multos hostium scorpionum iactu moles saxeae colliserunt, alii traiecti sagittis, pars confixi tragulis humum corporibus obstruebant, vulnerati alii socios fuga praecipiti repetebant.", "st": "19.2"}, {"sp": "N", "t": "Nec minores in civitate luctus aut mortes, sagittarum creberrima nube auras spissa multitudine obumbrante, tormentorumque machinis, quae direpta Singara possederant Persae, vulnera inferentibus plura.", "st": "19.2"}, {"sp": "N", "t": "Namque viribus collectis propugnatores, omissa vicissim certamina repetentes, in maximo defendendi ardore saucii perniciose cadebant, aut laniati volvendo stantes proxime subvertebant, aut certe spicula membris infixa, viventes adhuc vellendi peritos quaeritabant.", "st": "19.2"}, {"sp": "N", "t": "Ita strages stragibus implicatas, et ad extremum usque diei productas, ne vespertinae quidem hebetaverunt tenebrae, ea re quod obstinatione utrimque magna decernebatur.", "st": "19.2"}, {"sp": "N", "t": "Agitatis itaque sub onere armorum vigiliis, resultabant altrinsecus exortis clamoribus colles, nostris virtutes Constanti Caesaris extollentibus, ut domini rerum et mundi, Persis Saporem saansaan appellantibus et pirosen, quod rex regibus imperans, et bellorum victor interpretatur.", "st": "19.2"}, {"sp": "N", "t": "Ac priusquam lux quinta occiperet, signo per lituos dato, ad fervorem similium proeliorum excitae undique inaestimabiles copiae in modum alituum ferebantur, unde longe ac late prospici poterat, campis et convallibus nihil praeter arma micantia ferarum gentium demonstrantibus.", "st": "19.2"}, {"sp": "N", "t": "Moxque clamore sublato, cunctis temere prorumpentibus, telorum vis ingens volabat e muris, utque opinari dabatur, nulla frustra mittebantur inter hominum cadentia densitatem. Tot enim nos circumstantibus malis, non obtinendae causa salutis, (ut dixi) sed fortiter moriendi studio flagrabamus, et a diei principio ad usque lucem obscuram, neutrubi proelio inclinato, ferocius quam consultius pugnabatur. Exsurgebant enim terrentium paventiumque clamores, ut prae alacritate consistere sine vulnere vix quisquam possit.", "st": "19.2"}, {"sp": "N", "t": "Tandemque nox finem caedibus fecit, et satias aerumnarum indutias partibus dederat longiores. Ubi enim quiescendi nobis tempus est datum, exiguas quae supererant vires, continuus cum insomnia labor absumpsit, sanguine et pallente exspirantium facie perterrente, quibus ne suprema quidem humandi solacia tribui sinebant angustiae spatiorum, intra civitatis ambitum non nimium amplae, legionibus septem et promiscua advenarum civiumque sexus utriusque plebe, et militibus aliis paucis, ad usque numerum milium centum viginti cunctis inclusis.", "st": "19.2"}, {"sp": "N", "t": "Medebatur ergo suis quisque vulneribus pro possibilitate vel curantium copia, cum quidam graviter saucii, cruore exhausto, spiritus reluctantes efflarent, alii confossi mucronibus frustraque curati, animis in ventum solutis, proiciebantur exstincti, aliquorum foratis undique membris mederi periti vetabant, ne offensionibus cassis animae vexarentur afflictae, non nulli vellendis sagittis in ancipiti curatione graviora morte supplicia perferebant.", "st": "19.2"}, {"sp": "N", "t": "Dum apud Amidam hac partium destinatione pugnatur, Ursicinus maerens, quod ex alterius pendebat arbitrio, auctoritatis tune in regendo milite potioris, Sabinianum etiam tum sepulcris haerentem, crebro monebat, ut compositis velitaribus cunctis, per imos pedes montium occultis itineribus properarent, quo levium armorum auxilio, siqua fors iuvisset, stationibus interceptis, nocturnas hostium aggrederentur excubias, quae ingenti circumitu vallaverant muros, aut lacessitionibus crebris occuparent obsidioni fortiter adhaerentes.", "st": "19.3"}, {"sp": "N", "t": "Quibus Sabinianus renitebatur ut noxiis, palam quidem litteras imperiales praetendens, intacto ubique milite, quicquid geri potuisset impleri debere aperte iubentes, clam vero corde altissimo retinens, saepe in comitatu sibi mandatum, ut amplam omnem adipiscendae laudis decessori suo ardenti studio gloriae circumcideret, etiam ex re publica processuram.", "st": "19.3"}, {"sp": "N", "t": "Adeo vel cum exitio provinciarum festinabatur, ne bellicosus homo memorabilis alicuius facinoris auctor nuntiaretur aut socius. Ideoque his attonitus malis, exploratores ad nos saepe mittendo, licet ob custodias artas nullus facile oppidum poterat introire, et utilia agitando complura, nihil proficiens visebatur, ut leo magnitudine corporis et torvitate terribilis, inclusos intra retia catulos periculo ereptum ire non audens, unguibus ademptis et dentibus.", "st": "19.3"}, {"sp": "N", "t": "Sed in civitate, ubi sparsorum per vias cadaverum multitude humandi officia superaret, pestilentia tot malis accessit, verminantium corporum lue tabifica, vaporatis aestibus varioque plebis languore nutrita, quae genera morborum unde oriri solent breviter explicabo.", "st": "19.4"}, {"sp": "N", "t": "Nimietatem frigoris aut caloris, vel umoris vel siccitatis, pestilentias gignere philosophi et illustres medici tradiderunt. Unde accolentes loca palustria vel umecta tusses et oculares casus et similia perferunt, contra confines caloribus tepore febrium arescunt. Sed quanto ignis materies ceteris est efficacior, tanto ad perimendum celerior siccitas.", "st": "19.4"}, {"sp": "N", "t": "Hinc cum decennali bello Graecia desudaret, ne peregrinus poenas dissociati regalis matrimonii lucraretur, huius modi grassante pernicie, telis Apollinis periere complures (qui sol aestimatur).", "st": "19.4"}, {"sp": "N", "t": "Atque ut Thucydides exponit, clades illa, quae in Peloponnesiaci belli principiis Athenienses acerbo genere morbi vexavit, ab usque ferventi Aethiopiae plaga paulatim proserpens, Atticam occupavit.", "st": "19.4"}, {"sp": "N", "t": "Aliis placet auras (ut solent) aquasque vitiatas faetore cadaverum, vel similibus, salubritatis violare maximam partem, vel certe aeris permutationem subitam aegritudines parere leviores.", "st": "19.4"}, {"sp": "N", "t": "Affirmant etiam aliqui, terrarum halitu densiore crassatum aera, emittendis corporis spiraminibus resistentem, necare non nullos, qua causa animalia praeter homines cetera iugiter prona, Homero auctore, et experimentis deinceps multis, cum talis incesserit labes, ante novimus interire.", "st": "19.4"}, {"sp": "N", "t": "Et prima species luis pandemus appellatur, quae efficit in aridioribus locis agentes, caloribus crebris interpellari, secunda epidemus, quae tempore ingruens, acies hebetat luminum, et concitat periculosos umores, tertia loemodes, quae itidem temporaria est, sed volucri velocitate letabilis.", "st": "19.4"}, {"sp": "N", "t": "Hac exitiali peste quassatis, paucis intemperantia aestuum consumptis, quos multitude augebat, tandem nocte quae diem consecuta est decimum, exiguis imbribus disiecto concreto spiritu et crassato, sospitas retenta est corporum firma.", "st": "19.4"}, {"sp": "N", "t": "Verum inter haec inquies Persa vineis civitatem pluteisque circumdabat, et erigi aggeres coepti, turresque fabricabantur, frontibus ferratis excelsae, quarum fastigiis ballistae locatae sunt singulae, ut a propugnaculis propellerent defensores, levia tamen per funditores et sagittarios proelia ne puncto quidem brevi cessabant.", "st": "19.5"}, {"sp": "N", "t": "Erant nobiscum duae legiones Magnentiacae recens e Galliis ductae (ut praediximus) virorum fortium et pernicium, ad planarios conflictus aptorum, ad eas vero belli artes quibus stringebamur, non modo inhabiles, sed contra nimii turbatores, qui cum neque in machinis neque in operum constructione iuvarent, aliquotiens stolidius erumpentes, dimicantesque fidentissime minuto numero revertebant, tantum proficientes, quantum in publico (ut aiunt) incendio, aqua unius hominis manu adgesta.", "st": "19.5"}, {"sp": "N", "t": "Postremo obseratis portis praecaute vetantibusque tribunis, egredi nequeuntes, frendebant ut bestiae. Verum secutis diebus efficacia eorum eminuit (ut docebimus).", "st": "19.5"}, {"sp": "N", "t": "In summoto loco partis meridianae murorum, quae despectat fluvium Tigrim, turris fuit in sublimitatem exsurgens, sub qua hiabant rupes abscisae, ut despici sine vertigine horrenda non posset, unde cavatis fornicibus subterraneis, per radices montis scalae ad usque civitatis ducebant planitiem, quo ex amnis alveo haurirentur aquae furtim, ut in omnibus per eas regiones munimentis quae contingunt flumina vidimus, fabre politae.", "st": "19.5"}, {"sp": "N", "t": "Per has tenebras ob derupta neglectas, oppidano transfuga quodam ductante, qui ad diversam partem desciverat, septuaginta sagittarii Persae ex agmine regio arte fiduciaque praestantes, silentio summoti loci defensi, subito singuli noctis medio ad contignationem turris tertiam ascenderunt, ibique occultati, mane sago punici coloris elato, quod erat subeundae indicium pugnae, cum ex omni parte circumveniri urbem suis copiis inundantibus advertissent, exinanitis proiectisque ante pedes pharetris, clamoris ululabilis incendio tela summa peritia dispergebant. Moxque acies omnes densae petebant multo infestius quam antea civitatem.", "st": "19.5"}, {"sp": "N", "t": "Inter incertos nos et ancipites, quibus occurri deberet, instantibus supra, an multitudini transcensu scalarum iam propugnacula ipsa prensanti, dividitur opera, et translatae leviores quinque ballistae, contra turrim locantur, quae ocius lignea tela fundentes, non numquam et binos forabant, e quibus pars graviter vulnerati ruebant, alii machinarum metu stridentium praecipites acti, laniatis corporibus interibant.", "st": "19.5"}, {"sp": "N", "t": "Quibus hac celeritate confectis, relatisque ad loca sueta tormentis, paulo securius moenia omnium concursu defendebantur.", "st": "19.5"}, {"sp": "N", "t": "Et quoniam augebat iras militum scelestum facinus perfugae, quasi decurrentes in planum, ita iaculantes diversa missilia lacertis fortibus incumbebant, ut vergente in meridiem die, gentes acri repulsa disiectae, lacrimantes complurium mortes, tentoria repeterent vulnerum metu.", "st": "19.5"}, {"sp": "N", "t": "Adspiravit auram quandam salutis fortuna, innoxio die cum hostili clade emenso, cuius reliquo tempore ad quietem reficiendis corporibus dato, posterae lucis initio ex arce innumeram cernimus plebem, quae Ziata capto castello, ad hosticum ducebatur, quem in locum ut capacissimum et munitum—spatio quippe decem stadiorum ambitur —promiscua confugerat multitudo.", "st": "19.6"}, {"sp": "N", "t": "Nam etiam alia munimenta eisdem diebus rapta sunt et incensa, unde hominum milia extracta complura, servituri sequebantur, inter quos multi senecta infirmi, et mulieres iam grandaevae, cum ex variis deficerent causis, itineris longinquitate offensae, abiecta vivendi cupiditate, suris vel suffraginibus relinquebantur exsectis.", "st": "19.6"}, {"sp": "N", "t": "Has miserabiles turmas Galli milites contuentes, rationabili quidem sed intempestivo motu, conferendae cum hostibus manus copiam sibi dari poscebant, mortem tribunis vetantibus, primisque ordinibus minitantes, si deinceps prohiberent.", "st": "19.6"}, {"sp": "N", "t": "Utque dentatae in caveis bestiae, taetro paedore acerbius efferatae, evadendi spe repagulis versabilibus illiduntur, ita gladiis portas caedebant, quas supra diximus obseratas, admodum anxii, ne urbe excisa ipsi quoque sine ullo specioso facinore deleantur, aut exuta periculis, nihil egisse operae pretium pro magnanimitate Gallica memorentur, licet antea saepe egressi, structoresque aggerum confossis quibusdam impedire conati, paria pertulerunt.", "st": "19.6"}, {"sp": "N", "t": "Inopes nos consilii, et quid opponi deberet saevientibus ambigentes, id potissimum aegre eisdem assentientibus, tandem elegimus, ut quoniam ultra ferri non poterant, paulisper morati, custodias aggredi permitterentur hostiles, quae non procul erant a coniectu locatae telorum, ut eis perruptis, pergerent prorsus. Apparebat enim eos (si impetrassent) strages maximas edituros.", "st": "19.6"}, {"sp": "N", "t": "Quae dum parantur, per varia certaminum genera defensabantur acriter muri, laboribus et vigiliis, et tormentis, ad emittenda undique saxa telaque dispositis. Duo tamen aggeres celsi Persarum peditum manu, e regione et ex pugnaculo civitatis, struebantur operibus lentis, contra quos nostrorum quoque impensiore cura moles excitabantur altissimae, fastigio adversae celsitudinis aequatae, propugnatorum vel nimia pondera duraturae.", "st": "19.6"}, {"sp": "N", "t": "Inter haec Galli morarum impatientes, securibus gladiisque succincti, patefacta sunt egressi postica, observata nocte squalida et inluni, orantes caeleste praesidium, ut propitium adesset et libens. Atque ipsum spiritum reprimentes, cum prope venissent, conferti valido cursu, quibusdam stationariis interfectis, exteriores castrorum vigiles (ut in nullo tali metu) sopitos obtruncant, et supervenire ipsi regiae (si prosperior iuvisset eventus) occulte meditabantur.", "st": "19.6"}, {"sp": "N", "t": "Verum audito licet levi reptantium sonitu, gemituque caesorum, discusso somno excitatis multis et ad arma pro se quoque clamitante, steterunt milites vestigiis fixis, progredi ultra non ausi; nec enim cautum deinde videbatur, expergefactis quos petebant insidiae, in apertum properare discrimen, cum iam undique frendentium catervae Persarum in proelia venirent accensae.", "st": "19.6"}, {"sp": "N", "t": "Contra Galli corporum robore, audaciaque quoad poterant inconcussi, gladiis secantes adversos, parte suorum strata vel sagittarum undique volantium crebritate confixa, cum unum in locum totam periculi molem conversam, et concurrentium hostium agmina advertissent, nullo terga vertente, evadere festinabant, et velut repedantes sub modulis, sensim extra vallum protrusi, cum manipulos confertius invadentes sustinere non possent, tubarum perciti clangore castrensium, discedebant.", "st": "19.6"}, {"sp": "N", "t": "Et resultantibus e civitate lituis multis, portae panduntur, recepturae nostros si pervenire illuc usque valuissent, tormentorumque machinae stridebant sine iaculatione ulla telorum, ut stationibus praesidentes, post interemptos socios, quae pone agerentur ignari, urbis oppositi moenibus nudarent intuta et porta viri fortes susciperentur innoxii.", "st": "19.6"}, {"sp": "N", "t": "Hacque arte Galli portam prope confinia lucis introiere minuto, numero quidam perniciose, pars leviter vulnerati, quadringentis ea nocte desideratis, qui non Rhesum nec cubitantes pro muris Iliacis Thracas, sed Persarum regem armatorum centum milibus circumsaeptum, ni obstitisset violentior casus, in ipsis tentoriis obtruncarant.", "st": "19.6"}, {"sp": "N", "t": "Horum campiductoribus, ut fortium factorum antesignanis, post civitatis excidium, armatas statuas apud Edessam in regione celebri locari iusserat imperator, quae ad praesens servantur intactae.", "st": "19.6"}, {"sp": "N", "t": "Retectis sequenti luce funeribus, cum inter caesorum cadavera optimates invenirentur, et satrapae, clamoresque dissoni fortunam aliam alibi cum lacrimis indicabant, luctus ubique et indignatio regum audiebatur, arbitrantium per stationes muris obiectas irrupisse Romanos indutiisque ob haec tridui datis assensu communi, nos quoque spatium ad respirandum accepimus.", "st": "19.6"}, {"sp": "N", "t": "Perculsae deinde novitate rei efferataeque gentes, omissa omni cunctatione, operibus (quoniam vis minime procedebat) decernere iam censebant, et concito extremo belli ardore, omnes oppetere gloriose iam properabant, aut ruina urbis animis litasse caesorum.", "st": "19.7"}, {"sp": "N", "t": "Iamque apparatu cunctorum alacritate perfecto, exsiliente lucifero, operum variae species cum turribus ferratis admovebantur, quorum in verticibus celsis aptatae ballistae propugnatores agitantes humilius disiectabant.", "st": "19.7"}, {"sp": "N", "t": "Et albescente iam die, ferrea munimenta membrorum caelum omne subtexunt, densetaeque acies non inordinatim ut antea, sed tubarum sonitu leni ductante, nullis procursantibus incedebant, machinarum operti tegminibus, cratesque vimineas praetendentes.", "st": "19.7"}, {"sp": "N", "t": "Cumque propinquantes ad coniectum venere telorum, oppositis scutis, Persae pedites sagittas tormentis excussas e muris aegrius evitantes laxaverant aciem, nullo paene iaculi genere in vanum cadente; etiam cataphracti hebetati et cedentes animos auxere nostrorum.", "st": "19.7"}, {"sp": "N", "t": "Tamen quia hostiles ballistae ferratis impositae turribus, in humiliora ex supernis valentes, ut loco dispari ita eventu dissimili, nostra multo cruore foedabant, ingruente iam vespera, cum requiescerent partes, noctis spatium maius consumptum est, ut excogitari possit quid exitio ita atroci obiectaretur.", "st": "19.7"}, {"sp": "N", "t": "Et tandem multa versantibus nobis, sedit consilium quod tutius celeritas fecit, quattuor eisdem ballistis scorpiones opponi, qui dum translati e regione, caute (quod artis est difficillimae) collocantur, lux nobis advenit maestissima, Persarum manipulos formidatos ostentans, adiectis elephantorum agminibus, quorum stridore immanitateque corporum nihil humanae mentes terribilius cernunt.", "st": "19.7"}, {"sp": "N", "t": "Cumque omni ex latere armorum et operum beluarumque molibus urgeremur, per scorpionum ferreas fundas e propugnaculis subinde rotundi lapides iacti, dissolutis turrium coagmentis, ballistas earumque tortores ita fudere praecipites, ut quidam citra vulnerum noxas, alii obtriti magnitudine ponderum interirent, elephantis vi magna propulsis, quos flammis coniectis undique circumnexos, iam corporibus tactis, gradientesque retrosus regere magistri non poterant, postque exustis operibus, nulla quies certaminibus data.", "st": "19.7"}, {"sp": "N", "t": "Rex enim ipse Persarum, qui numquam adesse certaminibus cogitur, his turbinum infortuniis percitus, novo et nusquam antea cognito more, proeliatoris militis ritu prosiluit in confertos, et quia conspectior tegentium multitudine procul speculantibus visebatur, petitus crebritate telorum, multis stipatoribus stratis, abscessit, alternans regibilis acies, et ad extremum diei, nec mortium truci visu nec vulnerum territus, tandem tempus exiguum tribui quieti permisit.", "st": "19.7"}, {"sp": "N", "t": "Verum nocte proelia dirimente, somno per breve otium capto, nitescente iam luce, ad potiunda sperata ira et dolore exundans, nec fas ullum prae oculis habiturus, gentes in nos excitabat. Cumque crematis operibus (ut docuimus), pugna per aggeres celsos muris proximos temptaretur, ex aggestis erectis intrinsecus, quantum facere nitique poterant, nostri aequis viribus per ardua resistebant.", "st": "19.8"}, {"sp": "N", "t": "Et diu cruentum proelium stetit, nec metu mortis quisquam ex aliqua parte a studio propugnandi removebatur, eoque producta contentione, cum sors partium eventu regeretur indeclinabili, diu laborata moles illa nostrorum, velut terrae quodam tremore quassata procubuit, et tamquam itinerario aggere, vel superposito ponte, complanatum spatium, quod inter murum congestamque forinsecus struem hiabat, patefecit hostibus transitum, nullis obicibus impeditum, et pars pleraque militum deiectorum oppressa vel debilitata cessavit.", "st": "19.8"}, {"sp": "N", "t": "Concursum est tamen undique ad propulsationem periculi tam abrupti, et festinandi studio aliis impedientibus alios, audacia hostium ipso successu crescebat.", "st": "19.8"}, {"sp": "N", "t": "Accitis igitur regis imperio proeliatoribus universis, strictoque comminus ferro, cum sanguis utrubique immensis caedibus funderetur, oppilatae sunt corporibus fossae latiorque via ideo pandebatur, et concursu copiarum ardenti iam civitate oppleta, cum omnis defendendi vel fugiendi spes esset abscisa, pecorum ritu armati et imbelles sine sexus discrimine truncabantur.", "st": "19.8"}, {"sp": "N", "t": "Itaque vespera tenebrante, cum adhuc licet iniqua reluctante fortuna, multitudo nostrorum manu conserta distringeretur, in abstrusa quadam parte oppidi cum duobus aliis latens, obscurae praesidio noctis postica per quam nihil servabatur evado, et squalentum peritia locorum, comitumque adiutus celeritate, ad decimum lapidem tandem perveni.", "st": "19.8"}, {"sp": "N", "t": "In qua statione lenius recreati, cum ire protinus pergeremus, et incedendi nimietate iam superarer, ut insuetus ingenuus, offendi dirum aspectum, sed fatigato mihi lassitudine gravi levamen impendio tempestivum.", "st": "19.8"}, {"sp": "N", "t": "Fugaci equo nudo et infreni calonum quidam sedens (ne labi possit) ex more habenam qua ductabatur sinistra manu artius illigavit, moxque decussus, vinculi nodum abrumpere nequiens, per avia saltusque membratim discerptus, iumentum exhaustum cursu pondere cadaveris detinebat, cuius dorsuali comprensi servitio usus in tempore, cum eisdem sociis ad fontes sulphureos aquarum, suapte natura calentium, aegre perveni.", "st": "19.8"}, {"sp": "N", "t": "Et quia per aestum arida siti reptantes, aquam diu quaeritando, profundum bene vidimus puteum, et neque descendendi prae altitudine, nec restium aderat copia, necessitate docente postrema, indumenta lintea, quibus tegebamur, in oblongos discidimus pannulos, unde explicato fune ingenti, centonem quem sub galea unus ferebat e nostris, ultimae aptavimus summitati, qui per funem coniectus, aquasque hauriens ad peniculi modum, facile sitim qua urgebamur exstinxit.", "st": "19.8"}, {"sp": "N", "t": "Unde citi ferebamur ad flumen Euphratem, ulteriorem ripam petituri per navem, quam transfretandi causa iumenta et homines, in eo tractu diuturna consuetudo locarat.", "st": "19.8"}, {"sp": "N", "t": "Ecce autem Romanum agmen cum equestribus signis disiectum, eminus cernimus, quod persequebatur multitude Persarum, incertum unde impetu tam repentino terga viantum aggressa.", "st": "19.8"}, {"sp": "N", "t": "Quo exemplo terrigenas illos, non sinibus terrae emersos, sed exuberanti pernicitate credimus natos, qui quoniam inopini per varia visebantur, σπαρτοί vocitati, humo exsiluisse, vetustate rem fabulosius extollente, sunt aestimati.", "st": "19.8"}, {"sp": "N", "t": "Hoc malo conciti, cum omne iam esset in celeritate salutis praesidium, per dumeta et silvas montes petimus celsiores, exindeque Melitinam minoris Armeniae oppidum venimus, mox repertum ducem comitatique iam profecturum, Antiochiam revisimus insperati.", "st": "19.8"}, {"sp": "N", "t": "At Persae quia tendere iam introrsus autumno praecipiti haedorumque iniquo sidere exorto prohibebantur, captives agentes et praedas, remeare cogitabant ad sua.", "st": "19.9"}, {"sp": "N", "t": "Inter haec tamen funera direptionesque civitatis excisae, Aeliano comite et tribunis, quorum efficacia diu defensa sunt moenia, stragesque multiplicatae Persarum, patibulis sceleste suffixis, Iacobus et Caesius, numerarii apparitionis magistri equitum aliique protectores, post terga vinctis manibus ducebantur, Transtigritanis qui sollicita quaerebantur industria, nullo infimi summique discrimine, ad unum omnibus contruncatis.", "st": "19.9"}, {"sp": "N", "t": "Uxor vero Craugasii, quae retinens pudorem inviolatum, ut matrona nobilis colebatur, maerebat velut orbem alium sine marito visura, quamquam sperabat documentis praesentibus altiora.", "st": "19.9"}, {"sp": "N", "t": "In rem itaque consulens suam, et accidentia longe ante prospiciens, anxietate bifaria stringebatur, viduitatem detestans et nuptias. Ideo familiarem suum perquam fidum, regionumque Mesopotamiae gnarum, per Izalam montem, inter castella praesidiaria duo Maride et Lorne introiturum, Nisibin occulte dimisit, mandatis arcanisque vitae secretioris, maritum exorans, ut auditis quae contigerint, veniret secum beate victurus.", "st": "19.9"}, {"sp": "N", "t": "Quibus conventis, expeditus viator per saltuosos tramites et frutecta, Nisibin passibus citis ingressus, causatusque se domina nusquam visa, et forsitan interempta, data evadendi copia castris hostilibus abscessisse, et ideo ut vilis neglectus, docet Craugasium gesta; moxque accepta fide quod si tuto licuerit, sequetur coniugem libens, evasit, exoptatum mulieri nuntium ferens, quae hoc cognito per Tamsaporem ducem supplicaverat regi, ut si daretur facultas, antequam Romanis excederet finibus, in potestatem suam iuberet propitius maritum adscisci.", "st": "19.9"}, {"sp": "N", "t": "Praeter spem itaque omnium digresso advena repentino, qui postliminio reversus, statim sine ullius evanuit conscientia, perculsus suspicione dux Cassianus, praesidentesque ibi proceres alii, minitantes ultima Craugasium incessebant, non sine eius voluntate vel venisse vel abisse hominem clamitantes.", "st": "19.9"}, {"sp": "N", "t": "Qui proditoris metuens crimen, impendioque sollicitus, ne transitione perfugae uxor eius superesse doceretur et tractari piissime, per simulationem matrimonium alterius splendidae virginis affectavit. Et velut paraturus necessaria convivio nuptiali, egressus ad villa octavo lapide ab urbe distantem, concito equo ad Persarum vastatorium globum, quem didicerat adventare, confugit, susceptusque aventer, qui esset ex his cognitus quae loquebatur, Tamsapori post diem traditur quintum, perque eum regi oblatus, opibus et necessitudine omni recuperata cum coniuge, quam paucos post menses amiserat, erat secundi loci post Antoninum, ut ait poeta praeclarus “longo proximus intervallo.”", "st": "19.9"}, {"sp": "N", "t": "Ille enim ingenio et usu rerum diuturno firmatus, consiliis validis sufficiebat in cuncta quae conabatur, hic natura simplicior, nominis tamen itidem pervulgati. Et haec quidem haut diu postea contigerunt.", "st": "19.9"}, {"sp": "N", "t": "Rex vero licet securitatem praeferens vultu, exultansque specie tenus urbis excidio videbatur, profundo tamen animi graviter aestuabat, reputans in obsidionalibus malis saepe luctuosas se pertulisse iacturas multoque ampliores se ipsum populos perdidisse, quam e nostris ceperat vivos, vel certe per diversas fuderat pugnas, ut apud Nisibin aliquotiens evenit, et Singaram, parique modo cum septuaginta tresque dies Amidam multitudine circumsedisset armorum, triginta milia perdidit bellatorum, quae paulo postea per Discenen tribunum et notarium numerata sunt, hac discretione facilius, quod nostrorum cadavera mox caesorum fatiscunt ac diffluunt, adeo ut nullius mortui facies post quatriduum agnoscatur, interfectorum vero Persarum inarescunt in modum stipitum corpora, ut nec liquentibus membris, nec sanie perfusa, madescant, quod vita parcior facit, et ubi nascuntur exustae caloribus terrae.", "st": "19.9"}, {"sp": "N", "t": "Dum haec per varies turbines in Orientis extimo festinantur, difficultatem adventantis inopiae frumentorum urbs verebatur aeterna, vique minacissimae plebis, famem ultimum malorum omnium exspectantis, subinde Tertullus vexabatur, ea tempestate praefectus, irrationabiliter plane; nec enim per eum steterat quo minus tempore congruo alimenta navibus veherentur, quas maris casus asperiores solitis ventorumque procellae reflantium, delatas in proximos sinus, introire portum Augusti discriminum magnitudine perterrebant.", "st": "19.10"}, {"sp": "N", "t": "Quocirca idem saepe praefectus seditionibus agitatus, ac plebe iam saeviente immanius, quoniam verebatur impendens exitium, ab omni spe tuendae salutis exclusus, ut aestimabat, tumultuanti acriter populo, sed accidentia considerare sueto prudenter, obiecit parvulos filios, et lacrimans", "st": "19.10"}, {"sp": "N", "t": "“En” inquit “cives vestri (procul omen dii caelestes avertant!) eadem perlaturi vobiscum, ni fortuna affulserit laetior. Si itaque his abolitis nil triste accidere posse existimatis, praesto in potestate sunt vestra.” Qua miseratione vulgus ad clementiam suapte natura proclive, lenitum conticuit, aequanimiter venturam operiens sortem.", "st": "19.10"}, {"sp": "N", "t": "Moxque divini arbitrio numinis, quod auxit ab incunabulis Romam, perpetuamque fore spopondit, dum Tertullus apud Ostia in aede sacrificat Castorum, tranquillitas mare mollivit, mutatoque in austrum placidum vento, velificatione plena portum naves ingressae, frumentis horrea referserunt.", "st": "19.10"}, {"sp": "N", "t": "Inter haec ita ambigua, Constantium Sirmi etiam tum hiberna quiete curantem, permovebant nuntii metuendi et graves, indicantes id quod tune magnopere formidabat, Limigantes Sarmatas, quos expulisse paternis avitisque sedibus dominos suos ante monstravimus, paulatim posthabitis locis quae eis anno praeterito utiliter sunt destinata, ne (ut sunt versabiles) aliquid molirentur inicum, regiones confines limitibus occupasse, vagarique licentius genuine more (ni pellerentur,) omnia turbaturos.", "st": "19.11"}, {"sp": "N", "t": "Quae superbius incitanda prope diem imperator dilato negotio credens, coacta undique multitudine militis ad bella promptissimi, nec dum adulto vere ad procinctum egressus est gemina consideratione alacrior, quod expletus praedarum opimitate exercitus, aestate nuper emensa, similium spe fidenter in effectus animabitur prosperos, quodque Anatolio regente tune per Illyricum praefecturam, necessaria cuncta, vel ante tempus coacta, sine ullius dispendiis affluebant.", "st": "19.11"}, {"sp": "N", "t": "Nec enim dispositionibus umquam alterius praefecturae (ut inter omnes constat) ad praesens Arctoae provinciae bonis omnibus floruerunt, correctione titubantium benevola et sollerti, vehiculariae rei iacturis ingentibus, quae clausere domos innumeras, et censuali professione speciosa fiducia relevatae; indemnesque deinde et innoxii earum incolae partium, querellarum sopitis materiis viverent, ni postea exquisitorum detestanda nomina titulorum, per offerentes suscipientesque criminose in maius exaggerata, his propugnare sibi nitentibus potestates, illis attenuatis omnium opibus, se fore sperantibus tutos, ad usque proscriptiones miserorumque suspendia pervenerunt.", "st": "19.11"}, {"sp": "N", "t": "Rem igitur emendaturus urgentem, profectus cum instrumentis ambitiosis, imperator (ut dictum est) Valeriam venit, partem quondam Pannoniae, sed ad honorem Valeriae Diocletiani filiae et institutam et ita cognominatam, sub pellibusque exercitu diffuso per Histri fluminis margines, barbaros observabat ante adventum suum amicitiae velamento, Pannonias furtim vastandas, invadere hiemis durissimo cogitantes, cum nec dum solutae vernis caloribus nives amnem undique pervium faciunt, nostrique pruinis subdivales moras difficile tolerabunt.", "st": "19.11"}, {"sp": "N", "t": "Confestim itaque missis ad Limigantes duobus tribunis cum interpretibus singulis, explorabat modestius percunctando, quam ob rem relictis laribus post pacem et foedera petentibus attributa, ita palarentur per varia, limitesque contra interdicta pulsarent.", "st": "19.11"}, {"sp": "N", "t": "Qui vana quaedam causantes et irrita, pavore adigente mentiri, principem exorabant in veniam, obsecrantes ut simultate abolita, transmisso flumine ad eum venire permitterentur, docturi quae sustinerent incommoda, paratique intra spatia orbis Romani (si id placuerit) terras suscipere longe discretas, ut diuturno otio involuti, et Quietem colentes (tamquam salutarem deam) tributariorum onera subirent et nomen.", "st": "19.11"}, {"sp": "N", "t": "His post reditum tribunorum compertis, imperator exsultans, ut negotio quod rebatur inexplicabile sine ullo pulvere consummando, cunctos admisit, aviditate plus habendi incensus, quam adulatorum cohors augebat, id sine modo strepentium, quod externis sopitis, et ubique pace composita, proletarios lucrabitur plures, et tirocinia cogere poterit validissima: aurum quippe gratanter provinciales pro corporibus dabunt, quae spes rem Romanam aliquotiens aggravavit.", "st": "19.11"}, {"sp": "N", "t": "Proinde vallo prope Acimincum locato, celsoque aggere in speciem tribunalis erecto, naves vehentes quosdam legionarios expedites alveum fluminis proximum ripis observare sunt iussae, cum Innocentio quodam agrimensore, huius auctore consilii, ut si barbaros tumultuare sensissent, aliorsum intentos post terga pervaderent improvisi.", "st": "19.11"}, {"sp": "N", "t": "Quae Limigantes licet properari sentirent, nihil tamen praeter preces fingentes, stabant incurvi, longe alia quam quae gestu praeferebant et verbis altis mentibus perpensantes.", "st": "19.11"}, {"sp": "N", "t": "Visoque imperatore ex alto suggestu, iam sermonem parante lenissimum, meditanteque alloqui velut morigeros iam futuros, quidam ex illis, furore percitus truci, calceo suo in tribunal contorto, “Marha marha” (quod est apud eos signum bellicum) exclamavit, eumque secuta incondita multitudo, vexillo elato repente barbarico, ululans ferum, in ipsum principem ferebatur.", "st": "19.11"}, {"sp": "N", "t": "Qui cum ex alto despiciens, plena omnia discurrentis turbae cum missilibus vidisset, retectisque gladiis et verrutis iam propinquante pernicie, externis mixtus et suis, ignotusque dux esset an miles, quia neque cunctandi aderat tempus, neque cessandi, equo veloci impositus, cursu effuso evasit.", "st": "19.11"}, {"sp": "N", "t": "Stipatores tamen pauci dum ignis more inundantes conabantur arcere, aut vulnerati interierunt, aut ponderibus superruentium solis afflicti, sellaque regalis cum aureo pulvinari, nullo vetante, direpta est.", "st": "19.11"}, {"sp": "N", "t": "Mox autem audito, quod ad ultimum paene tractus exitium, in abrupto staret adhuc imperator, antiquissimum omnium exercitus ratus eum iuvare (nondum enim exemptum periculis aestimavit salutis) fastu fidentior, licet ob procursionem subitam semitectus, sonorum et Martium frendens, barbarorum mori obstinatorum catervis semet immersit.", "st": "19.11"}, {"sp": "N", "t": "Et quia virtute dedecus purgatura, ardens copia nostrorum erupit, iras in hostem perfidum parans, obvia quaeque obtruncabat, sine parsimonia vivos conculcans et semineces et peremptos; et antequam exsatiaret caedibus barbaricis manus, acervi constipati sunt mortuorum.", "st": "19.11"}, {"sp": "N", "t": "Urgebantur enim rebelles, aliis trucidatis, aliis terrore disiectis, quorum pars spem vitae cassis precibus usurpando multiplicatis ictibus caedebantur, postque deletos omnes in receptum canentibus lituis, nostri quoque licet rari videbantur exanimes, quos impetus conculcaverat vehemens, aut furori resistentes hostili, lateraque nudantes intecta, ordo fatalis absumpsit.", "st": "19.11"}, {"sp": "N", "t": "Mors tamen eminuit inter alios Cellae Scutariorum tribuni, qui inter confligendi exordia, primus omnium in medios semet Sarmatarum globos immisit.", "st": "19.11"}, {"sp": "N", "t": "Post quae tam saeva, digestis pro securitate limitum quae rationes monebant urgentes, Constantius Sirmium redit, ferens de hoste fallaci vindictam, et maturatis quae necessitates temporis poscebant instantes, egressus exinde Constantinopolim petit, ut Orienti iam proximus, cladibus apud Amidam mederetur acceptis, et redintegrato supplementis exercitu, impetus regis Persarum pari virium robore cohiberet, quem constabat (ni caelestis ratio impensiorque repelleret cura multorum) Mesopotamia relicta post terga, per extenta spatia signa moturum.", "st": "19.11"}, {"sp": "N", "t": "Inter has tamen sollicitudines, velut ex recepto quodam antiquitus more, ad vicem bellorum civilium, inflabant litui quaedam colorata laesae crimina maiestatis, quorum exsecutor et administer, saepe dictus Tartareus ille notarius missus est Paulus, qui peritus artium cruentarum, ut lanista ex commerciis libitinae vel ludi, ipse quoque ex eculeo vel carnifice quaestum fructumque captabat.", "st": "19.12"}, {"sp": "N", "t": "Ut enim erat obstinatum fixumque eius propositum ad laedendum, ita nec furtis abstinuit, innocentibus exitialis causas affingens, dum in calamitosis stipendiis versaretur.", "st": "19.12"}, {"sp": "N", "t": "Materiam autem in infinitum quaestionibus extendendis dedit occasio vilis et parva. Oppidum est Abydum in Thebaidis partis situm extremo. Hic Besae dei localiter appellati, oraculum quondam futura pandebat, priscis circumiacentium regionum caerimoniis solitum coli.", "st": "19.12"}, {"sp": "N", "t": "Et quoniam quidam praesentes, pars per alios desideriorum indice missa scriptura, supplicationibus expresse conceptis, consulta numinum scitabantur, chartulae sive membranae, continentes quae petebantur, post data quoque responsa, interdum remanebant in fano.", "st": "19.12"}, {"sp": "N", "t": "Ex his aliqua ad imperatorem maligne sunt missa, qui (ut erat angusti pectoris) obsurdescens in aliis etiam nimium seriis, in hoc titulo ima (quod aiunt) auricula mollior, et suspicax et minutus, acri felle concaluit; statimque ad Orientem ocius ire monuit Paulum, potestate delata, ut instar ducis rerum experientia clari, ad arbitrium suum audiri efficeret causas.", "st": "19.12"}, {"sp": "N", "t": "Datumque est negotium Modesto.(etiam tum per Orientem comiti) apto ad haec et similia. Hermogenes enim Ponticus ea tempestate praefectus praetorio, ut lenioris ingenii, spernebatur.", "st": "19.12"}, {"sp": "N", "t": "Perrexit (ut praeceptum est) Paulus funesti furoris et anhelitus plenus, dataque calumniae indulgentia plurimis, ducebantur ab orbe prope terrarum, iuxta nobiles et obscuri, quorum aliquos vinculorum afflixerant nexus, alios claustra poenalia consumpserunt.", "st": "19.12"}, {"sp": "N", "t": "Et electa est speetatrix suppliciorum feralium civitas in Palaestina Scythopolis, gemina ratione visa magis omnibus opportuna, quod secretior est et inter Antiochiam Alexandriamque media, unde multi plerumque ad crimina trahebantur.", "st": "19.12"}, {"sp": "N", "t": "Ductus est itaque inter primos Simplicius, Philippi filius, ex praefecto et consule, reus hac gratia postulatus, quod super adipiscendo interrogasse dicebatur imperio, perque elogium principis torqueri praeceptus, qui in his casibus nec peccatum aliquando pietati dederat nec erratum, fato quodam arcente, corpore immaculato lata fuga damnatus est.", "st": "19.12"}, {"sp": "N", "t": "Dein Parnasius (ex praefecto Aegypti) homo simplicium morum, eo adductus periculi, ut pronuntiaretur capitis reus, itidem pulsus est in exsilium, saepe auditus multo antehac rettulisse, quod cum Patras Achaicum oppidum, ubi genitus habuit larem, impetrandae causa cuiusdam relinqueret potestatis, per quietem deducentia se habitus tragici figmenta viderat multa.", "st": "19.12"}, {"sp": "N", "t": "Andronicus postea, studiis liberalibus et claritudine carminum notus, in iudicium introductus cum secura mente nullis suspicionibus urgeretur, purgando semet fidentius, absolutus est.", "st": "19.12"}, {"sp": "N", "t": "Demetrius itidem Cythras cognomento philosophus, grandaevus quidem sed corpore durus et animo, sacrificasse aliquotiens confutatus, infitiari non potuit, asserens propitiandi causa numinis haec a prima adulescentia factitasse, non temptandi sublimiora scrutatis; nec enim quemquam id noverat affectare. Diu itaque adhaerens eculeo, cum fiducia gravi fundatus, nequaquam varians eadem oraret intrepidus, Alexandriam (unde oriebatur) innoxius abire permissus est.", "st": "19.12"}, {"sp": "N", "t": "Et hos quidem aliosque paucos aequa sors, veritatis adiutrix, periculis eximit abruptis. Criminibus vero serpentibus latius, per implicates nexus sine fine distentos, quidam corporibus laniatis exstinguebantur, alii poenis ulterioribus damnati sunt bonis ereptis, Paulo succentore fabularum crudelium, quasi e promptuaria cella, fallaciarum et nocendi species suggerente complures, cuius ex nutu (prope dixerim) pendebat incedentium omnium salus.", "st": "19.12"}, {"sp": "N", "t": "Nam siqui remedia quartanae vel doloris alterius collo gestaret, sive per monumentum transisse vesperi, malivolorum argueretur indiciis, ut veneficus, sepulchrorumque horrores, et errantium ibidem animarum ludibria colligens vana, pronuntiatus reus capitis interibat.", "st": "19.12"}, {"sp": "N", "t": "Et prorsus ita res agebatur, quasi Clarum, Dodonaeas arbores, et effata Delphorum olim sollemnia, in imperatoris exitium sollicitaverint multi.", "st": "19.12"}, {"sp": "N", "t": "Unde blanditiarum taetra commenta, palatina cohors exquisite confingens, immunem eum fore malorum communium asserebat, fatum eius vigens semper et praesens in abolendis adversa conantibus eluxisse, vocibus magnis exclamans.", "st": "19.12"}, {"sp": "N", "t": "Et inquisitum in haec negotia fortius, nemo qui quidem recte sapiat reprehendet. Nec enim abnuimus salutem legitimi principis, propugnatoris bonorum et defensoris, unde salus quaeritur aliis, consociato studio muniri debere cunctorum; cuius retinendae causa validius, ubi maiestas pulsata defenditur, a quaestionibus vel cruentis, nullam Corneliae leges exemere fortunam.", "st": "19.12"}, {"sp": "N", "t": "Sed exsultare maestis casibus effrenate non decet, ne videantur licentia regi subiecti, non potestate. Imitandus sit Tullius, cum parcere vel laedere potuisset, ut ipse affirmat, ignoscendi quaerens causas, non puniendi occasiones, quod iudicis lenti et considerati est proprium.", "st": "19.12"}, {"sp": "N", "t": "Tunc apud Daphnen, amoenum illud et ambitiosum Antioohiae suburbanum, visu relatuque horrendum natum est monstrum, infans ore gemino cum dentibus binis et barba, quattuorque oculis, et brevissimis duabus auriculis, qui partus ita distortus praemonebat rem publicam in statum verti deformem.", "st": "19.12"}, {"sp": "N", "t": "Nascuntur huius modi saepe portenta, indicantia rerum variarum eventus, quae quoniam non expiantur, ut apud veteres publice, inaudita praetereunt et incognita.", "st": "19.12"}, {"sp": "N", "t": "His temporibus Isauri diu quieti post gesta quae superior continet textus, temptatumque Seleuciae civitatis obsidium, paulatim reviviscentes, ut solent verno tempore foveis exsilire serpentes, saltibus degressi scrupulosis et inviis, confertique in cuneos densos per furta et latrocinia finitimos afflictabant, praetenturas militum (ut montani) fallentes, perque rupis et dumeta ex usu facile discurrentes.", "st": "19.13"}, {"sp": "N", "t": "Ad quos vi vel ratione sedandos Lauricius, adiecta comitis dignitate, missus est rector, homo civilis prudentiae, qui minis potius quam acerbitate pleraque correxit, adeo ut eo diu provinciam obtinente, nihil accideret, quod animadversione dignum aestimaretur.", "st": "19.13"}], []);})();
